//! Tests for `engine::encounter`.
//!
//! A child module of `encounter` declared with `#[path]`, so everything
//! here reads through `use super::*` exactly as it did when it lived at
//! the bottom of that file. Nothing about visibility or scope changed;
//! what changed is that `encounter.rs` is now twelve thousand lines
//! instead of eighty thousand, of which sixty-eight thousand were this
//! module. A file that size is one nobody opens on purpose — greps
//! return it for everything, and the engine it is testing was buried
//! under its own test suite six times over.

use super::*;
use crate::actions::action_template::Action;
use crate::conditions::ConditionTimer;
use crate::engine::side_effects::ApplicableSideEffect;
use crate::actors::creatures::skeletons::SKELETON_TEMPLATE;
use crate::actors::creatures::slimes::SLIME_TEMPLATE;
use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
use crate::engine::actor_gen::ActorGenParams;
use crate::engine::terrain::TerrainInfo;
use crate::engine::terrain_gen::TerrainGenParams;
use crate::engine::types::AbilityScoreType;
use crate::engine::zones::{ZoneContact, ZoneEffect, ZoneMotion};

/// Builds a tiny encounter with no actors and a hand-crafted terrain
/// grid so LOS can be tested deterministically (terrain_gen randomness
/// would otherwise make assertions seed-dependent).
fn ei_with_terrain(width: usize, height: usize, walls: &[(isize, isize)]) -> EncounterInstance {
    ei_with_terrain_seeded(width, height, walls, 0)
}

/// Seed-parameterized `ei_with_terrain`, for the tests that sweep a
/// range of seeds because the behavior under test rides a die roll
/// (a save-or-condition install, a to-hit). Those tests each used
/// to open-code the `TerrainGenParams` / `ActorGenParams` /
/// `from_params` / floor-fill dance inline; this is the same body
/// with the seed lifted to a parameter.
fn ei_with_terrain_seeded(
    width: usize,
    height: usize,
    walls: &[(isize, isize)],
    seed: u64,
) -> EncounterInstance {
    // Use generator to bootstrap, then overwrite the terrain map.
    let tp = TerrainGenParams {
        width,
        height,
        branch_depth: 0,
        branch_prob: 0.0,
    };
    let ap = ActorGenParams {
        cr_target: 0.0,
        n_teams: 0,
        pc_template: None,
        start_team: 0,
    };
    let mut e = EncounterInstance::from_params(&tp, &ap, Some(seed)).unwrap();
    e.terrain = vec![
        TerrainInfo {
            terrain_type: TerrainType::Floor,
        };
        width * height
    ];
    for &(x, y) in walls {
        let idx = e.idx(Coordinate::new(x, y)).unwrap();
        e.terrain[idx].terrain_type = TerrainType::Wall;
    }
    e
}

/// A row-major index cannot represent "one column past the right
/// edge" — the arithmetic lands on the next row's first tile. The
/// bound on `x` is what stops every reader built on `idx` from
/// answering a question about a tile nobody asked about, and stops
/// `find_path` from indexing one past the end of its distance
/// vector at the bottom-right corner.
#[test]
fn a_coordinate_past_the_edge_of_a_row_is_off_the_map() {
    let mut e = ei_with_terrain(10, 10, &[]);
    e.set_terrain_at(Coordinate::new(0, 6), TerrainType::Wall);
    // (10, 5) would wrap to (0, 6) under row-major arithmetic.
    assert!(!e.in_bounds(Coordinate::new(10, 5)));
    assert!(e.idx(Coordinate::new(10, 5)).is_err());
    assert!(
        e.terrain_at(Coordinate::new(10, 5)).is_none(),
        "and so it reports no tile rather than the next row's wall"
    );
    assert!(!e.set_terrain_at(Coordinate::new(10, 5), TerrainType::Floor));
    assert_eq!(
        e.terrain_at(Coordinate::new(0, 6)).map(|t| t.terrain_type),
        Some(TerrainType::Wall),
        "the wall on the next row is untouched"
    );
    // The far corner is the one that used to index one past the end.
    assert!(!e.in_bounds(Coordinate::new(10, 9)));
    assert!(e.in_bounds(Coordinate::new(9, 9)));
}

#[test]
fn los_clear_horizontal() {
    let e = ei_with_terrain(10, 10, &[]);
    assert!(e.has_line_of_sight(Coordinate::new(0, 5), Coordinate::new(9, 5)));
}

#[test]
fn los_blocked_by_wall_between() {
    let e = ei_with_terrain(10, 10, &[(5, 5)]);
    assert!(!e.has_line_of_sight(Coordinate::new(0, 5), Coordinate::new(9, 5)));
}

#[test]
fn los_endpoints_not_checked() {
    // Wall on the destination tile should not block LOS *to* that tile —
    // attacks target the tile, they don't pass through it.
    let e = ei_with_terrain(10, 10, &[(9, 5)]);
    assert!(e.has_line_of_sight(Coordinate::new(0, 5), Coordinate::new(9, 5)));
}

#[test]
fn los_diagonal_clear() {
    let e = ei_with_terrain(10, 10, &[]);
    assert!(e.has_line_of_sight(Coordinate::new(0, 0), Coordinate::new(7, 7)));
}

#[test]
fn los_diagonal_blocked() {
    // Wall right on the diagonal path should block.
    let e = ei_with_terrain(10, 10, &[(3, 3)]);
    assert!(!e.has_line_of_sight(Coordinate::new(0, 0), Coordinate::new(7, 7)));
}

#[test]
fn los_same_tile_is_visible() {
    let e = ei_with_terrain(10, 10, &[]);
    assert!(e.has_line_of_sight(Coordinate::new(2, 2), Coordinate::new(2, 2)));
}

#[test]
fn death_save_three_failures_kills() {
    let e = ei_with_terrain(10, 10, &[]);
    // Build a zombie actor for testing.
    // Use Fighter — only PCs roll death saves; monsters die outright.
    let mut z = ActorInstance::from_creature_template(
        &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut FastRandRoller::with_seed(1),
        0,
    )
    .unwrap();
    z.take_damage(z.hitpoints());
    assert!(z.is_dying());
    // Force three failures (rolling 2 each is < 10, +1 fail).
    for _ in 0..3 {
        let outcome = z.apply_death_save(2);
        if matches!(outcome, DeathSaveOutcome::Dead) {
            let _ = e; // silence unused
            return;
        }
    }
    panic!("expected Dead outcome after 3 failed saves");
}

#[test]
fn death_save_three_successes_stabilizes() {
    let _e = ei_with_terrain(10, 10, &[]);
    // Use Fighter — only PCs roll death saves; monsters die outright.
    let mut z = ActorInstance::from_creature_template(
        &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut FastRandRoller::with_seed(1),
        0,
    )
    .unwrap();
    z.take_damage(z.hitpoints());
    // Roll 3 successes (>= 10).
    for _ in 0..3 {
        z.apply_death_save(15);
    }
    assert!(z.is_stable(), "expected stable after 3 successes");
    assert!(!z.is_combat_active(), "stable actor isn't a combatant");
}

#[test]
fn nat_20_revives_at_one_hp() {
    // Use Fighter — only PCs roll death saves; monsters die outright.
    let mut z = ActorInstance::from_creature_template(
        &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut FastRandRoller::with_seed(1),
        0,
    )
    .unwrap();
    z.take_damage(z.hitpoints());
    let outcome = z.apply_death_save(20);
    assert_eq!(outcome, DeathSaveOutcome::Revived);
    assert_eq!(z.hitpoints(), 1);
    assert!(z.is_combat_active());
}

#[test]
fn damage_to_dying_adds_failure() {
    // Use Fighter — only PCs roll death saves; monsters die outright.
    let mut z = ActorInstance::from_creature_template(
        &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut FastRandRoller::with_seed(1),
        0,
    )
    .unwrap();
    z.take_damage(z.hitpoints());
    assert_eq!(z.death_save_record(), (0, 0));
    z.take_damage(1); // damage while dying = +1 failure
    assert_eq!(z.death_save_record().1, 1);
}

#[test]
fn multiattack_runs_sub_attack_n_times() {
    use crate::actions::monster_attacks::ZOMBIE_MULTISLAM;
    // Static-cast to verify the trait wiring; no roll done here.
    let action: &dyn Action = &*ZOMBIE_MULTISLAM;
    assert_eq!(action.name(), "multislam");
    assert_eq!(action.reach_tiles(), Some(1));
    assert!(!action.requires_los());
}

#[test]
fn opportunity_attack_fires_when_leaving_reach() {
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor, Resource};

    let mut e = ei_with_terrain(20, 20, &[]);
    // Two enemies whose Medium 2x2 footprints touch (gap = 0).
    let mover_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let reactor_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(7, 5), 1, 0)
        .unwrap();
    // Sanity: reactor has a reaction available.
    assert!(
        e.actors[&reactor_id].can_consume_resource(Resource::Reaction),
        "reactor should start with a reaction slot"
    );

    // Move the mover well out of reach.
    let move_effect = MoveActor {
        actor_id: mover_id,
        path: vec![Coordinate::new(15, 5)],
    };
    move_effect.apply(&mut e);

    // Whether the OA hit is RNG-dependent, but the reaction must be
    // consumed regardless (it's spent on attempt, not on hit).
    if e.actors.contains_key(&reactor_id) {
        assert!(
            !e.actors[&reactor_id].can_consume_resource(Resource::Reaction),
            "reactor should have spent their reaction"
        );
    }
}

/// 5e **Flyby**: *"the creature doesn't provoke an opportunity attack
/// when it flies out of an enemy's reach."*
///
/// Three moves, same board, same pair of tiles. A giant owl in the air
/// leaves for free; a giant owl the general flying rule has grounded
/// pays like anything else; and an ordinary flier without the trait pays
/// too. The last two are what make this a test of the *trait* rather
/// than of flight — a build that suppressed opportunity attacks for
/// everything airborne would pass the first assertion alone.
#[test]
fn a_flyby_creature_leaves_for_free_and_only_while_it_is_flying() {
    use crate::actors::creatures::giant_owls::GIANT_OWL_TEMPLATE;
    use crate::actors::creatures::stirges::STIRGE_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor, Resource};

    // Fly out of a zombie's reach and report whether the zombie got to
    // swing for it. `grounded` installs the condition that takes the
    // mover out of the sky by the general flying rule.
    fn provoked(template: &'static CreatureTemplate, grounded: bool) -> bool {
        let mut e = ei_with_terrain(20, 20, &[]);
        let mover = e
            .instantiate_creature(template, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let reactor = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(7, 5), 1, 0)
            .unwrap();
        if grounded {
            e.actors
                .get_mut(&mover)
                .unwrap()
                .add_condition(Condition::Incapacitated, ConditionTimer::Rounds(10));
        }
        e.reconcile_altitudes();
        assert_eq!(
            e.actors[&mover].is_airborne(),
            !grounded,
            "{} should be {} at the moment it moves",
            template.name,
            if grounded { "on the floor" } else { "in the air" }
        );
        assert!(e.actors[&reactor].can_consume_resource(Resource::Reaction));
        MoveActor {
            actor_id: mover,
            path: vec![Coordinate::new(15, 5)],
        }
        .apply(&mut e);
        e.actors
            .get(&reactor)
            .is_none_or(|a| !a.can_consume_resource(Resource::Reaction))
    }

    assert!(
        GIANT_OWL_TEMPLATE.features.contains(crate::actions::class_features::FLYBY_TAG),
        "the owl is the one that carries the trait"
    );
    assert!(
        !provoked(&GIANT_OWL_TEMPLATE, false),
        "an owl in the air flies out of reach for free"
    );
    assert!(
        provoked(&GIANT_OWL_TEMPLATE, true),
        "RAW says \"when it flies\" — a grounded owl is walking"
    );
    assert!(
        !STIRGE_TEMPLATE.features.contains(crate::actions::class_features::FLYBY_TAG),
        "the stirge is the control: it flies and does not have Flyby"
    );
    assert!(
        provoked(&STIRGE_TEMPLATE, false),
        "flying is not itself a licence to leave"
    );
}

#[test]
fn opportunity_attack_does_not_fire_when_staying_in_reach() {
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor, Resource};

    let mut e = ei_with_terrain(20, 20, &[]);
    let mover_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let reactor_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(7, 5), 1, 0)
        .unwrap();

    // Step 1 tile in-place — footprints still touch the reactor.
    let move_effect = MoveActor {
        actor_id: mover_id,
        path: vec![Coordinate::new(5, 6)],
    };
    move_effect.apply(&mut e);

    assert!(
        e.actors[&reactor_id].can_consume_resource(Resource::Reaction),
        "reactor's reaction should be intact — mover stayed in reach"
    );
}

#[test]
fn opportunity_attack_fires_per_step_on_multitile_path() {
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor, Resource};

    let mut e = ei_with_terrain(20, 20, &[]);
    // Reactor is far from BOTH the mover's start and end tiles. The
    // path between passes through reach. With the old endpoint-only
    // OA, this would silently bypass the reactor's threatened square.
    let mover_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(0, 5), 0, 0)
        .unwrap();
    let reactor_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(10, 5), 1, 0)
        .unwrap();
    assert!(e.actors[&reactor_id].can_consume_resource(Resource::Reaction));

    // Walk the mover step-by-step right past the reactor.
    let path: Vec<Coordinate> = (1..=15).map(|x| Coordinate::new(x, 5)).collect();
    let move_effect = MoveActor {
        actor_id: mover_id,
        path,
    };
    move_effect.apply(&mut e);

    if e.actors.contains_key(&reactor_id) {
        assert!(
            !e.actors[&reactor_id].can_consume_resource(Resource::Reaction),
            "reactor should have OA'd as the mover stepped past their reach"
        );
    }
}

/// 5e Fighter Battle Master **Evasive Footwork**: *"When you move, you
/// can expend one superiority die, rolling the die and adding the number
/// rolled to your AC until you stop moving."*
///
/// A walk that provokes spends one die; a walk that provokes nothing
/// spends none. The second half is the whole design — the maneuver is
/// fired lazily from the opportunity-attack dispatcher precisely so a
/// fighter does not pay for a guard against an empty room.
#[test]
fn evasive_footwork_is_spent_by_a_walk_that_provokes_and_not_by_one_that_does_not() {
    use crate::actions::class_features::{EVASIVE_FOOTWORK_TAG, SUPERIORITY_DICE_TAG};
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor};

    // A walk out of a zombie's reach.
    let mut e = ei_with_terrain(20, 20, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let _zombie = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(7, 5), 1, 0)
        .unwrap();
    let dice_before = e.actors[&fighter].feature_charges_remaining(SUPERIORITY_DICE_TAG);
    assert!(
        dice_before > 0 && e.actors[&fighter].has_passive_feature(EVASIVE_FOOTWORK_TAG),
        "the fighter chassis carries the maneuver and the pool that funds it"
    );
    MoveActor {
        actor_id: fighter,
        path: (6..=15).map(|x| Coordinate::new(x, 5)).collect(),
    }
    .apply(&mut e);
    // The once-per-turn mark rather than the pool count, because the
    // pool is shared: the zombie's swing may also have drawn a die for
    // Parry, which is exactly the trade the shared pool exists to force
    // and exactly what would make a die-count assertion here a test of
    // two features at once.
    assert!(
        e.actors[&fighter].once_per_turn_used(EVASIVE_FOOTWORK_TAG),
        "a walk that provokes spends the die"
    );
    assert!(
        e.actors[&fighter].feature_charges_remaining(SUPERIORITY_DICE_TAG) < dice_before,
        "and the die comes out of the superiority pool"
    );
    // The guard does not outlive the move: RAW's window closes when the
    // fighter stops, and a +4 that survived into the enemy round would
    // be a better Shield than Shield for one superiority die.
    assert!(
        !e.actors[&fighter].has_condition(Condition::EvasiveFootwork),
        "the guard comes down when the move ends"
    );

    // The same walk with nobody to provoke.
    let mut quiet = ei_with_terrain(20, 20, &[]);
    let lone = quiet
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let before = quiet.actors[&lone].feature_charges_remaining(SUPERIORITY_DICE_TAG);
    MoveActor {
        actor_id: lone,
        path: (6..=15).map(|x| Coordinate::new(x, 5)).collect(),
    }
    .apply(&mut quiet);
    assert!(
        !quiet.actors[&lone].once_per_turn_used(EVASIVE_FOOTWORK_TAG),
        "a walk nobody swings at never reaches for the die"
    );
    assert_eq!(
        quiet.actors[&lone].feature_charges_remaining(SUPERIORITY_DICE_TAG),
        before,
        "a walk nobody swings at costs nothing"
    );
}

/// One die buys the whole move, however many reach envelopes it leaves.
/// RAW's window is "until you stop moving", not "until the first
/// attacker misses" — so a fighter running a gauntlet of three zombies
/// pays once, and the once-per-turn ledger is what carries the guard
/// across the steps.
#[test]
fn evasive_footwork_pays_once_for_a_walk_past_several_reactors() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor};

    let mut e = ei_with_terrain(30, 30, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(1, 5), 0, 0)
        .unwrap();
    // Three separate reach envelopes strung along the corridor, spaced
    // so the walk leaves each of them in turn.
    for (i, x) in [5, 11, 17].into_iter().enumerate() {
        e.instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(x, 8), 1, i)
            .unwrap();
    }
    let log_before = e.messages().len();
    MoveActor {
        actor_id: fighter,
        path: (2..=22).map(|x| Coordinate::new(x, 5)).collect(),
    }
    .apply(&mut e);
    // The log rather than the pool, for the reason the previous test
    // gives: a parried swing draws from the same four dice, so the
    // count answers a question about two features. The spend line is
    // written once per die and never on a free re-raise.
    let spends = e.messages()[log_before..]
        .iter()
        .filter(|m| m.contains("evasive footwork"))
        .count();
    assert_eq!(
        spends, 1,
        "one superiority die for one move, whatever it walked past"
    );
    // The guard really was up for more than the step that raised it —
    // otherwise "pays once" would be true only because it fired once.
    let provokes = e.messages()[log_before..]
        .iter()
        .filter(|m| m.contains("opportunity-attacks"))
        .count();
    assert!(
        provokes > 1,
        "the gauntlet should have provoked more than once (saw {})",
        provokes
    );
}

/// The pool is what makes the maneuver a choice. A fighter who has
/// already spent every superiority die on primes walks out of reach with
/// nothing to give ground with.
#[test]
fn evasive_footwork_has_nothing_to_spend_once_the_pool_is_empty() {
    use crate::actions::class_features::SUPERIORITY_DICE_TAG;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor};

    let mut e = ei_with_terrain(20, 20, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let _zombie = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(7, 5), 1, 0)
        .unwrap();
    {
        let f = e.actors.get_mut(&fighter).unwrap();
        while f.feature_charges_remaining(SUPERIORITY_DICE_TAG) > 0 {
            f.spend_feature(SUPERIORITY_DICE_TAG);
        }
    }
    MoveActor {
        actor_id: fighter,
        path: (6..=15).map(|x| Coordinate::new(x, 5)).collect(),
    }
    .apply(&mut e);
    assert_eq!(
        e.actors
            .get(&fighter)
            .map(|f| f.feature_charges_remaining(SUPERIORITY_DICE_TAG)),
        Some(0),
        "an empty pool stays empty rather than going negative"
    );
    assert!(
        e.actors
            .get(&fighter)
            .is_none_or(|f| !f.has_condition(Condition::EvasiveFootwork)),
        "and no guard goes up on a die that was not there"
    );
}

#[test]
fn opportunity_attack_skipped_for_same_team() {
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor, Resource};

    let mut e = ei_with_terrain(20, 20, &[]);
    // Both on team 0 — allies don't OA each other.
    let mover_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let ally_id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(7, 5), 0, 0)
        .unwrap();

    let move_effect = MoveActor {
        actor_id: mover_id,
        path: vec![Coordinate::new(15, 5)],
    };
    move_effect.apply(&mut e);

    assert!(
        e.actors[&ally_id].can_consume_resource(Resource::Reaction),
        "ally should not have spent their reaction"
    );
}

#[test]
fn roll_save_passes_above_dc() {
    // DC 1 is below any possible (d20 + STR mod) total, so always passes.
    let mut e = ei_with_terrain(10, 10, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    for _ in 0..20 {
        assert!(e
            .roll_save(id, crate::engine::types::AbilityScoreType::Strength, 1)
            .passed());
    }
}

#[test]
fn roll_save_fails_above_max() {
    // DC 30 is above the maximum (d20=20 + zombie STR mod +1 = 21).
    let mut e = ei_with_terrain(10, 10, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    for _ in 0..20 {
        assert!(!e
            .roll_save(id, crate::engine::types::AbilityScoreType::Strength, 30)
            .passed());
    }
}

#[test]
fn apply_condition_adds_and_remove_clears() {
    use crate::conditions::Condition;
    use crate::engine::side_effects::{ApplicableSideEffect, ApplyCondition, RemoveCondition};

    let mut e = ei_with_terrain(10, 10, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(!e.actors[&id].has_condition(Condition::Prone));
    ApplyCondition {
        actor_id: id,
        condition: Condition::Prone,
        timer: crate::conditions::ConditionTimer::Permanent,
    }
    .apply(&mut e);
    assert!(e.actors[&id].has_condition(Condition::Prone));
    RemoveCondition {
        actor_id: id,
        condition: Condition::Prone,
    }
    .apply(&mut e);
    assert!(!e.actors[&id].has_condition(Condition::Prone));
}

#[test]
fn prone_allows_crawling_at_full_speed_budget() {
    use crate::conditions::Condition;
    let mut e = ei_with_terrain(10, 10, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&id].remaining_movement() > 0.0);
    e.actors
        .get_mut(&id)
        .unwrap()
        .add_condition(Condition::Prone, crate::conditions::ConditionTimer::Permanent);
    // 5e: prone creatures can crawl — their movement budget stays
    // intact but every tile costs double (handled by the Dijkstra
    // pathfinder's prone_factor). remaining_movement() no longer
    // zeros for Prone since crawling is legal.
    assert!(
        e.actors[&id].remaining_movement() > 0.0,
        "prone actor can still crawl"
    );
}

#[test]
fn acid_splash_only_hits_actors_adjacent_to_primary() {
    use crate::actions::monster_attacks::ACID_SPIT;
    use crate::actors::creatures::slimes::SLIME_TEMPLATE;
    let mut e = ei_with_terrain(25, 25, &[]);
    let caster = e
        .instantiate_creature(&SLIME_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let primary = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(10, 10), 1, 0)
        .unwrap();
    let adjacent = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(12, 10), 1, 1)
        .unwrap();
    let far = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 22), 1, 2)
        .unwrap();
    let caster_initial_hp = e.actors[&caster].hitpoints();
    let far_initial_hp = e.actors[&far].hitpoints();
    let adjacent_max_hp = e.actors[&adjacent].max_hitpoints();

    // Loop until weapon_attack rolls a hit (slime DEX +1 vs zombie
    // AC 8 = 70%; 200 attempts is overkill).
    let mut landed = false;
    for _ in 0..200 {
        let target_vec = vec![primary];
        let effects =
            ACID_SPIT.side_effects(&mut e, caster, Some(&target_vec), None, None);
        if effects.is_empty() {
            continue;
        }
        for eff in effects {
            eff.apply(&mut e);
        }
        landed = true;
        break;
    }
    assert!(landed, "200 attack rolls and never a hit — RNG miscalibrated");

    // Caster and the far zombie must be untouched. Adjacent should
    // have taken splash damage on the hit that landed.
    assert_eq!(e.actors[&caster].hitpoints(), caster_initial_hp);
    assert_eq!(e.actors[&far].hitpoints(), far_initial_hp);
    assert!(
        e.actors[&adjacent].hitpoints() < adjacent_max_hp,
        "adjacent zombie should have taken splash"
    );
}

