#[test]
fn stand_up_leaves_remaining_movement() {
    use crate::actions::default_actions::STAND_UP;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&id)
        .unwrap()
        .add_condition(Condition::Prone, crate::conditions::ConditionTimer::Permanent);
    let speed = e.actors[&id].speed();

    // Execute stand-up.
    let aei = ActionExecutionInfo::new(&*STAND_UP, id, None, None, None);
    assert!(aei.validate(&e));
    e.pop_prompt();
    e.push_action(aei);
    e.process_stack();

    // After standing the actor should still have half their speed
    // available for normal movement (stand costs half, leaving half).
    let actor = &e.actors[&id];
    assert!(!actor.has_condition(Condition::Prone));
    assert!(
        actor.can_consume_resource(Resource::Movement(speed / 2.0 - 0.01)),
        "actor should have ~half speed remaining after standing"
    );
    assert!(
        !actor.can_consume_resource(Resource::Movement(speed / 2.0 + 0.01)),
        "actor should not have more than half speed remaining"
    );
}

#[test]
fn stand_up_fails_without_enough_movement() {
    use crate::actions::default_actions::STAND_UP;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&id)
        .unwrap()
        .add_condition(Condition::Prone, crate::conditions::ConditionTimer::Permanent);
    let speed = e.actors[&id].speed();

    // Burn most of the actor's movement so less than half speed remains.
    e.actors
        .get_mut(&id)
        .unwrap()
        .consume_resource(Resource::Movement(speed / 2.0 + 5.0));

    // Standing costs half speed, but we no longer have that much.
    let aei = ActionExecutionInfo::new(&*STAND_UP, id, None, None, None);
    assert!(
        !aei.validate(&e),
        "stand should fail when movement budget is too low"
    );
}

#[test]
fn drop_prone_installs_prone_with_zero_cost() {
    use crate::actions::default_actions::DROP_PRONE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let speed_before = e.actors[&id].speed();

    // Drop-prone should validate while not prone.
    let aei = ActionExecutionInfo::new(&*DROP_PRONE, id, None, None, None);
    assert!(aei.validate(&e), "drop prone should validate when standing");
    // Zero-cost: no resources spent.
    assert!(aei.cost(&e).is_empty());

    e.pop_prompt();
    e.push_action(aei);
    e.process_stack();

    // Prone is installed; movement budget untouched (drop-prone is free).
    let after = &e.actors[&id];
    assert!(after.has_condition(Condition::Prone));
    assert!(
        after.can_consume_resource(Resource::Movement(speed_before - 0.01)),
        "drop prone shouldn't have spent any movement budget"
    );
}

