    let id = e
        .instantiate_creature(&SKELETON_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let max = e.actors[&id].max_hitpoints();
    DealDamage {
        actor_id: id,
        amount: 3,
        damage_type: DamageType::Bludgeoning,
    }
    .apply(&mut e);
