/// Pseudodragon sting on fail applies the Asleep condition via the
/// DC-11 CON save rider. Sweeps seeds to find a fail roll so the
/// rider path is observed.
#[test]
fn pseudodragon_sting_sleeps_on_save_fail() {
    use crate::actions::monster_attacks::PSEUDODRAGON_STING;
    use crate::actors::creatures::pseudodragons::PSEUDODRAGON_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::Condition;
    for seed in 0..40u64 {
        let mut e = ei_seeded(15, 15, &[], seed);
        // Zombie is CHARM-immune but not SLEEP-immune in this engine,
        // and has a low CON modifier, so a fail save is common.
        let p = e
            .instantiate_creature(&PSEUDODRAGON_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let z = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        let effects = PSEUDODRAGON_STING.side_effects(&mut e, p, Some(&vec![z]), None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        if e.actors
            .get(&z)
            .is_some_and(|a| a.has_condition(Condition::Asleep))
        {
            return;
        }
    }
    panic!("expected at least one save-fail across 40 seeds; sleep rider never fired");
}

/// Polar Bear / Lion / Fire Giant / Cyclops / Roc: instantiate cleanly
/// from their templates and surface the marquee marker field that
/// distinguishes each from neighboring entries on the CR ladder
/// (Pack Tactics on Lion, fire immunity on Fire Giant, etc.).
#[test]
fn polar_bear_lion_fire_giant_cyclops_roc_templates_instantiate() {
    use crate::actors::creatures::cyclopes::CYCLOPS_TEMPLATE;
    use crate::actors::creatures::fire_giants::FIRE_GIANT_TEMPLATE;
    use crate::actors::creatures::lions::LION_TEMPLATE;
    use crate::actors::creatures::polar_bears::POLAR_BEAR_TEMPLATE;
    use crate::actors::creatures::rocs::ROC_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(30, 30, &[]);
    let polar = e
        .instantiate_creature(&POLAR_BEAR_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&polar].hitpoints() > 0);
    assert_eq!(e.actors[&polar].size(), crate::engine::types::Size::Large);
    let lion = e
        .instantiate_creature(&LION_TEMPLATE, Coordinate::new(6, 2), 0, 1)
        .unwrap();
    assert!(e.actors[&lion].has_pack_tactics());
    let fg = e
        .instantiate_creature(&FIRE_GIANT_TEMPLATE, Coordinate::new(10, 2), 0, 2)
        .unwrap();
    // Fire Giant: fire immunity halves a 20 fire hit to 0.
    assert_eq!(e.actors[&fg].effective_damage(20, DamageType::Fire), 0);
    // Charmed-immune like the other giants.
    assert!(e.actors[&fg].is_immune_to_condition(Condition::Charmed));
    let cy = e
        .instantiate_creature(&CYCLOPS_TEMPLATE, Coordinate::new(15, 2), 0, 3)
        .unwrap();
    assert_eq!(e.actors[&cy].size(), crate::engine::types::Size::Huge);
    assert!((e.actors[&cy].cr() - 6.0).abs() < f32::EPSILON);
    let roc = e
        .instantiate_creature(&ROC_TEMPLATE, Coordinate::new(20, 2), 0, 4)
        .unwrap();
    assert!(e.actors[&roc].is_immune_to_condition(Condition::Charmed));
    assert!((e.actors[&roc].cr() - 11.0).abs() < f32::EPSILON);
}

/// A rider goes up with their flying mount and comes down with it —
/// RAW's *"if you and your mount fall, you take falling damage"*.
///
/// The case exists at all because a mount can now fly under its own
/// power: the pegasus, the griffon and the hippogriff are all mountable
/// and all have a flying speed on their stat block. Before
/// `supported_altitude_for` applied the rider redirect, a paladin would
/// ride a pegasus to cruising altitude while standing, as far as the
/// altitude sweep was concerned, on the floor — and would step off onto
/// thin air owing nothing when the pegasus came down.
///
/// Both of them are charged, separately, because they are two creatures
/// with two hit point pools. The pegasus is grounded by the general
/// flying rule rather than by Earthbind, so that this is a *fall* and
/// not a landing.
#[test]
fn a_rider_falls_with_the_pegasus_they_are_sitting_on() {
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
    use crate::actors::creatures::pegasi::PEGASUS_TEMPLATE;
    use crate::engine::falling::{FLIGHT_ALTITUDE_FT, fall_damage_dice};

    let mut e = ei_with_terrain(20, 20, &[]);
    let pegasus = e
        .instantiate_creature(&PEGASUS_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let paladin = e
        .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(7, 5), 0, 1)
        .unwrap();
    e.mount(paladin, pegasus).expect("a pegasus is mountable");
    e.reconcile_altitudes();

    assert_eq!(
        e.actors[&pegasus].altitude_ft(),
        FLIGHT_ALTITUDE_FT,
        "the pegasus flies"
    );
    assert_eq!(
        e.actors[&paladin].altitude_ft(),
        FLIGHT_ALTITUDE_FT,
        "and the rider is wherever the pegasus is"
    );
    assert!(
        !e.actors[&paladin].has_innate_flight(),
        "the paladin has no wings of their own — the height is borrowed"
    );

    let peg_hp = e.actors[&pegasus].hitpoints();
    let pal_hp = e.actors[&paladin].hitpoints();
    // The general flying rule, not Earthbind: a creature deprived of the
    // ability to move falls, and a pegasus does not hover.
    e.actors
        .get_mut(&pegasus)
        .unwrap()
        .add_condition(Condition::Incapacitated, ConditionTimer::Rounds(10));
    e.reconcile_altitudes();

    let pool = fall_damage_dice(FLIGHT_ALTITUDE_FT);
    for (id, before, who) in [
        (pegasus, peg_hp, "the pegasus"),
        (paladin, pal_hp, "the rider"),
    ] {
        let after = &e.actors[&id];
        assert_eq!(after.altitude_ft(), 0, "{who} should be on the floor");
        let lost = before - after.hitpoints();
        assert!(
            (pool.count..=pool.max_roll()).contains(&lost),
            "{who} should be charged for a {FLIGHT_ALTITUDE_FT} ft drop, not {lost}"
        );
    }
}

/// Pegasus / Winter Wolf / Triceratops / T-Rex / Carrion Crawler: each
/// instantiates cleanly from its template and surfaces the marquee
/// marker field (Celestial type on Pegasus, cold immunity on Winter
/// Wolf, huge size on Triceratops / T-Rex, etc.) that distinguishes
/// the entry from its CR-ladder neighbors.
#[test]
fn new_dinos_celestials_winter_creatures_instantiate() {
    use crate::actors::creatures::carrion_crawlers::CARRION_CRAWLER_TEMPLATE;
    use crate::actors::creatures::pegasi::PEGASUS_TEMPLATE;
    use crate::actors::creatures::triceratopses::TRICERATOPS_TEMPLATE;
    use crate::actors::creatures::tyrannosauruses::T_REX_TEMPLATE;
    use crate::actors::creatures::winter_wolves::WINTER_WOLF_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::types::{CreatureType, DamageType, Size};
    let mut e = ei_with_terrain(40, 30, &[]);
    let peg = e
        .instantiate_creature(&PEGASUS_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&peg].hitpoints() > 0);
    assert_eq!(e.actors[&peg].creature_type(), CreatureType::Celestial);
    let ww = e
        .instantiate_creature(&WINTER_WOLF_TEMPLATE, Coordinate::new(6, 2), 0, 1)
        .unwrap();
    // Cold immunity reduces a 20-cold hit to 0.
    assert_eq!(e.actors[&ww].effective_damage(20, DamageType::Cold), 0);
    assert!(e.actors[&ww].has_pack_tactics());
    assert!(e.actors[&ww].is_immune_to_condition(Condition::Charmed));
    let tri = e
        .instantiate_creature(&TRICERATOPS_TEMPLATE, Coordinate::new(10, 2), 0, 2)
        .unwrap();
    assert_eq!(e.actors[&tri].size(), Size::Huge);
    assert!((e.actors[&tri].cr() - 5.0).abs() < f32::EPSILON);
    let trex = e
        .instantiate_creature(&T_REX_TEMPLATE, Coordinate::new(15, 2), 0, 3)
        .unwrap();
    assert_eq!(e.actors[&trex].size(), Size::Huge);
    assert!((e.actors[&trex].cr() - 8.0).abs() < f32::EPSILON);
    let cc = e
        .instantiate_creature(&CARRION_CRAWLER_TEMPLATE, Coordinate::new(20, 2), 0, 4)
        .unwrap();
    assert_eq!(e.actors[&cc].size(), Size::Large);
    assert!((e.actors[&cc].cr() - 2.0).abs() < f32::EPSILON);
}

