/// Barbarian Rage: applies Raging, eats Bonus Action + the feature
/// flag, and confers BPS resistance via the damage pipeline.
#[test]
fn barbarian_rage_grants_resistance_and_consumes_feature() {
    use crate::actions::class_features::{RAGE, RAGE_TAG};
    use crate::actors::creatures::barbarians::BARBARIAN_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&bid).unwrap().reset_for_new_round();
    assert!(e.actors[&bid].feature_available(RAGE_TAG));
    let effects = RAGE.side_effects(&mut e, bid, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&bid].has_condition(Condition::Raging));
    assert!(!e.actors[&bid].feature_available(RAGE_TAG));
    // Resistance check: 10 slashing scales to 5 while raging.
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Slashing), 5);
    // Non-BPS damage is unaffected.
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Fire), 10);
}

/// Berserker Frenzy: while raging, bonus-action Frenzy grants a fresh
/// Action token. Gated on `FRENZY_TAG` passive feature + active
/// `Raging` condition; fails closed otherwise (the validator returns
/// false so the Action::execute pipeline skips it).
#[test]
fn berserker_frenzy_grants_action_when_raging() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{FRENZY, RAGE};
    use crate::actors::creatures::barbarians::BARBARIAN_TEMPLATE;
    use crate::engine::side_effects::Resource;
    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&bid).unwrap().reset_for_new_round();
    // Frenzy is invalid before rage is up — gates on Raging.
    assert!(!FRENZY.validate_input(&e, bid, None, None, None));
    // Enter rage so the Frenzy gate opens.
    let rage_effects = RAGE.side_effects(&mut e, bid, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    // Snapshot pre-frenzy action pool.
    let before = e.actors[&bid].action_slots();
    assert!(FRENZY.validate_input(&e, bid, None, None, None));
    let effects = FRENZY.side_effects(&mut e, bid, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    // Action pool grew by one — the granted Action waits for the
    // barbarian's follow-up melee swing this turn.
    let after = e.actors[&bid].action_slots();
    assert_eq!(after, before + 1);
    // Frenzy cost is a bonus action only — no slot consumption here
    // (consume happens through `Action::execute`, not direct side_effects).
    let cost = FRENZY.cost(&e, bid, None, None, None);
    assert_eq!(cost, vec![Resource::BonusAction]);
}

/// Frenzy is gated to barbarians who actually have the FRENZY_TAG
/// passive feature. A non-Berserker barbarian (e.g. Totem Warrior)
/// holds Rage but lacks Frenzy — the gate should bounce the action.
#[test]
fn frenzy_invalid_without_passive_feature() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{FRENZY, RAGE};
    use crate::actors::creatures::barbarians::TOTEM_BARBARIAN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&bid).unwrap().reset_for_new_round();
    // Enter rage so the Raging gate is satisfied — the only gate
    // left to fail is the passive feature lookup.
    let rage_effects = RAGE.side_effects(&mut e, bid, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    assert!(
        !FRENZY.validate_input(&e, bid, None, None, None),
        "frenzy should bounce on a Totem barbarian who lacks FRENZY_TAG"
    );
}

/// Bear Totem Spirit: while raging, the holder resists every damage
/// type EXCEPT psychic. Verifies the passive-feature gate composes
/// cleanly with the Raging condition and short-circuits cleanly when
/// either side is absent.
#[test]
fn bear_totem_raging_resists_all_damage_except_psychic() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::TOTEM_BARBARIAN_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&bid).unwrap().reset_for_new_round();
    // Pre-rage: only template resistances apply (none on Totem
    // Barbarian by default) — fire damage is unmitigated.
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Fire), 10);
    let rage_effects = RAGE.side_effects(&mut e, bid, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&bid].has_condition(Condition::Raging));
    // Raging + Bear Totem: physical damage halved (composes with
    // baseline Rage BPS resistance, same one-halving rule), and
    // every non-psychic typed damage is also halved.
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Slashing), 5);
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Fire), 5);
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Cold), 5);
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Lightning), 5);
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Radiant), 5);
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Necrotic), 5);
    // Psychic is the carve-out — Bear Totem explicitly excludes it.
    assert_eq!(e.actors[&bid].effective_damage(10, DamageType::Psychic), 10);
}

/// Cohort-shape refactor sanity: after promoting the Bear Totem
/// inline branch in `has_condition_resistance` into the shared
/// `RAGE_GATED_BROAD_RESISTANCES` cohort table, every gating axis
/// still fires identically. Locks the promoted cohort against a
/// mis-mapping regression by exercising the four boolean-product
/// combinations of (raging, has-tag) and the two type-axis cases
/// (in `types_except` slice → passes through, out-of-slice →
/// halved) end-to-end:
///   - !raging + tag: no halving (Rage gate off).
///   - raging + !tag: no halving (tag gate off; a baseline Totem
///     Barbarian without the Bear-flavor pick doesn't get the
///     broad resistance).
///   - raging + tag + Psychic (in the `types_except` slice): no
///     halving (the exclusion carve-out fires).
///   - raging + tag + Fire (out of the slice): halved.
///
/// Sibling to `condition_driven_cohorts_preserve_behavior_after_struct_shape_refactor`
/// on the "cohort-shape refactor sanity" lane — same test intent
/// (lock the pre-cleanup vs. post-cleanup behavior equivalence),
/// different cohort.
#[test]
fn rage_gated_broad_resistances_cohort_matches_prior_inline_behavior() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::{
        TOTEM_BARBARIAN_TEMPLATE, WOLF_TOTEM_BARBARIAN_TEMPLATE,
    };
    use crate::conditions::Condition;
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(15, 15, &[]);
    // Un-raged Bear Totem Barbarian (TOTEM_BARBARIAN_TEMPLATE is the
    // Bear Spirit flavor): no cohort hit — tag alone is insufficient
    // (the shared Rage gate is off).
    let bear_unraged = e
        .instantiate_creature(&TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert_eq!(
        e.actors[&bear_unraged].effective_damage(10, DamageType::Fire),
        10,
        "Bear Totem's broad resistance requires the Rage gate — tag alone doesn't halve"
    );
    // Raged Wolf Totem Barbarian (WOLF_TOTEM_BARBARIAN_TEMPLATE
    // carries WOLF_TOTEM_TAG, not BEAR_TOTEM_TAG): no cohort hit on
    // the broad-resistance lane (the tag gate is off; the baseline
    // Raging BPS resistance still fires via TYPED_RESISTANCE_CONDITIONS
    // but not the all-except-psychic clause). Fire — a typed
    // damage type outside the BPS trio — lands full since Wolf lacks
    // the Bear-flavor broad-resistance tag.
    let wolf_raged = e
        .instantiate_creature(&WOLF_TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(4, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&wolf_raged).unwrap().reset_for_new_round();
    let rage_effects = RAGE.side_effects(&mut e, wolf_raged, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&wolf_raged].has_condition(Condition::Raging));
    assert_eq!(
        e.actors[&wolf_raged].effective_damage(10, DamageType::Fire),
        10,
        "Raging alone (without the Bear tag) doesn't halve non-BPS typed damage — only the promoted cohort row's tag gate does"
    );
    // Raged Bear Totem Barbarian: cohort row fires. Fire is out of
    // the `types_except: &[Psychic]` slice → halved. Psychic is in
    // the slice → passes through unchanged (the carve-out
    // preserved from the pre-cleanup inline branch).
    e.actors.get_mut(&bear_unraged).unwrap().reset_for_new_round();
    let rage_effects = RAGE.side_effects(&mut e, bear_unraged, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&bear_unraged].has_condition(Condition::Raging));
    assert_eq!(
        e.actors[&bear_unraged].effective_damage(10, DamageType::Fire),
        5,
        "raging Bear Totem halves fire — cohort row fires (Fire is not in the types_except slice)"
    );
    assert_eq!(
        e.actors[&bear_unraged].effective_damage(10, DamageType::Psychic),
        10,
        "raging Bear Totem does NOT halve psychic — cohort row's types_except carve-out fires (Psychic IS in the slice)"
    );
}

/// Cohort-shape refactor sanity: after promoting the six-branch
/// if-chain in `condition_ac_bonus` into the shared
/// `CONDITION_AC_BONUSES` cohort table, every source-condition
/// row still contributes its expected signed delta identically to
/// the pre-cleanup inline branch. Locks the promoted cohort
/// against a mis-mapping regression by exercising every row:
///   - ShieldOfFaith → +2
///   - Shielded → +5
///   - Hasted → +2
///   - Slowed → -2 (only debuff-side row)
///   - WardingBonded → +1
///   - OtherworldlyGuised → +2
///
/// Plus the empty (no conditions) and stacking (Shield of Faith +
/// Shielded → +7) cases so the filter-map-sum walk shape is
/// exercised end-to-end.
///
/// Sibling to `rage_gated_broad_resistances_cohort_matches_prior_inline_behavior`
/// on the "cohort-shape refactor sanity" lane — same test intent
/// (lock the pre-cleanup vs. post-cleanup behavior equivalence),
/// different cohort (AC bonuses here vs. broad resistances there).
#[test]
fn condition_ac_bonuses_cohort_matches_prior_inline_behavior() {
    use crate::actors::creatures::commoners::COMMONER_TEMPLATE;
    use crate::conditions::ConditionTimer;

    let mut e = ei_with_terrain(15, 15, &[]);
    let a = e
        .instantiate_creature(&COMMONER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    // Empty baseline — no AC-bump conditions held.
    assert_eq!(e.actors[&a].condition_ac_bonus(), 0);

    // Each row's magnitude, in isolation. Each iteration installs
    // one condition, checks the delta, then removes it to reset
    // for the next iteration.
    let rows: &[(Condition, i32)] = &[
        (Condition::ShieldOfFaith, 2),
        (Condition::Shielded, 5),
        (Condition::Hasted, 2),
        (Condition::Slowed, -2),
        (Condition::WardingBonded, 1),
        (Condition::OtherworldlyGuised, 2),
    ];
    for (cond, expected) in rows {
        e.actors
            .get_mut(&a)
            .unwrap()
            .add_condition(*cond, ConditionTimer::Rounds(5));
        assert_eq!(
            e.actors[&a].condition_ac_bonus(),
            *expected,
            "{:?} should contribute {} AC in isolation",
            cond,
            expected
        );
        e.actors.get_mut(&a).unwrap().remove_condition(*cond);
        assert_eq!(e.actors[&a].condition_ac_bonus(), 0);
    }

    // Vertical stacking: Shield of Faith (+2) + Shielded (+5) →
    // +7 (both buff-side rows fire, deltas sum).
    e.actors
        .get_mut(&a)
        .unwrap()
        .add_condition(Condition::ShieldOfFaith, ConditionTimer::Rounds(5));
    e.actors
        .get_mut(&a)
        .unwrap()
        .add_condition(Condition::Shielded, ConditionTimer::Rounds(5));
    assert_eq!(e.actors[&a].condition_ac_bonus(), 7);

    // Horizontal (buff + debuff) stacking: Hasted (+2) + Slowed
    // (-2) → 0. Load-bearing check that the signed delta pattern
    // lets a debuff-side row (Slowed) sit on the same cohort as
    // the buff-side rows without a separate cohort.
    e.actors
        .get_mut(&a)
        .unwrap()
        .remove_condition(Condition::ShieldOfFaith);
    e.actors
        .get_mut(&a)
        .unwrap()
        .remove_condition(Condition::Shielded);
    e.actors
        .get_mut(&a)
        .unwrap()
        .add_condition(Condition::Hasted, ConditionTimer::Rounds(5));
    e.actors
        .get_mut(&a)
        .unwrap()
        .add_condition(Condition::Slowed, ConditionTimer::Rounds(5));
    assert_eq!(e.actors[&a].condition_ac_bonus(), 0);
}

/// Wolf Totem Spirit (Barbarian Path of the Totem Warrior, alt-flavor):
/// while raging, allies have advantage on melee attacks against any
/// enemy footprint-adjacent to the wolf totem barbarian. Probes the
/// `compute_attack_mode` aura: an ally with no other advantage source
/// reads Normal on an unrelated target, Advantage on the target the
/// wolf totem barbarian is anchoring.
#[test]
fn wolf_totem_grants_ally_melee_advantage_against_adjacent_target() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::WOLF_TOTEM_BARBARIAN_TEMPLATE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::conditions::Condition;
    let mut e = ei_with_terrain(15, 15, &[]);
    let wolf = e
        .instantiate_creature(&WOLF_TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    // Park the ally well away from any enemy so the "ranged-while-
    // adjacent" disadvantage doesn't confound the aura check below.
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(10, 10), 0, 0)
        .unwrap();
    // Anchored goblin: footprint-adjacent to the wolf totem barbarian.
    let anchored = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
        .unwrap();
    // Distant goblin: well outside the wolf totem's aura AND outside
    // the ally's own five-foot envelope, so the ranged sample at the
    // bottom reads the aura and nothing else.
    //
    // (13, 13) used to be far enough and is not: a Medium creature
    // occupies a 2×2 box here, so that tile sits a footprint gap of one
    // from the ally at (10, 10) — which is `MELEE_REACH`, which is what
    // "within 5 feet" means on this grid. The gate that reads it used
    // to ask for a gap of zero, i.e. actual contact, and the goblin
    // slipped through the difference.
    let distant = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(16, 16), 1, 0)
        .unwrap();
    // Pre-rage: the aura is dormant; both targets read Normal.
    assert_eq!(e.compute_attack_mode(ally, anchored, true), RollMode::Normal);
    assert_eq!(e.compute_attack_mode(ally, distant, true), RollMode::Normal);
    let rage_effects = RAGE.side_effects(&mut e, wolf, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&wolf].has_condition(Condition::Raging));
    // Raging: the ally now reads Advantage on the anchored goblin
    // (footprint-adjacent to the raging wolf totem) but still Normal
    // on the distant goblin (outside the aura).
    assert_eq!(
        e.compute_attack_mode(ally, anchored, true),
        RollMode::Advantage
    );
    assert_eq!(e.compute_attack_mode(ally, distant, true), RollMode::Normal);
    // Ranged attacks against the distant target read Normal — Wolf
    // Totem is melee-only RAW (the ranged check on `anchored` would
    // be confounded by the adjacent-enemy ranged disadvantage on
    // the fighter, so we sample the cleaner `distant` lane here).
    assert_eq!(e.compute_attack_mode(ally, distant, false), RollMode::Normal);
}

/// Wolf Totem doesn't help the totem barbarian themselves — RAW reads
/// "your friends," so a wolf totem barbarian attacking solo into an
/// adjacent enemy gets no advantage from their own aura.
#[test]
fn wolf_totem_does_not_grant_self_advantage() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::WOLF_TOTEM_BARBARIAN_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let wolf = e
        .instantiate_creature(&WOLF_TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
        .unwrap();
    let rage_effects = RAGE.side_effects(&mut e, wolf, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    // Self-targeted swing: aura must NOT fire — even though the wolf
    // totem barbarian is adjacent to the goblin, they're not their
    // own friend.
    assert_eq!(e.compute_attack_mode(wolf, g, true), RollMode::Normal);
}

/// Eagle Totem Spirit's Dash-as-bonus-action: gated on raging + the
/// passive feature. Outside of rage the validator must reject;
/// inside rage it must pass and grant movement on side-effect.
#[test]
fn eagle_dive_requires_raging_and_grants_movement() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{EAGLE_DIVE, RAGE};
    use crate::actors::creatures::barbarians::EAGLE_TOTEM_BARBARIAN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let eagle = e
        .instantiate_creature(&EAGLE_TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    e.actors.get_mut(&eagle).unwrap().reset_for_new_round();
    // Pre-rage: Eagle Dive is gated off.
    assert!(!EAGLE_DIVE.custom_validate_input(&e, eagle, None, None, None));
    let rage_effects = RAGE.side_effects(&mut e, eagle, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    // Raging: Eagle Dive is now valid and grants a fresh movement chunk.
    assert!(EAGLE_DIVE.custom_validate_input(&e, eagle, None, None, None));
    // Drain movement so we can verify the grant.
    e.actors.get_mut(&eagle).unwrap().zero_movement();
    assert_eq!(e.actors[&eagle].remaining_movement(), 0.0);
    let effects = EAGLE_DIVE.side_effects(&mut e, eagle, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    let after = e.actors[&eagle].remaining_movement();
    assert!(after > 0.0, "Eagle Dive should grant a fresh movement chunk");
}

/// Assassinate (Rogue Assassin level 3): the assassin rolls with
/// advantage on every attack against any creature that hasn't taken
/// a turn in this combat yet. Verifies the passive-feature gate
/// composes cleanly with the target-side `has_taken_turn_in_combat`
/// latch: pre-turn the assassin reads Advantage, post-turn the
/// target loses the eligibility and the assassin falls back to
/// Normal.
#[test]
fn assassinate_grants_advantage_against_pre_turn_targets() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::rogues::ASSASSIN_ROGUE_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let assassin = e
        .instantiate_creature(&ASSASSIN_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Park the goblin out of melee reach so the ranged-while-adjacent
    // disadvantage clause doesn't confound the ranged-lane sample.
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 2), 1, 0)
        .unwrap();
    // Fresh encounter: neither actor has taken a turn yet.
    assert!(!e.actors[&goblin].has_taken_turn_in_combat());
    // Assassinate fires on melee AND ranged — sample both lanes.
    assert_eq!(
        e.compute_attack_mode(assassin, goblin, true),
        RollMode::Advantage
    );
    assert_eq!(
        e.compute_attack_mode(assassin, goblin, false),
        RollMode::Advantage
    );
    // Goblin takes their turn → latch flips → Assassinate no longer
    // applies, mode falls back to Normal.
    e.actors.get_mut(&goblin).unwrap().mark_taken_turn_in_combat();
    assert_eq!(
        e.compute_attack_mode(assassin, goblin, true),
        RollMode::Normal
    );
    assert_eq!(
        e.compute_attack_mode(assassin, goblin, false),
        RollMode::Normal
    );
}

/// Assassinate is gated by the ASSASSINATE_TAG passive — a baseline
/// rogue without the subclass feature reads Normal even against a
/// pre-turn target.
#[test]
fn assassinate_requires_passive_feature_tag() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let rogue = e
        .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
        .unwrap();
    assert!(!e.actors[&goblin].has_taken_turn_in_combat());
    // Baseline Rogue lacks the tag — no advantage from Assassinate.
    assert_eq!(
        e.compute_attack_mode(rogue, goblin, true),
        RollMode::Normal
    );
}

/// `start_turn_for` latches the active actor's `has_taken_turn_in_combat`
/// flag — verifies the Assassinate eligibility lattice updates the
/// moment the target's slot comes up.
#[test]
fn start_turn_for_latches_has_taken_turn_in_combat() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Fresh spawn: the latch is off.
    assert!(!e.actors[&g].has_taken_turn_in_combat());
    // First skip_turn advances the queue and starts the goblin's
    // turn — the latch flips on.
    e.skip_turn();
    assert!(e.actors[&g].has_taken_turn_in_combat());
}

/// Long rest clears the `has_taken_turn_in_combat` latch — RAW
/// Assassinate is per-combat, and the engine treats a long rest as
/// the boundary between encounters. Without the reset an Assassin
/// would never re-arm the alpha-strike window in a second fight.
#[test]
fn long_rest_clears_has_taken_turn_in_combat() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&g).unwrap().mark_taken_turn_in_combat();
    assert!(e.actors[&g].has_taken_turn_in_combat());
    e.actors.get_mut(&g).unwrap().long_rest();
    assert!(!e.actors[&g].has_taken_turn_in_combat());
}

/// Tiger Totem Spirit (Barbarian Path of the Totem Warrior, Tiger
/// flavor): while raging, the holder's walking speed increases by
/// 10 ft. Verifies the passive-feature + Raging gate composes cleanly:
/// pre-rage the bonus is dormant, raging adds the +10 ft, and the
/// bonus drops back off when the Raging condition lifts.
#[test]
fn tiger_totem_raging_adds_ten_feet_of_speed() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::TIGER_TOTEM_BARBARIAN_TEMPLATE;
    use crate::conditions::Condition;
    let mut e = ei_with_terrain(15, 15, &[]);
    let tiger = e
        .instantiate_creature(&TIGER_TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let base = e.actors[&tiger].speed();
    // Pre-rage: no Tiger speed bonus.
    assert_eq!(e.actors[&tiger].speed(), base);
    let rage_effects = RAGE.side_effects(&mut e, tiger, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&tiger].has_condition(Condition::Raging));
    // Raging: +10 ft speed from Tiger Totem.
    assert_eq!(e.actors[&tiger].speed(), base + 10.0);
    // Drop the Rage condition: bonus must lift.
    assert!(e.actors.get_mut(&tiger).unwrap().remove_condition(Condition::Raging));
    assert_eq!(e.actors[&tiger].speed(), base);
}

/// Tiger Totem Spirit is gated to barbarians who actually hold the
/// TIGER_TOTEM_TAG passive — a Bear / Wolf / Eagle / baseline
/// barbarian Raging gets no speed bump from Tiger.
#[test]
fn tiger_totem_does_not_grant_speed_to_other_totems() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::EAGLE_TOTEM_BARBARIAN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let eagle = e
        .instantiate_creature(&EAGLE_TOTEM_BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let base = e.actors[&eagle].speed();
    let rage_effects = RAGE.side_effects(&mut e, eagle, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    // Eagle barbarian Raging gets no Tiger Totem speed bonus.
    assert_eq!(e.actors[&eagle].speed(), base);
}

/// Survivor (Champion lv18): at the start of the holder's turn, if
/// at or below half max HP, regain `5 + CON modifier` HP. Verifies
/// the regen lands at the turn-start hook, the half-HP gate
/// short-circuits when above half, and a downed Champion doesn't
/// auto-resurrect.
#[test]
fn champion_survivor_regens_at_turn_start_when_wounded() {
    use crate::actors::creatures::fighters::CHAMPION_TEMPLATE;
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(15, 15, &[]);
    let champ = e
        .instantiate_creature(&CHAMPION_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let max = e.actors[&champ].max_hitpoints();
    // Above-half HP: turn-start regen must NOT fire. Take a single
    // point of damage so we're below max but well above half.
    let _ = e.actors.get_mut(&champ).unwrap().take_typed_damage(1, DamageType::Slashing);
    let above_half = e.actors[&champ].hitpoints();
    e.actors.get_mut(&champ).unwrap().reset_for_new_round();
    assert_eq!(
        e.actors[&champ].hitpoints(),
        above_half,
        "Survivor should not regen when above half max HP"
    );
    // At-half-HP: take damage to drop to half, then verify regen.
    let current = e.actors[&champ].hitpoints();
    let drop_to_half = current.saturating_sub(max / 2);
    let _ = e.actors.get_mut(&champ).unwrap().take_typed_damage(drop_to_half, DamageType::Slashing);
    let before = e.actors[&champ].hitpoints();
    assert!(before <= max / 2 && before > 0);
    e.actors.get_mut(&champ).unwrap().reset_for_new_round();
    let after = e.actors[&champ].hitpoints();
    assert!(
        after > before,
        "Survivor should regen at turn-start when at half HP (before={}, after={})",
        before,
        after
    );
    // Downed Champion: regen must NOT fire — Survivor is
    // stabilization, not revival. Drop the Champion to 0 with a
    // single big hit.
    let now = e.actors[&champ].hitpoints();
    let _ = e.actors.get_mut(&champ).unwrap().take_typed_damage(now + 100, DamageType::Slashing);
    assert_eq!(e.actors[&champ].hitpoints(), 0);
    e.actors.get_mut(&champ).unwrap().reset_for_new_round();
    assert_eq!(
        e.actors[&champ].hitpoints(),
        0,
        "Survivor should not auto-resurrect a downed Champion"
    );
}

/// Improved Divine Smite (Paladin level 11+): every melee weapon hit
/// fires the +1d8 radiant rider. We probe with a seed loop (mirrors
/// the existing `divine_smite_primes_and_consumes_on_hit` test) so
/// we exercise a real attack-roll resolution; on each connect we
/// confirm an `improved divine smite` log line appears in the
/// rider's expected slot.
#[test]
fn improved_divine_smite_logs_on_melee_hit() {
    use crate::actions::action_template::Action;
    use crate::actions::monster_attacks::GREATSWORD;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
    let mut saw_rider = false;
    for seed in 0..40 {
        let mut e = ei_with_terrain(15, 15, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let pal = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        let log_before = e.messages().len();
        let tv = vec![g];
        let _ = GREATSWORD.side_effects(&mut e, pal, Some(&tv), None, None);
        let log_lines: Vec<&String> = e.messages()[log_before..].iter().collect();
        if log_lines.iter().any(|s| s.contains("improved divine smite")) {
            saw_rider = true;
            break;
        }
    }
    assert!(
        saw_rider,
        "expected an 'improved divine smite' log line on at least one connecting swing"
    );
}

