/// Relentless Rage (Barbarian lv11): a killing blow against a
/// raging barbarian rolls a CON save vs DC 10; on a pass HP pins
/// at 1, the DC bumps to 15, and the barbarian stays Active
/// instead of falling to Dying. We deterministically seed the CON
/// save with a strong actor (CON 18 → +4 mod, prof +3 = +7 vs DC
/// 10) so the save reliably passes on a connecting test seed.
#[test]
fn relentless_rage_pins_raging_barbarian_at_one_hp_on_pass() {
    use crate::actions::class_features::{RAGE, RELENTLESS_RAGE_TAG};
    use crate::actors::actor_template::HpState;
    use crate::actors::creatures::barbarians::BARBARIAN_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::DealDamage;
    use crate::engine::types::DamageType;

    // Seed sweep until a connecting save passes (high mod + low DC
    // makes this almost certain across a small handful of seeds).
    let mut observed_pass = false;
    for seed in 0..40 {
        let mut e = ei_with_terrain(15, 15, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let bid = e
            .instantiate_creature(&BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(
            e.actors[&bid].has_passive_feature(RELENTLESS_RAGE_TAG),
            "BARBARIAN_TEMPLATE should ship with Relentless Rage"
        );
        // Enter rage so the gate is open.
        let rage_effects = RAGE.side_effects(&mut e, bid, None, None, None);
        for ef in rage_effects {
            ef.apply(&mut e);
        }
        assert!(e.actors[&bid].has_condition(Condition::Raging));
        let dc_before = e.actors[&bid].relentless_rage_dc();
        assert_eq!(dc_before, 10, "DC starts at 10");
        let max = e.actors[&bid].max_hitpoints();
        // Killing-blow damage but NOT massive-damage instant kill
        // (overflow under max_hitpoints, so the Dying transition
        // is the one we want to intercept). Fire damage so Rage's
        // BPS resistance doesn't soak the hit down to a survivable
        // amount.
        DealDamage {
            actor_id: bid,
            amount: max,
            damage_type: DamageType::Fire,
        }
        .apply(&mut e);
        // Either passed (HP pinned at 1, DC bumped) or failed (Dying).
        let actor = e.actors.get(&bid).unwrap();
        if matches!(actor.hp_state(), HpState::Active) {
            assert_eq!(actor.hitpoints(), 1, "RR pins HP at 1 on pass");
            assert_eq!(
                actor.relentless_rage_dc(),
                15,
                "DC bumps by 5 after a successful pin"
            );
            observed_pass = true;
            break;
        }
    }
    assert!(
        observed_pass,
        "expected a Relentless Rage CON save to pass across 40 seeds"
    );
}

/// Relentless Rage requires the holder to actually BE raging. A
/// barbarian with the tag who hasn't entered Rage gets no save
/// intercept — the killing blow drops them normally.
#[test]
fn relentless_rage_does_not_fire_without_raging() {
    use crate::actors::actor_template::HpState;
    use crate::actors::creatures::barbarians::BARBARIAN_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::DealDamage;
    use crate::engine::types::DamageType;

    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Explicitly NOT raging.
    assert!(!e.actors[&bid].has_condition(Condition::Raging));
    let max = e.actors[&bid].max_hitpoints();
    // Use Fire so no template resistance soaks the killing blow.
    DealDamage {
        actor_id: bid,
        amount: max,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    // Without Raging, the intercept short-circuits → Dying.
    assert!(matches!(
        e.actors[&bid].hp_state(),
        HpState::Dying { .. }
    ));
}

/// Death Ward takes priority over Relentless Rage. Both intercepts
/// can catch the 0-HP transition; Death Ward is an active spell the
/// barbarian chose to maintain, so burning the racial / class
/// feature first would waste the slot. Verifies the priority order
/// inside `take_damage` (Death Ward bites in `take_damage` itself,
/// returning DamageOutcome::Reduced, so Relentless Rage's
/// post-take_damage hook never sees a Downed outcome to intercept).
#[test]
fn relentless_rage_does_not_fire_when_death_ward_intercepts_first() {
    use crate::actions::class_features::RAGE;
    use crate::actors::creatures::barbarians::BARBARIAN_TEMPLATE;
    use crate::conditions::{Condition, ConditionTimer};
    use crate::engine::side_effects::DealDamage;
    use crate::engine::types::DamageType;

    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Enter rage so Relentless Rage *could* fire if reached.
    let rage_effects = RAGE.side_effects(&mut e, bid, None, None, None);
    for ef in rage_effects {
        ef.apply(&mut e);
    }
    // Layer Death Ward on top. RR's DC should stay pristine since
    // Death Ward intercepts first.
    e.actors
        .get_mut(&bid)
        .unwrap()
        .add_condition(Condition::DeathWarded, ConditionTimer::Rounds(100));
    let dc_before = e.actors[&bid].relentless_rage_dc();
    let max = e.actors[&bid].max_hitpoints();
    // Fire damage — Rage's BPS resistance doesn't soak it, so the
    // intercept gates actually open.
    DealDamage {
        actor_id: bid,
        amount: max,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    // Death Ward fired (cleared) → HP at 1, RR untouched.
    let actor = e.actors.get(&bid).unwrap();
    assert!(!actor.has_condition(Condition::DeathWarded));
    assert_eq!(actor.hitpoints(), 1);
    assert_eq!(
        actor.relentless_rage_dc(),
        dc_before,
        "RR DC should not bump when Death Ward intercepts first"
    );
}

/// Short rest resets the Relentless Rage DC back to 10 (RAW:
/// "When you finish a short or long rest, the DC resets to 10").
/// Verifies both the short-rest and long-rest reset lanes.
#[test]
fn relentless_rage_dc_resets_on_rest() {
    use crate::actors::creatures::barbarians::BARBARIAN_TEMPLATE;

    let mut e = ei_with_terrain(15, 15, &[]);
    let bid = e
        .instantiate_creature(&BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let actor = e.actors.get_mut(&bid).unwrap();
    // Simulate three successful uses.
    actor.bump_relentless_rage_dc();
    actor.bump_relentless_rage_dc();
    actor.bump_relentless_rage_dc();
    assert_eq!(actor.relentless_rage_dc(), 25);
    actor.short_rest(&mut crate::engine::dice::FastRandRoller::with_seed(1));
    assert_eq!(
        actor.relentless_rage_dc(),
        10,
        "short rest resets DC to 10"
    );
    actor.bump_relentless_rage_dc();
    actor.long_rest();
    assert_eq!(
        actor.relentless_rage_dc(),
        10,
        "long rest resets DC to 10"
    );
}

/// Rogue Cunning Hide: bonus-action Hide that drops the Hidden flag.
///
/// Swept across seeds because the payload rolls: SRD 5.2's Hide is a
/// DC 15 Dexterity (Stealth) check, and a rogue misses it often enough
/// that a single seed is a coin flip rather than an assertion.
#[test]
fn cunning_hide_applies_hidden() {
    use crate::actions::class_features::CUNNING_HIDE;
    use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;
    let mut hid = false;
    for seed in 0..20u64 {
        let mut e = ei_with_terrain_seeded(10, 10, &[], seed);
        let id = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let cost = CUNNING_HIDE.cost(&e, id, None, None, None);
        assert!(cost.contains(&Resource::BonusAction));
        for ef in CUNNING_HIDE.side_effects(&mut e, id, None, None, None) {
            ef.apply(&mut e);
        }
        if e.actors[&id].has_condition(Condition::Hidden) {
            hid = true;
            // A successful hide records what it rolled — the DC anybody
            // searching for this rogue has to beat.
            assert!(
                e.actors[&id]
                    .hidden_check_total()
                    .is_some_and(|t| t >= crate::actions::default_actions::HIDE_DC),
                "seed {}: a successful hide keeps the total that made it",
                seed
            );
        }
    }
    assert!(hid, "the rogue never once cleared DC 15 in twenty tries");
}

/// 5e Ranger **Vanish** (lv14 class feature) — bonus-action Hide
/// gated on `VANISH_TAG`. Mirrors the Cunning Hide shape: same
/// `Hidden` install, same `BonusAction` cost, but the caster's
/// `has_passive_feature` gate short-circuits for a template that
/// doesn't ship the tag. Verifies:
///   - RANGER_TEMPLATE (ships VANISH_TAG) passes the validate gate.
///   - A ranger firing Vanish gets Hidden with a BonusAction cost.
///   - A rogue (no VANISH_TAG) fails the validate gate — so an
///     accidental multiclass action-list leak wouldn't fire.
#[test]
fn vanish_applies_hidden_gated_on_vanish_tag() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::VANISH;
    use crate::actors::creatures::rangers::RANGER_TEMPLATE;
    use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;
    let mut e = ei_with_terrain(10, 10, &[]);
    let ranger = e
        .instantiate_creature(&RANGER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let rogue = e
        .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    assert!(
        VANISH.custom_validate_input(&e, ranger, None, None, None),
        "ranger ships VANISH_TAG — validate passes"
    );
    assert!(
        !VANISH.custom_validate_input(&e, rogue, None, None, None),
        "rogue lacks VANISH_TAG — validate rejects"
    );
    let effects = VANISH.side_effects(&mut e, ranger, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&ranger].has_condition(Condition::Hidden));
    let cost = VANISH.cost(&e, ranger, None, None, None);
    assert!(cost.contains(&Resource::BonusAction));
}

/// The Hunter subclass overrides the ranger's `features` set
/// entirely (rather than extending it), so this test locks in that
/// VANISH_TAG rides the override — otherwise a Hunter ranger would
/// silently lose Vanish even though the paired action is still in
/// their action list.
#[test]
fn hunter_ranger_ships_vanish_tag() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{VANISH, VANISH_TAG};
    use crate::actors::creatures::rangers::HUNTER_RANGER_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let hunter = e
        .instantiate_creature(&HUNTER_RANGER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(
        e.actors[&hunter].has_passive_feature(VANISH_TAG),
        "hunter ranger inherits VANISH_TAG"
    );
    assert!(
        VANISH.custom_validate_input(&e, hunter, None, None, None),
        "hunter ranger can fire Vanish"
    );
}

/// Fighter Indomitable: setting the pending flag and watching
/// `roll_save` re-roll once on a fail. We force a fail by using a
/// high DC; the marker is consumed regardless of whether the
/// reroll lifts the result.
#[test]
fn indomitable_rerolls_failed_save_once() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::types::AbilityScoreType;
    let mut e = ei_with_terrain(10, 10, &[]);
    let id = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // `modifier + 20` is the highest DC a reroll can still clear,
    // so the initial roll fails on all but a natural 20 and the
    // reroll is worth firing. DC 40, which this fixture used to
    // use, is out of reach of any d20 — and the cohort no longer
    // spends a charge on a save it cannot rescue.
    let dc = e.actors[&id].save_modifier(AbilityScoreType::Dexterity) + 20;
    let mut fired = false;
    for seed in 0u64..32 {
        e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
        e.actors.get_mut(&id).unwrap().mark_indomitable_pending();
        let _ = e.roll_save(id, AbilityScoreType::Dexterity, dc);
        // The marker is consumed either way (no infinite rerolls).
        if !e.actors[&id].indomitable_pending() {
            fired = true;
            break;
        }
    }
    assert!(
        fired,
        "32 seeds should have produced at least one failure the reroll could answer"
    );
}

/// Spike Growth applies Spiked to enemies in the burst and
/// starts concentration.
#[test]
fn spike_growth_marks_enemies_and_concentrates() {
    use crate::actions::spells::SPIKE_GROWTH;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 8), 1, 0)
        .unwrap();
    let effects = SPIKE_GROWTH.side_effects(
        &mut e,
        wiz,
        None,
        Some(&vec![Coordinate::new(8, 8)]),
        None,
    );
    for ef in effects {
        ef.apply(&mut e);
    }
    // The thorns are ground, not a tag: nobody picks up a
    // condition, and standing still in them costs nothing.
    assert_eq!(e.zones().len(), 1);
    assert_eq!(e.actors[&goblin].hitpoints(), e.actors[&goblin].max_hitpoints());
    assert!(e.actors[&wiz].is_concentrating());
}

/// Spike Growth bills by the tile, and only for the tiles that are
/// actually thorny: crossing the patch costs a roll per step, and
/// walking on past it costs nothing.
#[test]
fn crossing_spike_growth_costs_a_roll_a_tile_and_leaving_it_costs_nothing() {
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, MoveActor};
    let mut e = ei_with_terrain(30, 30, &[]);
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(2, 10), 0, 0)
        .unwrap();
    e.install_zone(test_zone(
        Coordinate::new(8, 10),
        1,
        ZoneEffect::thorny(
            crate::engine::dice::Dice::new(2, 4),
            DamageType::Piercing,
        ),
    ));
    let before = e.actors[&ogre].hitpoints();
    // Three tiles, all of them thorny.
    MoveActor {
        actor_id: ogre,
        path: (5..=7).map(|x| Coordinate::new(x, 10)).collect(),
    }
    .apply(&mut e);
    let crossed = e.actors[&ogre].hitpoints();
    assert!(
        before - crossed >= 6,
        "three thorny tiles is three 2d4 rolls, not one ({} → {})",
        before,
        crossed
    );
    // Out the far side onto clean ground — the old model kept
    // billing here, because the thorns were stuck to the walker.
    MoveActor {
        actor_id: ogre,
        path: (12..=15).map(|x| Coordinate::new(x, 10)).collect(),
    }
    .apply(&mut e);
    assert_eq!(
        e.actors[&ogre].hitpoints(),
        crossed,
        "clean ground is free"
    );
}

/// Telekinesis: pulls the failed-save target and lifts them, also
/// starts concentration.
#[test]
fn telekinesis_lifts_and_pulls() {
    use crate::actions::spells::TELEKINESIS;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::conditions::Condition;
    // Use enough trials that one save fails — goblin has a low STR.
    let mut lifted = false;
    for seed in 0..30 {
        let mut e = ei_with_terrain(20, 20, &[]);
        // Vary the RNG path across attempts by burning `seed` rolls.
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 10), 1, 0)
            .unwrap();
        let tv = vec![g];
        let effects =
            TELEKINESIS.side_effects(&mut e, wiz, Some(&tv), None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        if e.actors[&g].has_condition(Condition::Lifted) {
            lifted = true;
            assert!(e.actors[&wiz].is_concentrating());
            break;
        }
    }
    assert!(lifted, "telekinesis never landed across 30 attempts");
}

