/// `passive_perception` folds in the Perception skill proficiency
/// for actors who have it. Without proficiency it's just `10 + WIS
/// modifier`; with it, it's `10 + WIS modifier + proficiency bonus`.
#[test]
fn passive_perception_includes_skill_proficiency() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::engine::types::Skill;
    let mut e = ei_with_terrain(10, 10, &[]);
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let actor = &e.actors[&g];
    // Baseline: WIS-mod-only check vs the helper.
    let wis_mod = actor.ability_modifier(AbilityScoreType::Wisdom);
    let proficient = actor.has_skill(Skill::Perception);
    let expected = 10 + wis_mod + if proficient { actor.proficiency_bonus() } else { 0 };
    assert_eq!(actor.passive_perception(), expected);
}

/// `roll_ability_check` adds the ability modifier and, optionally,
/// the proficiency bonus for an associated skill. The total is the
/// d20 roll plus that aggregate modifier.
#[test]
fn roll_ability_check_adds_modifier_and_proficiency() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Without a skill: total >= ability modifier + 1 (d20 floor),
    // <= ability modifier + 20 (d20 ceiling).
    let total = e.roll_ability_check(g, AbilityScoreType::Strength, None);
    let mod_str = e.actors[&g].ability_modifier(AbilityScoreType::Strength);
    assert!(
        total > mod_str && total <= mod_str + 20,
        "roll out of expected band: {} (mod {})",
        total,
        mod_str
    );
}

/// Every clause 5e writes as "…on ability checks" reaches the check
/// lane, and only the check lane. Poisoned is the debuff half, Rage
/// the buff half, and Rage is scoped to Strength — a raging
/// barbarian's Wisdom check is an ordinary roll.
#[test]
fn check_mode_reads_the_check_clauses_and_scopes_the_strength_ones() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert_eq!(
        e.compute_check_mode(g, AbilityScoreType::Strength),
        RollMode::Normal
    );
    e.actors
        .get_mut(&g)
        .unwrap()
        .add_condition(Condition::Poisoned, ConditionTimer::Permanent);
    assert_eq!(
        e.compute_check_mode(g, AbilityScoreType::Wisdom),
        RollMode::Disadvantage,
        "poisoned imposes disadvantage on ability checks"
    );
    e.actors
        .get_mut(&g)
        .unwrap()
        .remove_condition(Condition::Poisoned);
    e.actors
        .get_mut(&g)
        .unwrap()
        .add_condition(Condition::Raging, ConditionTimer::Permanent);
    assert_eq!(
        e.compute_check_mode(g, AbilityScoreType::Strength),
        RollMode::Advantage,
        "rage grants advantage on Strength checks"
    );
    assert_eq!(
        e.compute_check_mode(g, AbilityScoreType::Wisdom),
        RollMode::Normal,
        "rage says nothing about a Wisdom check"
    );
}

/// A Bardic Inspiration / Guidance die is worth +3 on an ability
/// check and is spent by it. The spend is the load-bearing half:
/// without it the same die would pay for a check *and* the swing
/// after it, which is exactly the bug the attack and save lanes
/// already guard against.
///
/// Guidance had no other lane at all — it installs `Inspired` and
/// its whole RAW effect is on ability checks, so before the check
/// lane existed a cast of it could not change a number in the game.
#[test]
fn an_inspiration_die_lands_on_a_check_and_is_spent_by_it() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&g)
        .unwrap()
        .add_condition(Condition::Inspired, ConditionTimer::Rounds(10));
    assert_eq!(e.actors[&g].condition_check_bonus(), 3);
    let mod_wis = e.actors[&g].ability_modifier(AbilityScoreType::Wisdom);
    let total = e.roll_ability_check(g, AbilityScoreType::Wisdom, None);
    assert!(
        total > mod_wis + 3 && total <= mod_wis + 3 + 20,
        "check total {} should carry the +3 die (mod {})",
        total,
        mod_wis
    );
    assert!(
        !e.actors[&g].has_condition(Condition::Inspired),
        "the check should have spent the die"
    );
}

/// The defender in a contest answers with whichever pairing they are
/// actually best at, and proficiency counts toward that comparison
/// rather than the ability modifier alone.
///
/// Two creatures at opposite ends of the STR/DEX axis pin both
/// branches: an ogre answers a shove by bracing (Athletics), a
/// goblin by twisting away (Acrobatics).
#[test]
fn a_contest_defender_answers_with_their_better_skill() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    use crate::engine::types::Skill;
    const OPTIONS: &[(AbilityScoreType, Skill)] = &[
        (AbilityScoreType::Strength, Skill::Athletics),
        (AbilityScoreType::Dexterity, Skill::Acrobatics),
    ];
    let mut e = ei_with_terrain(10, 10, &[]);
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 6), 1, 0)
        .unwrap();
    assert_eq!(
        e.best_check_option(ogre, OPTIONS).map(|(a, _)| a),
        Some(AbilityScoreType::Strength)
    );
    assert_eq!(
        e.best_check_option(goblin, OPTIONS).map(|(a, _)| a),
        Some(AbilityScoreType::Dexterity)
    );
    // Proficiency is a term in the comparison, not just the ability
    // modifier. The ogre is the case that proves it: offered its own
    // Strength without a skill against its (much worse) Dexterity
    // *with* a proficiency it holds, the bonus has to be able to
    // move the answer. Nothing in the game gives an ogre Acrobatics,
    // so the pin is on the arithmetic — the chosen pairing's total
    // is the maximum available.
    // Ties go to the earlier row, which is what lets a caller order
    // its options by preference. Two copies of the same pairing are
    // the cleanest way to ask.
    const TIED: &[(AbilityScoreType, Skill)] = &[
        (AbilityScoreType::Strength, Skill::Athletics),
        (AbilityScoreType::Strength, Skill::Acrobatics),
    ];
    assert_eq!(
        e.best_check_option(ogre, TIED).map(|(_, s)| s),
        Some(Skill::Athletics)
    );

    let best = e.best_check_option(ogre, OPTIONS).unwrap();
    let actor = &e.actors[&ogre];
    let score = |(ability, skill): &(AbilityScoreType, Skill)| {
        actor.ability_modifier(*ability)
            + if actor.has_skill(*skill) {
                actor.proficiency_bonus()
            } else {
                0
            }
    };
    assert_eq!(
        score(&best),
        OPTIONS.iter().map(score).max().unwrap(),
        "the chosen pairing should be the highest-scoring one on offer"
    );
}

/// The Hide action rolls the Stealth check it is named after, and a
/// creature proficient in Stealth collects the bonus. It used to
/// roll a Dexterity *saving throw*, which reads off an entirely
/// different set of modifiers and never once touched Stealth — while
/// `Search`, standing on the other side of the same contest, was
/// already folding that very proficiency into the DC.
#[test]
fn hiding_collects_the_stealth_proficiency_it_is_named_after() {
    use crate::actions::default_actions::HIDE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::engine::types::Skill;
    let mut e = ei_with_terrain(20, 20, &[]);
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(
        e.actors[&goblin].has_skill(Skill::Stealth),
        "the MM goblin is proficient in Stealth"
    );
    let before = e.messages().len();
    let effects = HIDE.side_effects(&mut e, goblin, None, None, None);
    for effect in effects {
        effect.apply(&mut e);
    }
    // The roll itself is a die, so the pin is on which roll it is:
    // the check lane names its skill in the log, and the save lane
    // has no skill to name.
    let logged: Vec<&String> = e.messages()[before..].iter().collect();
    assert!(
        logged.iter().any(|m| m.contains("(Stealth) check")),
        "hide should roll a Stealth check, got {:?}",
        logged
    );
    // And the roll carries the proficiency: floor and ceiling of the
    // band a proficient goblin's Stealth check can land in.
    let actor = &e.actors[&goblin];
    let expected = actor.ability_modifier(AbilityScoreType::Dexterity)
        + actor.proficiency_bonus();
    let total = e.roll_ability_check(
        goblin,
        AbilityScoreType::Dexterity,
        Some(Skill::Stealth),
    );
    assert!(
        total > expected && total <= expected + 20,
        "stealth check {} outside the proficient band around {}",
        total,
        expected
    );
}

/// The Luckstone's check half reaches the check, and the robe's DC half
/// reaches the DC.
///
/// Both are flat terms that arrive at expressions rather than at a
/// struct, which is the half a `total_item_bonuses()` assertion cannot
/// see: a field nothing reads sums correctly forever. The check is read
/// off the log's own breakdown, which is where every other flat term on
/// a d20 is already visible.
#[test]
fn the_flat_item_terms_reach_the_rolls_they_are_written_about() {
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::types::{AbilityScoreType, Skill};
    use crate::items::item_template::{ROBE_OF_THE_ARCHMAGI, STONE_OF_GOOD_LUCK};

    let mut e = ei_with_terrain(12, 12, &[]);
    let id = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();

    // The check: same seed, same actor, one stone of difference.
    let rolled = |e: &mut EncounterInstance, seed: u64| {
        e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
        e.roll_ability_check(id, AbilityScoreType::Dexterity, Some(Skill::Stealth))
    };
    let before: Vec<i32> = (0..8).map(|s| rolled(&mut e, s)).collect();
    e.actors.get_mut(&id).unwrap().pickup_item(&STONE_OF_GOOD_LUCK);
    let after: Vec<i32> = (0..8).map(|s| rolled(&mut e, s)).collect();
    for (seed, (b, a)) in before.iter().zip(&after).enumerate() {
        assert_eq!(
            a - b,
            1,
            "seed {seed}: the luckstone's +1 did not reach the check"
        );
    }

    // The DC: the expression every save-for-damage spell derives from.
    let base_dc = e.actors[&id].spell_save_dc(AbilityScoreType::Intelligence);
    e.actors
        .get_mut(&id)
        .unwrap()
        .pickup_item(&ROBE_OF_THE_ARCHMAGI);
    assert_eq!(
        e.actors[&id].spell_save_dc(AbilityScoreType::Intelligence),
        base_dc + 2
    );
}

/// The Sentinel Shield's Perception clause reaches the die, and reaches
/// only that skill's die.
///
/// The unit test beside the item pins the flag; this pins the wiring,
/// which is the half that could silently not exist —
/// `compute_check_mode` is handed an ability and never sees a skill, so
/// an implementation that put the clause there would pass every
/// assertion about the shield and hand the holder Advantage on six
/// skills.
///
/// Read off the log's own mode suffix rather than by counting outcomes:
/// the roll is a die, and what is being asserted is which shape it was
/// rolled in.
#[test]
fn the_sentinel_shields_perception_clause_reaches_the_right_die() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::types::{AbilityScoreType, Skill};
    use crate::items::item_template::SENTINEL_SHIELD;

    let mut e = ei_with_terrain(12, 12, &[]);
    let id = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let suffix_of = |e: &mut EncounterInstance, skill: Option<Skill>| {
        let before = e.messages().len();
        e.roll_ability_check(id, AbilityScoreType::Wisdom, skill);
        e.messages()[before..]
            .iter()
            .find(|m| m.contains("check"))
            .cloned()
            .unwrap_or_default()
    };

    assert!(!suffix_of(&mut e, Some(Skill::Perception)).contains("(adv)"));
    e.actors.get_mut(&id).unwrap().pickup_item(&SENTINEL_SHIELD);
    assert!(
        suffix_of(&mut e, Some(Skill::Perception)).contains("(adv)"),
        "the shield's Perception clause never reached the roll"
    );
    assert!(
        !suffix_of(&mut e, Some(Skill::Insight)).contains("(adv)"),
        "a Wisdom check of another skill picked the clause up"
    );
    assert!(
        !suffix_of(&mut e, None).contains("(adv)"),
        "a bare Wisdom check picked the clause up (sentinel shield)"
    );
}

/// The two ends of the Hide/Search contest, and the three items SRD 5.2
/// prints for them.
///
/// `Item::skill_check_advantages` shipped with one carrier and a note
/// saying the next item on the lane would name a different skill. Three
/// arrive at once: the Boots of Elvenkind and the Cloak of Elvenkind on
/// Stealth, the Eyes of the Eagle on Perception. The cloak is the
/// interesting one — it was already in the file carrying *half* of its
/// printed sentence, with the Stealth half dropped for want of this
/// lane.
///
/// What is pinned:
///   - each item's clause reaches the die of the skill it names, and
///     no other skill's die;
///   - advantage on the Hide roll is worth what it is worth in *this*
///     engine, which is not "hides more often" but "is found on a
///     higher number" — `resolve_hide_attempt` writes the successful
///     Stealth total down as the DC a Searcher must beat;
///   - two Stealth items together are one notch, not two, which is
///     5e's rule and has to survive `has_skill_check_advantage` being
///     an `any`.
#[test]
fn the_elvenkind_shelf_bends_the_two_checks_the_engine_actually_rolls() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::types::{AbilityScoreType, Skill};
    use crate::items::item_template::{
        BOOTS_OF_ELVENKIND, CLOAK_OF_ELVENKIND, EYES_OF_THE_EAGLE, Item,
    };

    let rolled_with = |carried: &[&'static Item], ability, skill| {
        let mut e = ei_with_terrain(12, 12, &[]);
        let id = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        for item in carried {
            e.actors.get_mut(&id).unwrap().pickup_item(item);
        }
        let before = e.messages().len();
        e.roll_ability_check(id, ability, skill);
        e.messages()[before..]
            .iter()
            .find(|m| m.contains("check"))
            .cloned()
            .unwrap_or_default()
    };
    let adv = |carried: &[&'static Item], ability, skill| {
        rolled_with(carried, ability, skill).contains("(adv)")
    };

    // Each clause finds its own die…
    assert!(adv(
        &[&BOOTS_OF_ELVENKIND],
        AbilityScoreType::Dexterity,
        Some(Skill::Stealth)
    ));
    assert!(adv(
        &[&CLOAK_OF_ELVENKIND],
        AbilityScoreType::Dexterity,
        Some(Skill::Stealth)
    ));
    assert!(adv(
        &[&EYES_OF_THE_EAGLE],
        AbilityScoreType::Wisdom,
        Some(Skill::Perception)
    ));

    // …and only its own. The boots are not lenses and the lenses are
    // not boots, which is the claim `compute_check_mode` could not have
    // made — it is handed an ability and never sees the skill.
    assert!(!adv(
        &[&BOOTS_OF_ELVENKIND],
        AbilityScoreType::Wisdom,
        Some(Skill::Perception)
    ));
    assert!(!adv(
        &[&EYES_OF_THE_EAGLE],
        AbilityScoreType::Dexterity,
        Some(Skill::Stealth)
    ));
    assert!(!adv(
        &[&EYES_OF_THE_EAGLE],
        AbilityScoreType::Wisdom,
        Some(Skill::Insight)
    ));

    // Two Stealth items are one notch. The log prints the resolved
    // mode, so "(adv)" appearing once is the whole claim — what would
    // fail here is an implementation that summed into the total.
    let both = rolled_with(
        &[&BOOTS_OF_ELVENKIND, &CLOAK_OF_ELVENKIND],
        AbilityScoreType::Dexterity,
        Some(Skill::Stealth),
    );
    assert!(both.contains("(adv)"));
    assert_eq!(both.matches("(adv)").count(), 1, "{both}");

    // And the consequence that makes the boots worth an item slot: the
    // number a Searcher has to beat goes up. Averaged over a band of
    // seeds because a d20 is a d20 — advantage is worth about +3.3 on
    // one roll, so twenty-four of them separate cleanly.
    let mean_stealth = |carried: &[&'static Item]| {
        let mut e = ei_with_terrain(12, 12, &[]);
        let id = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        for item in carried {
            e.actors.get_mut(&id).unwrap().pickup_item(item);
        }
        let total: i32 = (0..24)
            .map(|seed| {
                e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
                e.roll_ability_check(id, AbilityScoreType::Dexterity, Some(Skill::Stealth))
            })
            .sum();
        f64::from(total) / 24.0
    };
    let bare = mean_stealth(&[]);
    let booted = mean_stealth(&[&BOOTS_OF_ELVENKIND]);
    assert!(
        booted > bare + 1.5,
        "the boots barely moved the DC a Searcher must beat: {bare} -> {booted}"
    );
}

/// The Belt of Dwarvenkind, and the first item scoped by *what failing
/// a save would cost you*.
///
/// SRD 5.2's Resilience clause is two sentences — Poison resistance,
/// and *"Advantage on saving throws you make to avoid or end the
/// Poisoned condition"* — and the second one is the shape five features
/// in `actor_template` apologise for not being able to express. It
/// lands on `Item::save_advantages_against`, read through
/// `has_save_advantage_against` beside the `CONDITION_SAVE_ADVANTAGES`
/// cohort.
///
/// Pinned here rather than only beside the item, because the claims are
/// about the wiring:
///   - a save *against the Poisoned condition* is lifted;
///   - a Constitution save against anything else is not — which is
///     precisely what the two available roundings could not do, and
///     what the dwarf chassis's own Dwarven Resilience row still does
///     not do (it widens to every Constitution save, under a docstring
///     saying so);
///   - two sources are one notch, not two, so a dwarf wearing the belt
///     rolls the same die a dwarf without it does;
///   - the Toughness clause reaches the score through the new bonus
///     lane, capped at RAW's 20.
#[test]
fn the_dwarven_belt_answers_a_poisoner_and_not_a_purple_worm() {
    use crate::actors::creatures::dwarves::DWARF_TEMPLATE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::types::{AbilityScoreType, DamageType};
    use crate::items::item_template::BELT_OF_DWARVENKIND;

    let mut e = ei_with_terrain(12, 12, &[]);
    let id = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();

    // Toughness: +2, and everything downstream of the score moves.
    let con = e.actors[&id].ability_score(AbilityScoreType::Constitution);
    let con_mod = e.actors[&id].ability_modifier(AbilityScoreType::Constitution);
    e.actors
        .get_mut(&id)
        .unwrap()
        .pickup_item(&BELT_OF_DWARVENKIND);
    assert_eq!(
        e.actors[&id].ability_score(AbilityScoreType::Constitution),
        (con + 2).min(20)
    );
    assert!(e.actors[&id].ability_modifier(AbilityScoreType::Constitution) >= con_mod);

    // Resilience, half one: poison is halved. Read through
    // `effective_damage`, which is the lane that folds the item's
    // resistance in — `damage_modifier` answers off the template map
    // and has never heard of an inventory.
    assert_eq!(e.actors[&id].effective_damage(20, DamageType::Poison), 10);
    assert_eq!(e.actors[&id].effective_damage(20, DamageType::Acid), 20);

    // Resilience, half two — and its negative. Read off the save log's
    // own mode suffix, which is where the resolved notch is printed.
    let suffix = |e: &mut EncounterInstance, against: Option<Condition>| {
        let before = e.messages().len();
        match against {
            Some(c) => {
                e.roll_save_vs_condition(id, AbilityScoreType::Constitution, 10, c);
            }
            None => {
                e.roll_save(id, AbilityScoreType::Constitution, 10);
            }
        }
        e.messages()[before..]
            .iter()
            .find(|m| m.contains("save:"))
            .cloned()
            .unwrap_or_default()
    };
    assert!(
        suffix(&mut e, Some(Condition::Poisoned)).contains("(adv)"),
        "the belt's save clause never reached the die"
    );
    assert!(
        !suffix(&mut e, Some(Condition::Stunned)).contains("(adv)"),
        "the belt lifted a save against something it has never heard of"
    );
    assert!(
        !suffix(&mut e, None).contains("(adv)"),
        "the belt lifted a bare Constitution save"
    );

    // And the notch does not stack with a creature that already has the
    // clause by nature. The dwarf's own Dwarven Resilience is a
    // Constitution-wide row, so it lifts the save with or without the
    // belt — the claim is that wearing one does not produce a second
    // "(adv)" in the resolved mode.
    let mut d = ei_with_terrain(12, 12, &[]);
    let dwarf = d
        .instantiate_creature(&DWARF_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    d.actors
        .get_mut(&dwarf)
        .unwrap()
        .pickup_item(&BELT_OF_DWARVENKIND);
    let before = d.messages().len();
    d.roll_save_vs_condition(
        dwarf,
        AbilityScoreType::Constitution,
        10,
        Condition::Poisoned,
    );
    let line = d.messages()[before..]
        .iter()
        .find(|m| m.contains("save:"))
        .cloned()
        .unwrap_or_default();
    assert_eq!(line.matches("(adv)").count(), 1, "{line}");
}

/// A grapple names its grappler, and the hold ends the moment that
/// creature can no longer hold on. Stunning them is the cheapest
/// way to say "incapacitated" — RAW ends the grapple outright.
#[test]
fn a_grapple_ends_when_the_grappler_is_incapacitated() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 5), 1, 0)
        .unwrap();
    for effect in crate::engine::side_effects::install_condition_with_link(
        Condition::Grappled,
        goblin,
        ogre,
        ConditionTimer::Rounds(10),
    ) {
        effect.apply(&mut e);
    }
    assert_eq!(e.actors[&goblin].linked_by(Condition::Grappled), Some(ogre));
    // Grappler still standing and free: the hold survives the sweep.
    e.release_broken_grapples(goblin);
    assert!(e.actors[&goblin].has_condition(Condition::Grappled));
    e.actors
        .get_mut(&ogre)
        .unwrap()
        .add_condition(Condition::Stunned, ConditionTimer::Permanent);
    e.release_broken_grapples(goblin);
    assert!(
        !e.actors[&goblin].has_condition(Condition::Grappled),
        "a stunned grappler cannot keep holding on"
    );
}

/// The grapple's other RAW ending: separation. A grappled creature's
/// speed is 0, so it can never walk out of the hold — but the
/// grappler can walk away, and every teleport and shove in the game
/// can pull the two apart. Without this the victim would stay pinned
/// by a creature on the far side of the map.
#[test]
fn a_grapple_ends_when_the_two_are_pulled_apart() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    for effect in crate::engine::side_effects::install_condition_with_link(
        Condition::Grappled,
        goblin,
        ogre,
        ConditionTimer::Rounds(10),
    ) {
        effect.apply(&mut e);
    }
    // Adjacent: the hold survives the sweep.
    e.release_broken_grapples(goblin);
    assert!(e.actors[&goblin].has_condition(Condition::Grappled));
    // Walk the grappler across the room and it does not.
    e.place_actor_at(ogre, Coordinate::new(15, 15)).unwrap();
    e.release_broken_grapples(goblin);
    assert!(
        !e.actors[&goblin].has_condition(Condition::Grappled),
        "a hold does not reach across the map"
    );
}

/// A monster whose attack grapples names itself as the grappler,
/// same as the Grapple action does.
///
/// Anchoring is what makes two rules real for these attacks: the
/// escape is a contest against the creature holding on, and the
/// hold ends when that creature is incapacitated. Before it, a
/// roper's tendril grappled nobody in particular.
///
/// Swept over the **whole bestiary** rather than over a hand-written
/// list of grapplers, and the difference is not academic: this test
/// shipped with five names on it, chosen one per chassis the anchoring
/// travels through, and by the time six more stat blocks had grown their
/// RAW grapples the list still said five. A roster that has to be
/// remembered is a roster that goes stale silently — and a hold that
/// names nobody is invisible until somebody tries to escape it.
#[test]
fn a_monsters_grapple_names_the_monster() {
    use crate::actions::action_template::Action;
    use crate::actors::creatures::gladiators::GLADIATOR_TEMPLATE;
    use crate::conditions::Condition;
    let grapplers = EncounterInstance::template_pool();
    let mut checked = 0;
    for template in grapplers {
        for seed in 0..6u64 {
            let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
            let monster = e
                .instantiate_creature(template, Coordinate::new(4, 4), 0, 0)
                .unwrap();
            // A Medium victim rather than the Large brown bear this
            // used to grab: the giant frog's and the constrictor
            // snake's holds are gated at "Medium or smaller", so a bear
            // put two of the five chassis under test out of reach and
            // the sweep would have passed on the other three alone.
            let victim = e
                .instantiate_creature(&GLADIATOR_TEMPLATE, Coordinate::new(6, 4), 1, 0)
                .unwrap();
            let actions: Vec<&'static (dyn Action + Send + Sync)> =
                e.actors[&monster].available_actions();
            for action in actions {
                let targets = vec![victim];
                let effects =
                    action.side_effects(&mut e, monster, Some(&targets), None, None);
                for effect in effects {
                    effect.apply(&mut e);
                }
                if e.actors
                    .get(&victim)
                    .is_some_and(|a| a.has_condition(Condition::Grappled))
                {
                    checked += 1;
                    assert_eq!(
                        e.actors[&victim].linked_by(Condition::Grappled),
                        Some(monster),
                        "{}'s grapple should name it as the grappler",
                        template.name
                    );
                    break;
                }
            }
        }
    }
    // A floor rather than `> 0`, for the reason the roster is a sweep:
    // a filter that quietly narrowed to one creature would still pass a
    // `> 0`, and the whole point of walking the bestiary is that nobody
    // has to remember which creatures grapple.
    // A floor rather than `> 0`, for the reason the roster became a
    // sweep: a filter that quietly narrowed to one creature would still
    // pass a `> 0`, and the whole point of walking the bestiary is that
    // nobody has to remember which creatures grapple. The sweep lands
    // several hundred holds across six seeds; a hundred is comfortably
    // under that and comfortably over any one creature's share.
    assert!(
        checked >= 100,
        "the sweep only landed {} grapples — something narrowed it",
        checked
    );
}

/// An unlinked hold — an ooze's adhesive, a spell's tentacles — has
/// nobody to be incapacitated, so the sweep leaves it alone. Its
/// timer and its escape check are what end it.
#[test]
fn an_unlinked_hold_survives_the_grapple_sweep() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 5), 1, 0)
        .unwrap();
    e.actors
        .get_mut(&goblin)
        .unwrap()
        .add_condition(Condition::Grappled, ConditionTimer::Rounds(10));
    e.release_broken_grapples(goblin);
    assert!(e.actors[&goblin].has_condition(Condition::Grappled));
}

/// Couatl template has the bite + sleep gaze action pair and the
/// MM radiant/psychic resistance + immunity profile.
#[test]
fn couatl_template_has_bite_gaze_and_resistances() {
    use crate::actions::monster_attacks::{COUATL_BITE, COUATL_SLEEP_GAZE};
    use crate::actors::creatures::couatls::COUATL_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let c = e
        .instantiate_creature(&COUATL_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let actor = &e.actors[&c];
    let names: std::collections::HashSet<_> = actor
        .actions
        .iter()
        .map(|a| a.name().to_string())
        .collect();
    assert!(names.contains(COUATL_BITE.name()));
    assert!(names.contains(COUATL_SLEEP_GAZE.name()));
    // SRD 5.2 "Immunities Psychic, Radiant" — both, and the radiant
    // half is an immunity rather than the 2014 printing's resistance.
    assert!(actor.is_immune_to(DamageType::Psychic));
    assert!(actor.is_immune_to(DamageType::Radiant));
    // Couatls can't be magically charmed or frightened.
    assert!(actor.is_immune_to_condition(Condition::Charmed));
    assert!(actor.is_immune_to_condition(Condition::Frightened));
}

/// Pit Fiend template carries fire + poison immunity, the fear aura as
/// a passive emanation, and the bite/claw multi pair. Also: immune to
/// Frightened, which is what keeps a pair of them from cowing each
/// other.
#[test]
fn pit_fiend_template_is_fire_poison_immune_with_fear_aura() {
    use crate::actors::creatures::pit_fiends::PIT_FIEND_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let p = e
        .instantiate_creature(&PIT_FIEND_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let actor = &e.actors[&p];
    assert!(actor.is_immune_to(DamageType::Fire));
    assert!(actor.is_immune_to(DamageType::Poison));
    let [aura] = actor.emanations() else {
        panic!("the pit fiend has exactly one emanation");
    };
    assert_eq!(aura.name, "fear aura");
    assert_eq!(aura.dc, 21);
    assert_eq!(aura.radius_feet, 20);
    assert!(aura.grants_immunity_on_save);
    assert!(aura.requires_conscious_source);
    // And it is not an Action any more — RAW's aura costs the fiend
    // nothing, which is the whole reason it can keep its multiattack.
    assert!(actor.find_action("fear aura").is_none());
    assert!(actor.is_immune_to_condition(Condition::Frightened));
    assert!(actor.is_immune_to_condition(Condition::Poisoned));
    assert!(actor.is_immune_to_condition(Condition::Charmed));
}

/// Pit Fiend Fear Aura: anyone who opens a turn within twenty feet
/// makes a DC 21 Wisdom save or is Frightened until their next turn —
/// and a creature that makes it once is done with this fiend's aura.
///
/// It costs the fiend nothing, which is the difference from the Action
/// it used to be: the aura bills every round without the pit fiend
/// spending anything, and the bite and two claws land on top.
#[test]
fn a_pit_fiends_aura_bills_every_turn_spent_inside_it() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::pit_fiends::PIT_FIEND_TEMPLATE;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;

    let mut frightened = false;
    let mut banked = false;
    for seed in 0..30u64 {
        let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
        let fiend = e
            .instantiate_creature(&PIT_FIEND_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // A goblin, whose Wisdom save cannot reach 21 on any die, and a
        // cleric, whose can. Which is itself the shape of a DC 21 aura:
        // the rank and file never get out from under it.
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 2), 1, 0)
            .unwrap();
        let cleric = e
            .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(8, 6), 1, 1)
            .unwrap();
        e.start_turn_for(g);
        if e.actors[&g].has_condition(Condition::Frightened) {
            frightened = true;
            assert_eq!(
                e.actors[&g].linked_by(Condition::Frightened),
                Some(fiend),
                "and it knows what it is afraid of"
            );
        }
        for _ in 0..8 {
            e.start_turn_for(cleric);
            if e.trait_immunity_banked(cleric, fiend, "fear aura") {
                banked = true;
                // Done with it: no further save, no further fear.
                for _ in 0..4 {
                    e.start_turn_for(cleric);
                    assert!(!e.actors[&cleric].has_condition(Condition::Frightened));
                }
                break;
            }
        }
        if frightened && banked {
            break;
        }
    }
    assert!(frightened, "a DC 21 save fails on a goblin");
    assert!(banked, "and making it once is the end of it");
}

/// RAW's "while it doesn't have the Incapacitated condition": a stunned
/// pit fiend is not frightening anybody. The clause that separates a
/// projected aura from a smell — see `Emanation::requires_conscious_source`.
#[test]
fn a_stunned_pit_fiend_projects_nothing() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::pit_fiends::PIT_FIEND_TEMPLATE;
    for seed in 0..30u64 {
        let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
        let fiend = e
            .instantiate_creature(&PIT_FIEND_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&fiend)
            .unwrap()
            .add_condition(Condition::Stunned, ConditionTimer::Rounds(5));
        e.start_turn_for(g);
        assert!(!e.actors[&g].has_condition(Condition::Frightened));
        assert!(
            !e.trait_immunity_banked(g, fiend, "fear aura"),
            "and no save was rolled at all, so nothing was banked (seed {seed})"
        );
    }
}

/// Chain Lightning: hits the primary + up to 3 forks within 5 tiles
/// of the primary. Each fork makes its own save. Placing 4 enemies
/// in a tight cluster verifies all 4 take damage.
#[test]
fn chain_lightning_arcs_to_three_nearby_targets() {
    use crate::actions::spells::CHAIN_LIGHTNING;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    let mut e = ei_with_terrain(30, 30, &[]);
    let w = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Give the wizard a level-6 slot.
    let _ = e
        .actors
        .get_mut(&w)
        .unwrap()
        .spell_slot_manager
        .restore_spell_slot(6, 1);
    // Primary + 3 forks tightly clustered.
    let primary = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 10), 1, 0)
        .unwrap();
    let f1 = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(11, 10), 1, 1)
        .unwrap();
    let f2 = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 11), 1, 2)
        .unwrap();
    let f3 = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(12, 11), 1, 3)
        .unwrap();
    let hp_before: Vec<u32> = [primary, f1, f2, f3]
        .iter()
        .map(|id| e.actors[id].hitpoints())
        .collect();
    let tv = vec![primary];
    let effects = CHAIN_LIGHTNING.side_effects(&mut e, w, Some(&tv), None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    let hp_after: Vec<u32> = [primary, f1, f2, f3]
        .iter()
        .map(|id| e.actors.get(id).map(|a| a.hitpoints()).unwrap_or(0))
        .collect();
    // Every target should have taken damage (10d8 even halved is
    // > 0 against AC 12 goblins with no resistance).
    for (i, (b, a)) in hp_before.iter().zip(hp_after.iter()).enumerate() {
        assert!(
            a < b,
            "chain lightning target index {} should be damaged ({} → {})",
            i, b, a
        );
    }
}

/// AI integration: a paladin with no concentration up and an enemy
/// in melee reach should fire one of the new Smite spells (Searing
/// at lv1 first, falling back as slots run out).
#[test]
fn ai_paladin_casts_smite_spell_when_adjacent() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
    use crate::ai::Controller;
    use crate::conditions::ConditionTimer;
    let mut e = ei_with_terrain(20, 20, &[]);
    let pal = e
        .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let _g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
        .unwrap();
    // Pre-spend Divine Smite by marking it as already primed so the
    // AI's earlier-priority Divine Smite gate falls through; the
    // SmiteSpell path is what we want to validate here.
    e.actors
        .get_mut(&pal)
        .unwrap()
        .add_condition(Condition::Smiting, ConditionTimer::Rounds(2));
    let ai = crate::ai::simple::SimpleAi;
    let decision = ai.decide(&e, pal);
    let crate::ai::ControllerDecision::Act(aei) = decision else {
        panic!("paladin should act");
    };
    let name = aei.action().name();
    assert!(
        matches!(
            name,
            "searing smite" | "wrathful smite" | "branding smite" | "blinding smite"
        ),
        "paladin should cast a smite spell, got {}",
        name
    );
}

/// Goodberry heals 10 HP on a touch-range ally — no save, no roll
/// dependency, just a flat top-up. The cleanse path doesn't fire
/// (it's a heal, not a restoration), so the only mutation is HP.
#[test]
fn goodberry_heals_ally_for_ten() {
    use crate::actions::spells::GOODBERRY;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let druid = e
        .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    let max = e.actors[&ally].max_hitpoints();
    e.actors.get_mut(&ally).unwrap().take_damage(max - 1);
    let before = e.actors[&ally].hitpoints();
    let tv = vec![ally];
    let effs = GOODBERRY.side_effects(&mut e, druid, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    let after = e.actors[&ally].hitpoints();
    assert_eq!(after, before + 10);
}

/// Moonbeam: cast at a point, damages every creature in the 1-tile
/// burst on a failed CON save and installs concentration on the
/// caster. With AC-agnostic save targets the save outcome is RNG;
/// we just verify damage landed on at least one target and the
/// caster is now concentrating on Moonbeam.
#[test]
fn moonbeam_damages_burst_and_starts_concentration() {
    use crate::actions::spells::MOONBEAM;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let druid = e
        .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let g1 = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 10), 1, 0)
        .unwrap();
    let g2 = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(11, 10), 1, 1)
        .unwrap();
    let hp_before = [e.actors[&g1].hitpoints(), e.actors[&g2].hitpoints()];
    let tl = vec![Coordinate::new(10, 10)];
    let effs = MOONBEAM.side_effects(&mut e, druid, None, Some(&tl), None);
    for ef in effs {
        ef.apply(&mut e);
    }
    // Concentration installs on the caster.
    assert!(
        e.actors[&druid].is_concentrating(),
        "druid should concentrate on Moonbeam"
    );
    // At least one goblin should have taken some damage (even on a
    // save they take half of 2d10 ≥ 1).
    let hp_after = [
        e.actors.get(&g1).map(|a| a.hitpoints()).unwrap_or(0),
        e.actors.get(&g2).map(|a| a.hitpoints()).unwrap_or(0),
    ];
    assert!(
        hp_after[0] < hp_before[0] || hp_after[1] < hp_before[1],
        "moonbeam should damage at least one goblin in the burst"
    );
}

