/// SRD 5.2 exhaustion is a flat penalty on **every** D20 Test, from the
/// first level — not disadvantage on some of them from the third.
///
/// The engine shipped the 2014 ladder, and the direction it was wrong
/// in mattered: a creature at exhaustion 1 or 2 swung and saved at full
/// strength, because those rungs only touched ability checks and speed.
/// Two points a level, on all three lanes, is what 5.2 prints; the roll
/// *mode* is left alone entirely, which is the other half of the change
/// and the half a `RollMode` assertion is the only way to see.
#[test]
fn exhaustion_taxes_every_d20_test_from_the_first_level() {
    use crate::actors::actor_template::EXHAUSTION_D20_PENALTY_PER_LEVEL;
    use crate::actors::creatures::guards::GUARD_TEMPLATE;
    use crate::conditions::ConditionTimer;
    let mut e = ei_with_terrain(15, 15, &[]);
    // A guard rather than a zombie: SRD 5.2 makes every Undead immune to
    // Exhaustion, so a zombie is the one creature on the board that
    // cannot demonstrate the ladder.
    let attacker = e
        .instantiate_creature(&GUARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let target = e
        .instantiate_creature(&GUARD_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    let wis = crate::engine::types::AbilityScoreType::Wisdom;
    let base_save = e.actors[&attacker].save_modifier(wis);
    let (base_attack, _) = e.caster_attack_buffs(attacker);

    for level in 1..=3 {
        e.actors
            .get_mut(&attacker)
            .unwrap()
            .add_condition(Condition::Exhausted, ConditionTimer::Permanent);
        assert_eq!(e.actors[&attacker].exhaustion_level(), level);
        let owed = -(level as i32) * EXHAUSTION_D20_PENALTY_PER_LEVEL;
        assert_eq!(
            e.actors[&attacker].exhaustion_d20_penalty(),
            owed,
            "two points a level, cumulative"
        );
        assert_eq!(
            e.actors[&attacker].save_modifier(wis),
            base_save + owed,
            "the save total carries it"
        );
        assert_eq!(
            e.caster_attack_buffs(attacker).0,
            base_attack + owed,
            "and so does the attack roll"
        );
        // The mode is untouched at every level: 5.2 replaced the
        // disadvantage the older printing handed out with the number.
        assert!(matches!(
            e.compute_attack_mode(attacker, target, true),
            RollMode::Normal
        ));
        assert!(matches!(e.compute_save_mode(attacker, wis), RollMode::Normal));
        assert!(matches!(e.compute_check_mode(attacker, wis), RollMode::Normal));
    }
}

/// The other half of SRD 5.2's ladder: five feet of speed per level,
/// floored at zero, and death at six.
///
/// The 2014 rungs this replaces were half speed at 2, a halved hit
/// point maximum at 4 and speed 0 at 5. None of the three is in 5.2, and
/// the hit point one is pinned here as an absence because it is the
/// clause a creature would notice most: it used to clip current HP down
/// as the level landed, which is a thing an exhausted creature no
/// longer suffers.
#[test]
fn exhaustion_walks_the_speed_line_down_five_feet_at_a_time() {
    use crate::actors::actor_template::{
        EXHAUSTION_DEATH_TIER, EXHAUSTION_SPEED_PENALTY_FT_PER_LEVEL,
    };
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let base_speed = e.actors[&id].speed();
    let base_max_hp = e.actors[&id].max_hitpoints();
    assert!(base_speed > 0.0 && base_max_hp > 1);

    let a = e.actors.get_mut(&id).unwrap();
    for level in 1..EXHAUSTION_DEATH_TIER {
        a.gain_exhaustion(1);
        let owed = level as f32 * EXHAUSTION_SPEED_PENALTY_FT_PER_LEVEL;
        assert!(
            (a.speed() - (base_speed - owed).max(0.0)).abs() < 0.01,
            "level {} should cost {} ft, speed is {}",
            level,
            owed,
            a.speed()
        );
        assert_eq!(
            a.max_hitpoints(),
            base_max_hp,
            "5.2 has no halved hit point maximum at any level"
        );
    }
    // A fighter's 30 ft is gone by level 6, and the floor holds rather
    // than the number going negative — which is what makes 5.2 need no
    // "speed 0" rung of its own.
    assert!(a.speed() >= 0.0);

    a.gain_exhaustion(1);
    assert!(!a.is_combat_active(), "level 6 is death");
    assert_eq!(a.exhaustion_level(), EXHAUSTION_DEATH_TIER);
    // The ladder has a top: nothing stacks past the level that kills.
    a.gain_exhaustion(3);
    assert_eq!(a.exhaustion_level(), EXHAUSTION_DEATH_TIER);
}

/// A readied attack fires on the step that brings an enemy into
/// reach, and on no other step. The two negative cases are the ones
/// worth pinning: a mover who was *already* inside the reach isn't
/// entering it, and a mover crossing the room outside the reach
/// never triggers anything.
#[test]
fn a_readied_attack_fires_on_the_step_that_closes_the_distance() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::veterans::VETERAN_TEMPLATE;
    use crate::conditions::ConditionTimer;
    use crate::engine::side_effects::Resource;
    let mut e = ei_with_terrain(20, 20, &[]);
    let readier = e
        .instantiate_creature(&VETERAN_TEMPLATE, Coordinate::new(4, 4), 0, 0)
        .unwrap();
    let mover = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(12, 4), 1, 0)
        .unwrap();
    let reach = e
        .best_readyable_attack(readier)
        .and_then(|a| a.reach_tiles())
        .expect("a veteran should have something to ready");
    e.actors
        .get_mut(&readier)
        .unwrap()
        .add_condition(Condition::Readied, ConditionTimer::UntilStartOfNextTurn);

    // A step that stays outside the reach: nothing happens.
    let outside = Coordinate::new(4 + reach + 3, 4);
    e.dispatch_readied_attacks(mover, Coordinate::new(4 + reach + 4, 4), outside);
    assert!(
        e.actors[&readier].has_condition(Condition::Readied),
        "a mover still out of reach shouldn't trip the hold"
    );

    // The step that crosses in: the swing fires, and it costs the
    // reaction and the hold.
    let inside = Coordinate::new(4 + reach, 4);
    let before = e.messages().len();
    e.dispatch_readied_attacks(mover, outside, inside);
    assert!(
        e.messages()[before..]
            .iter()
            .any(|m| m.contains("readied")),
        "the readied attack should have fired: {:?}",
        &e.messages()[before..]
    );
    assert!(!e.actors[&readier].has_condition(Condition::Readied));
    assert!(!e.actors[&readier].can_consume_resource(Resource::Reaction));
}

/// Evasive Footwork covers a readied shot as well as an opportunity
/// attack. RAW's window is "until you stop moving", and a readied
/// attack that fires as the fighter steps into its arc catches them
/// mid-step exactly as a swing at their back does.
///
/// The two dispatchers raise the guard independently and pay for it
/// once, because the die comes out of the shared once-per-turn ledger
/// rather than out of either dispatcher's own bookkeeping.
#[test]
fn evasive_footwork_answers_a_readied_shot_as_well_as_an_opportunity_attack() {
    use crate::actions::class_features::{EVASIVE_FOOTWORK_TAG, SUPERIORITY_DICE_TAG};
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::veterans::VETERAN_TEMPLATE;
    use crate::conditions::ConditionTimer;

    let mut e = ei_with_terrain(20, 20, &[]);
    let readier = e
        .instantiate_creature(&VETERAN_TEMPLATE, Coordinate::new(4, 4), 1, 0)
        .unwrap();
    let mover = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(15, 4), 0, 0)
        .unwrap();
    let reach = e
        .best_readyable_attack(readier)
        .and_then(|a| a.reach_tiles())
        .expect("a veteran should have something to ready");
    e.actors
        .get_mut(&readier)
        .unwrap()
        .add_condition(Condition::Readied, ConditionTimer::UntilStartOfNextTurn);
    let dice_before = e.actors[&mover].feature_charges_remaining(SUPERIORITY_DICE_TAG);

    // Same geometry as `a_readied_attack_fires_on_the_step_that_closes_the_distance`:
    // a step from outside the readier's reach to inside it.
    let outside = Coordinate::new(4 + reach + 3, 4);
    let inside = Coordinate::new(4 + reach, 4);
    e.dispatch_readied_attacks(mover, outside, inside);

    assert!(
        e.actors[&mover].once_per_turn_used(EVASIVE_FOOTWORK_TAG),
        "the readied shot is a swing taken while the fighter is moving"
    );
    assert!(
        e.actors[&mover].feature_charges_remaining(SUPERIORITY_DICE_TAG) < dice_before,
        "and it costs a superiority die"
    );
    assert!(
        !e.actors[&mover].has_condition(Condition::EvasiveFootwork),
        "the guard comes down when the step resolves"
    );
}

/// The three reaction dispatchers read the same list of "may this
/// creature swing at that one" rules as declared actions do.
///
/// None of the three goes through `Action::validate`, so each used to
/// carry its own copy of the list — and the copies had drifted. The
/// readied-attack dispatcher open-coded the charm arm and knew nothing
/// about the other two, which is what this pins: a readier wrapped
/// around somebody's head held its swing for a passer-by, and a swallowed
/// readier held one through the stomach wall.
///
/// Written against the predicate rather than against three staged
/// dispatches, because what is under test is that there is *one* list.
/// A fourth rule added to `hostility_blocked` should need no edit here
/// and no edit in any of the three dispatchers.
#[test]
fn every_reaction_lane_reads_the_same_hostility_list() {
    use crate::actors::creatures::gladiators::GLADIATOR_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::purple_worms::PURPLE_WORM_TEMPLATE;
    use crate::actors::creatures::stirges::STIRGE_TEMPLATE;
    use crate::engine::side_effects::install_condition_with_link;

    let mut e = ei_with_terrain(30, 20, &[]);
    let passer_by = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 1, 0)
        .unwrap();

    // Charm: the charmed creature may not swing at its charmer, and may
    // swing at anybody else.
    let charmed = e
        .instantiate_creature(&GLADIATOR_TEMPLATE, Coordinate::new(4, 4), 0, 0)
        .unwrap();
    let charmer = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 4), 1, 0)
        .unwrap();
    for effect in install_condition_with_link(
        Condition::Charmed,
        charmed,
        charmer,
        ConditionTimer::Permanent,
    ) {
        effect.apply(&mut e);
    }
    assert!(e.hostility_blocked(charmed, charmer));
    assert!(!e.hostility_blocked(charmed, passer_by));

    // Attach: the latched creature may swing only at what it is holding.
    let stirge = e
        .instantiate_creature(&STIRGE_TEMPLATE, Coordinate::new(8, 4), 1, 0)
        .unwrap();
    let host = e
        .instantiate_creature(&GLADIATOR_TEMPLATE, Coordinate::new(9, 4), 0, 0)
        .unwrap();
    assert!(e.attach(stirge, host).is_ok());
    assert!(!e.hostility_blocked(stirge, host));
    assert!(e.hostility_blocked(stirge, passer_by));

    // Swallow: Total Cover, both ways, except against the stomach.
    let worm = e
        .instantiate_creature(&PURPLE_WORM_TEMPLATE, Coordinate::new(14, 10), 1, 0)
        .unwrap();
    let eaten = e
        .instantiate_creature(&GLADIATOR_TEMPLATE, Coordinate::new(18, 10), 0, 0)
        .unwrap();
    for effect in install_condition_with_link(
        Condition::Grappled,
        eaten,
        worm,
        ConditionTimer::Permanent,
    ) {
        effect.apply(&mut e);
    }
    assert!(e.swallow(worm, eaten).is_ok());
    assert!(!e.hostility_blocked(eaten, worm));
    assert!(e.hostility_blocked(eaten, passer_by));
    assert!(e.hostility_blocked(passer_by, eaten));

    // And the one rule on the list that is about the actor rather than
    // the pair: 5e's flat "the target can't attack", which Gaseous Form
    // prints. It has to be here rather than only in `validate` because
    // the three reaction lanes have no other gate for it — a creature
    // that had turned into a cloud could not declare an attack on its
    // own turn and could still riposte one.
    let cloud = e
        .instantiate_creature(&GLADIATOR_TEMPLATE, Coordinate::new(24, 4), 0, 0)
        .unwrap();
    assert!(!e.hostility_blocked(cloud, passer_by));
    e.actors
        .get_mut(&cloud)
        .unwrap()
        .add_condition(Condition::Gaseous, ConditionTimer::Rounds(10));
    assert!(e.hostility_blocked(cloud, passer_by));
}


/// Aid does not stack with itself. PHB: "the effects of the same
/// spell cast multiple times don't combine."
///
/// The bug this pins had two halves and the second was the
/// expensive one. A second cast added a second five hit points,
/// which is against the rule; and because the cast *validated*, the
/// AI's support rung — which walks its heal list every turn and
/// takes the first action that passes — answered the same wounded
/// ally with Aid on every turn it had a level-2 slot for. An
/// artificer standing beside its steel defender spent an entire
/// spell table five hit points at a time.
#[test]
fn aid_does_not_stack_on_a_target_that_already_has_it() {
    use crate::actions::spells::AID;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let cleric = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 0)
        .unwrap();
    let before = e.actors[&ally].max_hitpoints();

    let aei = ActionExecutionInfo::new(&*AID, cleric, Some(vec![ally]), None, None);
    assert!(aei.validate(&e), "the first cast should be legal");
    for ef in aei.execute(&mut e) {
        ef.apply(&mut e);
    }
    assert_eq!(e.actors[&ally].max_hitpoints(), before + 5);
    assert!(e.actors[&ally].has_condition(Condition::Aided));

    // The second cast is refused outright, which is what sends the
    // AI's support rung on to the next thing on its list.
    e.actors.get_mut(&cleric).unwrap().reset_for_new_round();
    let again = ActionExecutionInfo::new(&*AID, cleric, Some(vec![ally]), None, None);
    assert!(
        !again.validate(&e),
        "a second Aid on the same target should not be castable"
    );
    assert_eq!(e.actors[&ally].max_hitpoints(), before + 5);
}

// ─── Artificer ──────────────────────────────────────────────────

/// Flash of Genius rescues an *ally's* failed save, which no other
/// entry on the failed-save recovery ladder can do — every one of
/// them is a charge the failing actor is carrying.
#[test]
fn flash_of_genius_pays_for_an_allys_failed_save() {
    use crate::actions::class_features::FLASH_OF_GENIUS_TAG;
    use crate::actors::creatures::artificers::ARTIFICER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let artificer = e
        .instantiate_creature(&ARTIFICER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 0, 0)
        .unwrap();
    // A DC the goblin cannot clear on its own d20 but that the
    // artificer's +4 Intelligence can drag it over from below.
    // `roll_save` is seeded, so the shortfall is whatever the die
    // gives; sweep until one lands inside the modifier's range.
    let mut rescued = false;
    for _ in 0..40 {
        e.actors
            .get_mut(&artificer)
            .unwrap()
            .grant_feature_for_test(FLASH_OF_GENIUS_TAG);
        e.actors.get_mut(&artificer).unwrap().reset_for_new_round();
        let before = e.messages().len();
        let outcome = e.roll_save(ally, AbilityScoreType::Wisdom, 14);
        let fired = e.messages()[before..]
            .iter()
            .any(|m| m.contains("flash of genius"));
        if fired {
            assert!(
                outcome.passed(),
                "a flash that fired should have turned the save"
            );
            assert!(
                !e.actors[&artificer].feature_available(FLASH_OF_GENIUS_TAG),
                "the charge should be spent"
            );
            assert!(
                !e.actors[&artificer]
                    .can_consume_resource(crate::engine::side_effects::Resource::Reaction),
                "the reaction should be spent"
            );
            rescued = true;
            break;
        }
    }
    assert!(rescued, "40 saves at DC 14 should include one the flash could reach");
}

/// The two costs are real, and the range is the one RAW names.
