/// A boss that finishes off the creature whose turn just ended does
/// not cost the next creature in the queue its turn.
///
/// The trap is in the interaction between two individually correct
/// pieces. `InitiativeTracker::remove_actor` deliberately leaves
/// `curr_index` alone when the active slot is the one removed, so "the
/// next actor naturally slides into place there" — exactly right for
/// every other caller. And `advance` moves one slot on. Dispatch
/// legendary actions *before* the advance and the two compose into a
/// skipped turn: the dead creature's slot is vacated, the next
/// combatant slides into it, and the advance steps straight over them.
///
/// The fixture is built to tell the two orderings apart, which took
/// some doing. A wide burst that kills every enemy at once cannot: with
/// one survivor left, both orderings land on it. So the boss here is
/// the beholder, whose whole repertoire is a single-target ray, and
/// only one goblin is ever within a hit point of dying — the rest of
/// the queue survives to be skipped over.
#[test]
fn a_legendary_kill_does_not_swallow_the_next_creatures_turn() {
    use crate::actors::creatures::beholders::BEHOLDER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut discriminating = 0;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain_seeded(30, 30, &[], seed);
        e.instantiate_creature(&BEHOLDER_TEMPLATE, Coordinate::new(10, 10), 0, 0)
            .unwrap();
        // The ray takes the nearest enemy it can see, so the goblin
        // beside the beholder is the only one it will ever pick.
        let victim = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(12, 10), 1, 1)
            .unwrap();
        let victim_hp = e.actors[&victim].hitpoints();
        // Three more goblins, out of the ray's reach because it only
        // ever has one target, and at full health besides. They are the
        // queue the bug eats a slot out of.
        for (i, spot) in [(24, 24), (24, 22), (22, 24)].into_iter().enumerate() {
            e.instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(spot.0, spot.1), 1, i + 2)
                .unwrap();
        }

        for _ in 0..8 {
            let queue = e.initiative_slots();
            if queue.len() < 3 || !e.actors.contains_key(&victim) {
                break;
            }
            let ended = queue[0].actor_id;
            // Put the victim one hit point from death only on the turn
            // end that is actually under test — its own. On every other
            // turn end the ray lands and it survives, which keeps the
            // fixture alive long enough to reach the case that matters.
            let hp = e.actors[&victim].hitpoints();
            if ended == victim {
                if hp > 1 {
                    e.actors.get_mut(&victim).unwrap().take_damage(hp - 1);
                }
            } else if hp < victim_hp {
                e.actors.get_mut(&victim).unwrap().heal(victim_hp - hp);
            }

            e.advance_initiative();

            // Whoever is first behind the ended slot and still standing
            // is owed the next turn. Stated once rather than as a case
            // analysis, so the assertion is the invariant itself.
            let Some(owed) = queue[1..]
                .iter()
                .map(|s| s.actor_id)
                .find(|id| e.actors.contains_key(id))
            else {
                break;
            };
            assert_eq!(
                e.initiative_tracker.current_player(),
                Some(owed),
                "seed {}: the turn after {}'s went to the wrong creature",
                seed,
                ended
            );
            if ended == victim && !e.actors.contains_key(&ended) {
                discriminating += 1;
            }
        }
    }
    assert!(
        discriminating > 0,
        "no seed in the sweep ended a creature's turn by killing it with a \
         legendary action — the ordering under test was never exercised"
    );
}

/// The pool never goes negative, and an option is never taken that
/// the remaining budget cannot pay for.
///
/// The rule that makes RAW's "(Costs 2 Actions)" mean anything: a
/// dispatcher that drew uniformly from the whole list would let a
/// one-point remainder buy a three-point option, which is a lich
/// casting Disrupt Life four times a round.
#[test]
fn an_option_is_never_taken_on_credit() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::liches::LICH_TEMPLATE;
    use crate::engine::side_effects::Resource;
    let mut e = ei_with_terrain(40, 40, &[]);
    let lich = e
        .instantiate_creature(&LICH_TEMPLATE, Coordinate::new(4, 4), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(30, 30), 1, 0)
        .unwrap();
    let cheapest = e.actors[&lich]
        .legendary_actions()
        .iter()
        .map(|o| o.cost)
        .min()
        .expect("the lich should have options");
    for _ in 0..40 {
        let before = e.actors[&lich].legendary_action_slots();
        e.dispatch_legendary_actions(Some(goblin));
        let after = e.actors[&lich].legendary_action_slots();
        assert!(after <= before, "the pool grew mid-round");
        if before < cheapest {
            assert_eq!(after, before, "a remainder too small to buy anything spent");
        }
        e.actors.get_mut(&lich).unwrap().reset_for_new_round();
        // Re-drain to a deliberately awkward remainder so the
        // affordability filter is exercised at every rung rather
        // than only at a full pool.
        while e.actors[&lich].legendary_action_slots() > 1 {
            e.actors
                .get_mut(&lich)
                .unwrap()
                .consume_resource(Resource::LegendaryAction);
        }
    }
}

/// A source that hands out exhaustion hands out a *level*, and a
/// second application stacks on the first. Under the old single
/// flag the second one was swallowed whole by the "already has this
/// condition" check — Sickening Radiance could hold a creature in
/// its glow for ten rounds and never make it any worse off than the
/// first failed save did.
///
/// Both log lines are pinned too, because they are the only way a
/// player can see the rung they are on: the climb has to name it,
/// and a partial cleanse must not claim the whole ladder.
#[test]
fn a_second_helping_of_exhaustion_stacks_and_says_so() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::ConditionTimer;
    use crate::engine::side_effects::{ApplicableSideEffect, ApplyCondition, RemoveCondition};
    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let install = ApplyCondition {
        actor_id: id,
        condition: Condition::Exhausted,
        timer: ConditionTimer::Permanent,
    };
    install.apply(&mut e);
    install.apply(&mut e);
    assert_eq!(e.actors[&id].exhaustion_level(), 2);
    assert!(
        e.messages().iter().any(|m| m.contains("exhausted (level 2)")),
        "the second application should announce the rung it reached"
    );
    let before = e.messages().len();
    RemoveCondition {
        actor_id: id,
        condition: Condition::Exhausted,
    }
    .apply(&mut e);
    assert_eq!(e.actors[&id].exhaustion_level(), 1);
    let logged: Vec<&String> = e.messages()[before..].iter().collect();
    assert!(
        logged.iter().any(|m| m.contains("eases to level 1")),
        "a partial cleanse must not read as 'no longer exhausted': {:?}",
        logged
    );
}

/// Every cleanse 5e writes for exhaustion says "reduce by 1", and
/// both of ours now do. Greater Restoration reaches it through
/// `remove_condition`; a long rest reaches it through `long_rest`,
/// which also has to walk back its own blanket condition wipe.
#[test]
fn a_cleanse_walks_one_rung_back_down_rather_than_the_whole_ladder() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let a = e.actors.get_mut(&id).unwrap();
    a.gain_exhaustion(3);
    // The Greater Restoration lane.
    a.remove_condition(Condition::Exhausted);
    assert_eq!(a.exhaustion_level(), 2);
    assert!(a.has_condition(Condition::Exhausted), "still exhausted, just less so");
    // The long-rest lane, which clears every other condition
    // wholesale and must leave this one standing.
    a.long_rest();
    assert_eq!(a.exhaustion_level(), 1);
    assert!(a.has_condition(Condition::Exhausted));
    a.long_rest();
    assert_eq!(a.exhaustion_level(), 0);
    assert!(!a.has_condition(Condition::Exhausted), "the last rung clears the flag");
    // And a rest with nothing to shed is a no-op rather than an
    // underflow.
    a.long_rest();
    assert_eq!(a.exhaustion_level(), 0);
}

/// Storm of Vengeance: 2d6 thunder + 4d6 lightning on every enemy
/// in the 30ft sphere, CON save for half + dodges the Deafened
/// rider. Allies in the radius are spared by enemy_burst_targets.
/// Verifies the dual-damage shape lands and concentration installs.
#[test]
fn storm_of_vengeance_dual_damages_enemies_only() {
    use crate::actions::spells::STORM_OF_VENGEANCE;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(30, 30, &[]);
    let druid = e
        .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(10, 10), 0, 1)
        .unwrap();
    let enemy = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(11, 10), 1, 0)
        .unwrap();
    let ally_before = e.actors[&ally].hitpoints();
    let enemy_before = e.actors[&enemy].hitpoints();
    let tl = vec![Coordinate::new(10, 10)];
    let effs = STORM_OF_VENGEANCE.side_effects(&mut e, druid, None, Some(&tl), None);
    for ef in effs {
        ef.apply(&mut e);
    }
    // Concentration installs on the druid.
    assert!(e.actors[&druid].is_concentrating());
    // Enemy goblin takes mixed damage; ally zombie is spared.
    let enemy_after = e
        .actors
        .get(&enemy)
        .map(|a| a.hitpoints())
        .unwrap_or(0);
    assert!(
        enemy_after < enemy_before,
        "enemy should take storm damage"
    );
    assert_eq!(
        e.actors[&ally].hitpoints(),
        ally_before,
        "ally should NOT take storm damage (enemy-only burst)"
    );
}

/// Exhausted is in the Greater Restoration cleanse pool, so casting
/// GR on an exhausted ally lifts the flag.
#[test]
fn greater_restoration_lifts_exhausted() {
    use crate::actions::spells::GREATER_RESTORATION;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::conditions::ConditionTimer;
    let mut e = ei_with_terrain(15, 15, &[]);
    let cleric = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    e.actors
        .get_mut(&ally)
        .unwrap()
        .add_condition(Condition::Exhausted, ConditionTimer::Permanent);
    let tv = vec![ally];
    let effs = GREATER_RESTORATION.side_effects(&mut e, cleric, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(
        !e.actors[&ally].has_condition(Condition::Exhausted),
        "greater restoration should cleanse Exhausted"
    );
}

/// Confusion: imposes attacker disadvantage on the target and blocks
/// their reactions. We pick a low-WIS goblin and spam casts until one
/// fails the save so the condition lands.
#[test]
fn confusion_disad_attacks_and_blocks_reactions() {
    use crate::actions::spells::CONFUSION;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::Resource;
    let mut confused = false;
    for seed in 0..30 {
        let mut e = ei_with_terrain(25, 25, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 10), 1, 0)
            .unwrap();
        let tl = vec![Coordinate::new(10, 10)];
        let effs = CONFUSION.side_effects(&mut e, wiz, None, Some(&tl), None);
        for ef in effs {
            ef.apply(&mut e);
        }
        if e.actors[&g].has_condition(Condition::Confused) {
            confused = true;
            // Concentration installs on the caster regardless of saves.
            assert!(e.actors[&wiz].is_concentrating());
            // Reactions are blocked.
            let g_actor = e.actors.get_mut(&g).unwrap();
            g_actor.give_resource(Resource::Reaction);
            assert!(
                !g_actor.can_consume_resource(Resource::Reaction),
                "Confused should block reaction consumption"
            );
            // Attack rolls eat disadvantage.
            let mode = e.compute_attack_mode(g, wiz, true);
            assert!(matches!(mode, RollMode::Disadvantage));
            break;
        }
    }
    assert!(confused, "confusion never landed across 30 attempts");
}

/// Plant Growth: every enemy in the burst is Entangled (zeros
/// movement) for the duration; allies are skipped.
#[test]
fn plant_growth_entangles_enemies_only() {
    use crate::actions::spells::PLANT_GROWTH;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(25, 25, &[]);
    let cler = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(10, 10), 0, 1)
        .unwrap();
    let enemy = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(11, 10), 1, 0)
        .unwrap();
    let tl = vec![Coordinate::new(10, 10)];
    let effs = PLANT_GROWTH.side_effects(&mut e, cler, None, Some(&tl), None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&enemy].has_condition(Condition::Entangled),
        "enemy in burst should be Entangled"
    );
    assert!(
        !e.actors[&ally].has_condition(Condition::Entangled),
        "ally in burst should be spared (enemy-only partition)"
    );
    // Entangled enters the zeros_movement set: the goblin's remaining
    // movement should be 0 even after a turn-reset gives them speed.
    e.actors.get_mut(&enemy).unwrap().reset_for_new_round();
    assert_eq!(e.actors[&enemy].remaining_movement(), 0.0);
    // Plant Growth is not concentration-bound.
    assert!(!e.actors[&cler].is_concentrating());
}

/// Fly: applies the Flying condition (concentration-bound) and bumps
/// the target's speed by the +60ft fly rider in `speed()`.
#[test]
fn fly_boosts_speed_and_starts_concentration() {
    use crate::actions::spells::FLY;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let cler = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    let base_speed = e.actors[&ally].speed();
    let tv = vec![ally];
    let effs = FLY.side_effects(&mut e, cler, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&ally].has_condition(Condition::Flying),
        "fly should apply the Flying condition"
    );
    assert!(
        e.actors[&ally].speed() > base_speed,
        "Flying should boost speed: {} → {}",
        base_speed,
        e.actors[&ally].speed()
    );
    assert!(e.actors[&cler].is_concentrating());
}

/// Spider Climb: applies the SpiderClimbing condition
/// (concentration-bound) and bumps the target's speed by the +30ft
/// climb rider in `speed()`. Smaller bump than Fly but still a
/// meaningful kiting boost. Stacks with Fly when both are active.
#[test]
fn spider_climb_boosts_speed_and_starts_concentration() {
    use crate::actions::spells::{FLY, SPIDER_CLIMB};
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    let base_speed = e.actors[&ally].speed();
    let tv = vec![ally];
    let effs = SPIDER_CLIMB.side_effects(&mut e, wiz, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&ally].has_condition(Condition::SpiderClimbing),
        "spider climb should apply the SpiderClimbing condition"
    );
    let after_climb = e.actors[&ally].speed();
    assert!(
        after_climb > base_speed,
        "SpiderClimbing should boost speed: {} → {}",
        base_speed,
        after_climb
    );
    assert!(e.actors[&wiz].is_concentrating());
    // Drop concentration → buff drops off, speed returns to base.
    e.drop_concentration(wiz);
    assert!(
        !e.actors[&ally].has_condition(Condition::SpiderClimbing),
        "dropping concentration should strip SpiderClimbing"
    );
    assert_eq!(
        e.actors[&ally].speed(),
        base_speed,
        "speed should snap back to base when SpiderClimbing drops"
    );
    // Stacks with Fly — re-apply both and verify the second buff
    // adds on top of the first.
    let effs = SPIDER_CLIMB.side_effects(&mut e, wiz, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    let climb_only = e.actors[&ally].speed();
    // Pre-empt the existing Spider Climb concentration with Fly via
    // the caster's own concentration drop, then re-apply Fly through
    // a separate concentrator so the stack lands cleanly.
    let other = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 2), 0, 2)
        .unwrap();
    let effs = FLY.side_effects(&mut e, other, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    let both = e.actors[&ally].speed();
    assert!(
        both > climb_only,
        "stacking Fly on top of Spider Climb should add on top: {} → {}",
        climb_only,
        both
    );
}

