/// Flurry of Blows: grants the monk an extra Action so a second
/// martial-arts strike fits in the turn.
#[test]
fn flurry_of_blows_grants_extra_action() {
    use crate::actions::class_features::FLURRY_OF_BLOWS;
    use crate::actors::creatures::monks::MONK_TEMPLATE;
    use crate::engine::side_effects::Resource;
    let mut e = ei_with_terrain(15, 15, &[]);
    let monk = e
        .instantiate_creature(&MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Top up to default: 1 Action, 1 BonusAction.
    let m = e.actors.get_mut(&monk).unwrap();
    m.give_resource(Resource::Action);
    m.give_resource(Resource::BonusAction);
    let before = e.actors[&monk].action_slots();
    let effs = FLURRY_OF_BLOWS.side_effects(&mut e, monk, None, None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    let after = e.actors[&monk].action_slots();
    assert_eq!(
        after,
        before + 1,
        "flurry should grant +1 Action ({} → {})",
        before,
        after
    );
}

/// Stillness of Mind clears both Charmed and Frightened on the monk
/// in a single Action, and short-circuits cleanly (no-op
/// custom_validate_input → returns Skip-equivalent) when the monk
/// holds neither.
#[test]
fn stillness_of_mind_clears_charmed_and_frightened() {
    use crate::actions::class_features::STILLNESS_OF_MIND;
    use crate::actors::creatures::monks::MONK_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let monk = e
        .instantiate_creature(&MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Pin Charmed + Frightened on the monk so the cleanse has work
    // to do.
    e.actors.get_mut(&monk).unwrap().add_condition(
        Condition::Charmed,
        crate::conditions::ConditionTimer::Rounds(10),
    );
    e.actors.get_mut(&monk).unwrap().add_condition(
        Condition::Frightened,
        crate::conditions::ConditionTimer::Rounds(10),
    );
    assert!(STILLNESS_OF_MIND.custom_validate_input(&e, monk, None, None, None));
    let effs = STILLNESS_OF_MIND.side_effects(&mut e, monk, None, None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(!e.actors[&monk].has_condition(Condition::Charmed));
    assert!(!e.actors[&monk].has_condition(Condition::Frightened));
    // Validate that the action refuses to fire when neither is up
    // (no Action wasted on a stray click).
    assert!(!STILLNESS_OF_MIND.custom_validate_input(&e, monk, None, None, None));
}

/// Condition cohort helpers — verify the new attacker-disadvantage
/// table is populated correctly so the refactor of
/// `compute_attack_mode` doesn't silently drop a condition.
#[test]
fn condition_cohort_helpers_match_engine_behavior() {
    use crate::conditions::Condition;
    // Confused / Dominated must be in the attacker-disadvantage cohort.
    assert!(Condition::Confused.imposes_attacker_disadvantage());
    assert!(Condition::Dominated.imposes_attacker_disadvantage());
    // Legacy disadvantage sources still flag as such.
    assert!(Condition::Prone.imposes_attacker_disadvantage());
    assert!(Condition::Poisoned.imposes_attacker_disadvantage());
    assert!(Condition::HeatMetaled.imposes_attacker_disadvantage());
    // Confused blocks reactions (RAW: chaos table); NoReaction too.
    assert!(Condition::Confused.blocks_reactions());
    assert!(Condition::NoReaction.blocks_reactions());
    // Flying is a dispellable buff (concentration-anchored).
    assert!(Condition::Flying.is_dispellable_buff());
    // Entangled zeros movement (Plant Growth area).
    assert!(Condition::Entangled.zeros_movement());
    // Feebled imposes attacker disadvantage (the dazed mind clause).
    assert!(Condition::Feebled.imposes_attacker_disadvantage());
}

/// Magic Stone — cantrip ranged spell attack at 60ft with WIS-mod
/// damage. Validates the spell-attack pipeline goes through with a
/// bludgeoning typing (so resistance/immunity to BPS applies).
#[test]
fn magic_stone_lands_bludgeoning_via_spell_attack() {
    use crate::actions::spells::MAGIC_STONE;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    // Sweep seeds to find a hit (advantage isn't guaranteed at d20).
    let mut hit_landed = false;
    for seed in 0..40 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let d = e
            .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 2), 1, 0)
            .unwrap();
        let before = e.actors[&g].hitpoints();
        let tv = vec![g];
        let effects = MAGIC_STONE.side_effects(&mut e, d, Some(&tv), None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        if e.actors
            .get(&g)
            .is_some_and(|a| a.hitpoints() < before)
        {
            hit_landed = true;
            break;
        }
    }
    assert!(hit_landed, "magic stone never landed a bludgeoning hit");
}

/// Heroes' Feast — level-6 ally-burst buff. Grants temp HP, heal,
/// and Heroic to every ally in the burst centered on the targeted
/// tile. Skips enemies. Validates the temp-HP + Heroic install
/// path through the burst targeting helper.
#[test]
fn heroes_feast_buffs_allies_only() {
    use crate::actions::spells::HEROES_FEAST;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let c = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let f = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(6, 5), 0, 1)
        .unwrap();
    let g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(7, 5), 1, 0)
        .unwrap();
    // Wound the fighter so the heal half is observable.
    let max = e.actors[&f].max_hitpoints();
    e.actors.get_mut(&f).unwrap().take_damage(max / 2);
    let fighter_hp_pre = e.actors[&f].hitpoints();
    let goblin_hp_pre = e.actors[&g].hitpoints();
    // Cast on the cleric's own tile so the burst catches both allies
    // (the goblin is at gap=2 from this tile, just outside our
    // 6-tile radius — actually well inside).
    let tl = vec![Coordinate::new(5, 5)];
    let effects = HEROES_FEAST.side_effects(&mut e, c, None, Some(&tl), None);
    for ef in effects {
        ef.apply(&mut e);
    }
    // Allies got temp HP + Heroic; enemy untouched.
    assert!(
        e.actors[&c].temp_hp() > 0,
        "cleric should get temp HP from their own feast"
    );
    assert!(
        e.actors[&f].temp_hp() > 0,
        "ally in burst should get temp HP"
    );
    assert!(
        e.actors[&c].has_condition(Condition::Heroic),
        "cleric should be Heroic"
    );
    assert!(
        e.actors[&f].has_condition(Condition::Heroic),
        "ally should be Heroic"
    );
    assert_eq!(
        e.actors[&g].temp_hp(),
        0,
        "enemy in burst must NOT get temp HP"
    );
    assert!(
        !e.actors[&g].has_condition(Condition::Heroic),
        "enemy in burst must NOT get Heroic"
    );
    assert_eq!(
        e.actors[&g].hitpoints(),
        goblin_hp_pre,
        "enemy in burst must not be healed"
    );
    // Heal half landed on the wounded fighter.
    assert!(
        e.actors[&f].hitpoints() > fighter_hp_pre,
        "wounded ally should receive the feast's heal"
    );
}

/// Spike Stones lays the same thorny ground its smaller sibling
/// does, over a wider patch, and charges by the tile for it —
/// friend and foe alike, since the stones are the ground.
#[test]
fn spike_stones_lays_thorny_ground_and_bills_by_the_tile() {
    use crate::actions::spells::SPIKE_STONES;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    use crate::engine::side_effects::MoveActor;
    let mut e = ei_with_terrain(30, 30, &[]);
    let druid = e
        .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(2, 20), 1, 0)
        .unwrap();
    let centre = Coordinate::new(20, 20);
    for ef in SPIKE_STONES.side_effects(&mut e, druid, None, Some(&vec![centre]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 1);
    assert_eq!(e.zone_movement_multiplier(centre), 2.0);
    assert!(e.actors[&druid].is_concentrating());
    let before = e.actors[&ogre].hitpoints();
    MoveActor {
        actor_id: ogre,
        path: (17..=19).map(|x| Coordinate::new(x, 20)).collect(),
    }
    .apply(&mut e);
    assert!(
        e.actors[&ogre].hitpoints() < before,
        "walking into the stones should cost the walker"
    );
    e.drop_concentration(druid);
    assert!(e.zones().is_empty());
}

/// Mind Flayer's Mind Blast — burst, INT save halves, fail also
/// applies Stunned. Validates the enemy-only filter (allies in cone
/// skip both damage and stun) and the save partition.
#[test]
fn mind_blast_burst_stuns_failing_enemies_only() {
    use crate::actions::monster_attacks::MIND_FLAYER_MIND_BLAST;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::mind_flayers::MIND_FLAYER_TEMPLATE;
    // Sweep seeds to find a target failing the INT save (goblins
    // have INT 10 = +0 vs the flayer's high spell DC, so failures
    // are very common).
    let mut stun_landed = false;
    for seed in 0..30 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let flayer = e
            .instantiate_creature(&MIND_FLAYER_TEMPLATE, Coordinate::new(2, 2), 1, 0)
            .unwrap();
        let g_enemy = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g_ally = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 1)
            .unwrap();
        let tl = vec![Coordinate::new(5, 5)];
        let effects = MIND_FLAYER_MIND_BLAST.side_effects(
            &mut e,
            flayer,
            None,
            Some(&tl),
            None,
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        // Ally goblin (same team as flayer) must never be hit by
        // the cone — enemy_burst_targets filters them out.
        assert!(
            !e.actors[&g_ally].has_condition(Condition::Stunned),
            "ally in cone must not be Stunned"
        );
        if e.actors[&g_enemy].has_condition(Condition::Stunned) {
            stun_landed = true;
            break;
        }
    }
    assert!(
        stun_landed,
        "mind blast never stunned an enemy across 30 seeds"
    );
}

