/// Pushing Attack primes PushingAttacking and, on a connecting
/// melee hit, fires the new `FollowUpEffect::Push` rider — the
/// target should land further from the attacker than they started
/// (or stay put if the save passed; we sweep seeds until a fail
/// lands). Validates the new push-only follow-up shape end-to-end.
#[test]
fn pushing_attack_displaces_target_on_failed_save() {
    use crate::actions::class_features::PUSHING_ATTACK;
    use crate::actions::monster_attacks::SCIMITAR;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut pushed_any = false;
    for seed in 0..80 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let start_loc = e.actors[&g].location();
        let effects = PUSHING_ATTACK.side_effects(&mut e, f, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(e.actors[&f].has_condition(Condition::PushingAttacking));
        let tv = vec![g];
        let weapon_effects = SCIMITAR.side_effects(&mut e, f, Some(&tv), None, None);
        for ef in weapon_effects {
            ef.apply(&mut e);
        }
        // Goblin may have died on the hit; if alive, check the loc.
        if let Some(goblin) = e.actors.get(&g) {
            if goblin.location() != start_loc {
                pushed_any = true;
                break;
            }
        } else {
            // Killed — that's still a valid outcome (the swing did its
            // job before the rider could push). Skip this seed; the
            // sweep is wide enough to find a non-killing hit.
            continue;
        }
    }
    assert!(
        pushed_any,
        "pushing attack never moved the goblin across 80 seeds"
    );
}

/// Goaded condition + Goaded back-link force disadvantage on attacks
/// against anyone other than the goader. Verifies the
/// `compute_attack_mode` clause and the link auto-clear when the
/// condition is removed.
#[test]
fn goaded_attack_mode_imposes_disadvantage_on_off_target() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::conditions::ConditionTimer;
    let mut e = ei_with_terrain(15, 15, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let other_ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    // Wire the goblin as Goaded by the fighter.
    {
        let g = e.actors.get_mut(&goblin).unwrap();
        g.add_condition(Condition::Goaded, ConditionTimer::UntilStartOfNextTurn);
        g.set_condition_link(Condition::Goaded, Some(fighter));
    }
    // Attacking the goader (fighter): no disadvantage from the goad.
    let mode_vs_goader = e.compute_attack_mode(goblin, fighter, true);
    assert_ne!(
        mode_vs_goader,
        RollMode::Disadvantage,
        "attacks against the goader bypass the goad rider"
    );
    // Attacking anyone else: goad clause applies disadvantage.
    let mode_vs_ally = e.compute_attack_mode(goblin, other_ally, true);
    assert_eq!(
        mode_vs_ally,
        RollMode::Disadvantage,
        "attacks vs off-target eat goad disadvantage"
    );
    // Removing the condition clears the link automatically.
    e.actors
        .get_mut(&goblin)
        .unwrap()
        .remove_condition(Condition::Goaded);
    assert!(e.actors[&goblin].linked_by(Condition::Goaded).is_none());
}

/// Distracting Strike primed + a melee swing that lands tags the
/// target Distracted and wires the `Distracted` back-link onto the
/// fighter. Exercises the full prime → hit → rider chain (rider
/// table consume_on_trigger + push_follow_up_effect's chained
/// SetConditionLink(Distracted) emission), not just the prime install. Probes
/// across RNG seeds because the swing has to actually hit at least
/// once for the rider to fire.
#[test]
fn distracting_strike_rider_applies_distracted_on_hit() {
    use crate::actions::class_features::DISTRACTING_ATTACK;
    use crate::actions::monster_attacks::SCIMITAR;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    let mut applied = false;
    for seed in 0..80 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        // Prime distracting strike.
        let prime_effects = DISTRACTING_ATTACK.side_effects(&mut e, f, None, None, None);
        for ef in prime_effects {
            ef.apply(&mut e);
        }
        assert!(e.actors[&f].has_condition(Condition::DistractingAttacking));
        // Swing.
        let tv = vec![g];
        let weapon_effects = SCIMITAR.side_effects(&mut e, f, Some(&tv), None, None);
        for ef in weapon_effects {
            ef.apply(&mut e);
        }
        // If the goblin survived the swing AND was tagged, the rider
        // fired correctly. Check Distracted back-link too.
        if let Some(goblin) = e.actors.get(&g)
            && goblin.has_condition(Condition::Distracted)
        {
            assert_eq!(
                goblin.linked_by(Condition::Distracted),
                Some(f),
                "Distracted back-link should point at the fighter"
            );
            // Prime should be consumed on the hit.
            assert!(!e.actors[&f].has_condition(Condition::DistractingAttacking));
            applied = true;
            break;
        }
    }
    assert!(
        applied,
        "distracting strike rider never landed across 80 seeds"
    );
}

/// Maneuvering Attack primed + a melee swing that lands moves an ally
/// who is out of position. A melee ally with nothing in reach closes
/// with its nearest enemy, and pays a reaction for the step.
#[test]
fn maneuvering_attack_closes_a_stranded_melee_ally_with_the_fight() {
    use crate::actions::class_features::MANEUVERING_ATTACK;
    use crate::actions::monster_attacks::SCIMITAR;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut moved = false;
    for seed in 0..80 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(7, 5), 1, 0)
            .unwrap();
        // A second fighter parked across the room with nothing in
        // reach: a melee body that is not where it wants to be, which
        // is exactly the ally RAW's "more advantageous position" is
        // about.
        let ally = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(15, 5), 0, 1)
            .unwrap();
        let prime = MANEUVERING_ATTACK.side_effects(&mut e, f, None, None, None);
        for ef in prime {
            ef.apply(&mut e);
        }
        assert!(e.actors[&f].has_condition(Condition::ManeuveringAttacking));
        let ally_start = e.actors[&ally].location();
        let tv = vec![g];
        let swing = SCIMITAR.side_effects(&mut e, f, Some(&tv), None, None);
        for ef in swing {
            ef.apply(&mut e);
        }
        // Only a landed swing cashes the prime.
        if e.actors[&f].has_condition(Condition::ManeuveringAttacking) {
            continue;
        }
        let ally_end = e.actors[&ally].location();
        assert!(
            ally_end.x < ally_start.x,
            "seed {}: the stranded ally should have closed with the goblin ({} -> {})",
            seed,
            ally_start,
            ally_end
        );
        assert!(
            !e.actors[&ally].can_consume_resource(Resource::Reaction),
            "seed {}: RAW charges the move to the ally's own reaction",
            seed
        );
        moved = true;
        break;
    }
    assert!(moved, "maneuvering attack never landed across 80 seeds");
}

/// The other half of the same rule: an ally who fights at range and has
/// something in its face is moved *away* from it. Same maneuver, same
/// die, opposite direction — the direction is a fact about the ally's
/// weapon rather than about the maneuver.
#[test]
fn maneuvering_attack_pulls_a_cornered_caster_out_of_reach() {
    use crate::actions::class_features::MANEUVERING_ATTACK;
    use crate::actions::monster_attacks::SCIMITAR;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;

    let mut moved = false;
    for seed in 0..80 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(7, 5), 1, 0)
            .unwrap();
        // The wizard is standing next to the goblin, which for a
        // creature with no melee weapon is the wrong side of the room.
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(9, 5), 0, 1)
            .unwrap();
        let prime = MANEUVERING_ATTACK.side_effects(&mut e, f, None, None, None);
        for ef in prime {
            ef.apply(&mut e);
        }
        let start = e.actors[&wizard].location();
        let tv = vec![g];
        let swing = SCIMITAR.side_effects(&mut e, f, Some(&tv), None, None);
        for ef in swing {
            ef.apply(&mut e);
        }
        if e.actors[&f].has_condition(Condition::ManeuveringAttacking) {
            continue;
        }
        let end = e.actors[&wizard].location();
        assert!(
            end.x > start.x,
            "seed {}: the cornered wizard should have backed off ({} -> {})",
            seed,
            start,
            end
        );
        moved = true;
        break;
    }
    assert!(moved, "maneuvering attack never landed across 80 seeds");
}

/// Nobody out of position, nobody moved — and the maneuver still costs
/// its die, because RAW's fighter has already committed it by the time
/// the comrade declines the step. The AI is what keeps that from
/// happening; the resolver just has to not crash or move somebody who
/// was fine where they were.
#[test]
fn maneuvering_attack_finds_nobody_when_every_ally_is_where_it_wants_to_be() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut e = ei_with_terrain(20, 20, &[]);
    let f = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let _g = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(7, 5), 1, 0)
        .unwrap();
    // A melee ally already toe to toe with the goblin.
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(9, 5), 0, 1)
        .unwrap();
    assert!(
        crate::engine::attack::maneuverable_ally(&e, f).is_none(),
        "an engaged melee ally is not out of position"
    );
    // …and the AI does not spend the die on it.
    assert!(
        !e.actors[&ally].has_condition(Condition::ManeuveringAttacking),
        "sanity: the ally is not the one priming"
    );
}

/// Distracted condition + Distracted back-link grant advantage to
/// attackers *other* than the fighter who tagged the target.
/// Symmetric inverse of the goaded test: same plumbing, flipped
/// polarity (target-side advantage vs attacker-side disadvantage).
#[test]
fn distracted_attack_mode_grants_advantage_to_off_attackers() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::conditions::ConditionTimer;
    let mut e = ei_with_terrain(15, 15, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let other_ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    // Tag the goblin as Distracted by the fighter.
    {
        let g = e.actors.get_mut(&goblin).unwrap();
        g.add_condition(Condition::Distracted, ConditionTimer::UntilStartOfNextTurn);
        g.set_condition_link(Condition::Distracted, Some(fighter));
    }
    // Fighter (the distractor) attacking the goblin: no advantage
    // from their own setup — RAW: "an attacker other than you."
    let mode_self = e.compute_attack_mode(fighter, goblin, true);
    assert_ne!(
        mode_self,
        RollMode::Advantage,
        "the distractor gets no advantage from their own setup",
    );
    // Other ally attacking the goblin: gets advantage from the
    // Distracted rider.
    let mode_ally = e.compute_attack_mode(other_ally, goblin, true);
    assert_eq!(
        mode_ally,
        RollMode::Advantage,
        "ally swing benefits from the distracter's setup",
    );
    // Removing the condition clears the link automatically.
    e.actors
        .get_mut(&goblin)
        .unwrap()
        .remove_condition(Condition::Distracted);
    assert!(e.actors[&goblin].linked_by(Condition::Distracted).is_none());
}

