/// Banishing Smite HP-threshold gate: the rider banishes only "if
/// this damage reduces the target to 50 hp or fewer." Verifies the
/// predicted-post-damage gate by smacking a goblin (low HP) versus
/// a stone golem (very high HP) — the goblin should get banished
/// (Mazed) when the smite lands; the stone golem (>50 HP after the
/// smite) should not.
#[test]
fn banishing_smite_banishes_below_threshold_only() {
    use crate::actions::monster_attacks::GREATSWORD;
    use crate::actions::spells::BANISHING_SMITE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
    use crate::actors::creatures::stone_golems::STONE_GOLEM_TEMPLATE;

    // Below threshold: goblin (~7 HP) should be banished on hit.
    // Sweep seeds because the swing must land (paladin attack vs
    // goblin AC 15) and the smite rider must roll high enough.
    let mut goblin_banished = false;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain(15, 15, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let pal = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        // Prime the smite, then make a melee swing at the adjacent
        // goblin. The on-hit rider table handles the rest.
        for ef in BANISHING_SMITE.side_effects(&mut e, pal, None, None, None) {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&pal].has_condition(Condition::BanishingSmiting),
            "smite prime should be installed"
        );
        for ef in GREATSWORD.side_effects(&mut e, pal, Some(&vec![goblin]), None, None) {
            ef.apply(&mut e);
        }
        if e.actors
            .get(&goblin)
            .is_some_and(|a| a.has_condition(Condition::Banished))
        {
            goblin_banished = true;
            break;
        }
    }
    assert!(
        goblin_banished,
        "Banishing Smite should banish a low-HP goblin when the swing lands"
    );

    // Above threshold: stone golem (~178 HP) should NOT be banished
    // — predicted post-damage HP stays well above 50.
    let mut e = ei_with_terrain(15, 15, &[]);
    let pal = e
        .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let golem = e
        .instantiate_creature(&STONE_GOLEM_TEMPLATE, Coordinate::new(3, 2), 1, 0)
        .unwrap();
    for ef in BANISHING_SMITE.side_effects(&mut e, pal, None, None, None) {
        ef.apply(&mut e);
    }
    // Drive several swings to ensure at least one lands.
    for _ in 0..5 {
        for ef in GREATSWORD.side_effects(&mut e, pal, Some(&vec![golem]), None, None) {
            ef.apply(&mut e);
        }
        // If the smite prime is consumed and golem stays unbanished,
        // we've validated the threshold gate.
        if !e.actors[&pal].has_condition(Condition::BanishingSmiting) {
            break;
        }
    }
    assert!(
        !e.actors
            .get(&golem)
            .is_some_and(|a| a.has_condition(Condition::Banished)),
        "Stone Golem stays above the 50-HP threshold — banish should be blocked"
    );
}

/// Glabrezu template: CR-9 demon. Verifies the demon envelope:
/// poison immunity, cold/fire/lightning/B/P/S resistance, and the
/// Charmed/Frightened/Poisoned condition immunities. Confirms the
/// 4-swing multiattack lane is present.
#[test]
fn glabrezu_template_carries_demon_envelope() {
    use crate::actors::creatures::glabrezus::GLABREZU_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&GLABREZU_TEMPLATE, Coordinate::new(5, 5), 1, 0)
        .unwrap();
    let g = &e.actors[&id];
    assert!(g.is_immune_to(DamageType::Poison));
    assert!(g.is_resistant_to(DamageType::Cold));
    assert!(g.is_resistant_to(DamageType::Fire));
    assert!(g.is_resistant_to(DamageType::Lightning));
    assert!(g.resists_nonmagical(DamageType::Bludgeoning));
    assert!(g.is_immune_to_condition(Condition::Poisoned));
    assert!(g.is_immune_to_condition(Condition::Charmed));
    assert!(g.is_immune_to_condition(Condition::Frightened));
    // Not legendary — Glabrezus aren't demon princes.
    assert_eq!(g.legendary_resistance_max(), 0);
    assert!(g.find_action("glabrezu pincer").is_some());
    assert!(g.find_action("glabrezu fist").is_some());
    assert!(g.find_action("glabrezu multiattack").is_some());
}

/// Sphered / WindWalled / StaggeringSmiting / BanishingSmiting all
/// join the dispellable-buff cohort so Dispel Magic can strip them.
/// Sphered is the only debuff in the cohort — it sits in
/// `is_dispellable_buff` so Dispel Magic on the trapped creature
/// can shatter the sphere as a friendly utility. The three smite /
/// wind buffs are conventional buffs.
#[test]
fn new_buffs_join_dispellable_cohort() {
    assert!(Condition::WindWalled.is_dispellable_buff());
    assert!(Condition::StaggeringSmiting.is_dispellable_buff());
    assert!(Condition::BanishingSmiting.is_dispellable_buff());
    assert!(Condition::ThunderousSmiting.is_dispellable_buff());
    // Sphered is a debuff but still dispel-removable (the sphere is
    // the magical effect; dispel cracks it). We don't put it in
    // `is_dispellable_buff` since that cohort is read for buff
    // stripping; Sphered drops via concentration cleanup instead.
    assert!(!Condition::Sphered.is_dispellable_buff());
}

/// Drift-prevention: every SmiteSpell-chassis prime (paladin +
/// ranger flavors) must register through the shared
/// `is_smite_prime()` helper so the `is_dispellable_buff` sweep
/// picks them up without a duplicate row on the explicit OR list.
/// Locks the promotion of the three ranger smite primes
/// (`LightningArrowPrimed` / `EnsnaringStriking` / `ZephyrStriking`)
/// into `is_smite_prime` — same lane as the paladin family — so a
/// future ranger smite spell (a hypothetical Sunbeam Strike, Storm
/// Strike, etc.) that adds a `_Primed` / `_Striking` condition
/// and wires it into `is_smite_prime` picks up the dispel + double-
/// prime-gate + AI concentration bookkeeping for free without a
/// second edit on the `is_dispellable_buff` explicit-OR block.
#[test]
fn every_smite_spell_prime_registers_via_is_smite_prime() {
    // Paladin family — the seven SmiteSpell prime conditions plus
    // the two class-feature Smite primes (Divine Smite + Divine
    // Strike). Every entry must return true from is_smite_prime().
    for prime in [
        Condition::Smiting,
        Condition::SearingSmiting,
        Condition::WrathfulSmiting,
        Condition::BrandingSmiting,
        Condition::BlindingSmiting,
        Condition::StaggeringSmiting,
        Condition::BanishingSmiting,
        Condition::ThunderousSmiting,
        Condition::DivineStriking,
        Condition::LightningArrowPrimed,
        Condition::EnsnaringStriking,
        Condition::ZephyrStriking,
    ] {
        assert!(
            prime.is_smite_prime(),
            "expected {:?} to route through is_smite_prime",
            prime
        );
        assert!(
            prime.is_dispellable_buff(),
            "expected {:?} to route through is_dispellable_buff via is_smite_prime",
            prime
        );
    }
    // A non-smite prime (Bless / MageArmored) doesn't route
    // through is_smite_prime but still lands as dispellable via
    // the explicit-OR list — sanity-check the negation so a future
    // over-broad expansion of is_smite_prime doesn't silently
    // collapse the two lanes.
    assert!(!Condition::Blessed.is_smite_prime());
    assert!(Condition::Blessed.is_dispellable_buff());
}

/// Thunderous Smite (lv1 paladin evocation): bonus-action prime that
/// adds +2d6 thunder + STR-save Prone on the next melee hit. Verifies
/// the prime install + concentration mark.
#[test]
fn thunderous_smite_primes_thunder_rider() {
    use crate::actions::spells::THUNDEROUS_SMITE;
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let pal = e
        .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    for ef in THUNDEROUS_SMITE.side_effects(&mut e, pal, None, None, None) {
        ef.apply(&mut e);
    }
    assert!(e.actors[&pal].has_condition(Condition::ThunderousSmiting));
    assert!(e.actors[&pal].is_concentrating());
    assert_eq!(
        e.actors[&pal]
            .concentration()
            .map(|c| c.spell_name.as_str()),
        Some("Thunderous Smite")
    );
}

/// Thunderous Smite landing-prone follow-up: the smite rider's STR
/// save (vs the paladin's CHA-based DC) gates Prone on fail. Sweep
/// seeds until both the swing and the save outcome resolve to a
/// proned goblin — confirms the prime → swing → prone path works
/// end-to-end.
#[test]
fn thunderous_smite_prones_failed_save() {
    use crate::actions::monster_attacks::GREATSWORD;
    use crate::actions::spells::THUNDEROUS_SMITE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;

    let mut goblin_proned = false;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain(15, 15, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let pal = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        for ef in THUNDEROUS_SMITE.side_effects(&mut e, pal, None, None, None) {
            ef.apply(&mut e);
        }
        for ef in GREATSWORD.side_effects(&mut e, pal, Some(&vec![goblin]), None, None) {
            ef.apply(&mut e);
        }
        if e.actors
            .get(&goblin)
            .is_some_and(|a| a.has_condition(Condition::Prone))
        {
            goblin_proned = true;
            break;
        }
    }
    assert!(
        goblin_proned,
        "Thunderous Smite should knock a goblin prone on a failed STR save"
    );
}

/// Lightning Lure (sorcerer/warlock/wizard cantrip): STR-save pull
/// toward caster + 1d8 lightning if the pull lands the target within
/// 5 ft. Verifies the pull-and-damage chain end-to-end against a
/// goblin standing 5 tiles east of a wizard (just inside the 6-tile
/// reach but outside the post-pull 5ft window — the 4-tile pull
/// should drop them onto an adjacent tile).
#[test]
fn lightning_lure_pulls_and_zaps_failed_save() {
    use crate::actions::spells::LIGHTNING_LURE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;

    let mut zapped = false;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain(15, 15, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 7), 0, 0)
            .unwrap();
        let start_x = 10;
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(start_x, 7), 1, 0)
            .unwrap();
        let goblin_hp_before = e.actors[&goblin].hitpoints();
        for ef in LIGHTNING_LURE.side_effects(&mut e, wiz, Some(&vec![goblin]), None, None) {
            ef.apply(&mut e);
        }
        // If the save fails, the goblin gets pulled (x decreases)
        // and zapped (HP drops).
        if e.actors
            .get(&goblin)
            .is_some_and(|a| a.location().x < start_x && a.hitpoints() < goblin_hp_before)
        {
            zapped = true;
            break;
        }
    }
    assert!(
        zapped,
        "Lightning Lure should pull and zap a goblin on a failed STR save"
    );
}

