/// `zone_sustained_by` is the handle the steered spells re-enter
/// through, and it is scoped to the owner: two druids with two
/// moonbeams each find their own.
#[test]
fn a_sustained_zone_is_found_by_its_owner_and_not_by_anybody_else() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut e = ei_with_terrain(20, 20, &[]);
    let mine = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let theirs = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 4), 1, 0)
        .unwrap();
    let mut z = restraining_zone(Coordinate::new(10, 10), 1, 10);
    z.owner_id = mine;
    z.name = "beam";
    e.install_zone(z);
    assert!(e.zone_sustained_by(mine, "beam").is_some());
    assert!(e.zone_sustained_by(theirs, "beam").is_none());
    assert!(e.zone_sustained_by(mine, "some other spell").is_none());
}

/// Hunger of Hadar needs two coincident zones to hold three RAW
/// clauses: the dark and its automatic cold on one, the saved-for
/// acid on the other. Both are held by the same concentration, so
/// the void arrives and leaves as one thing.
#[test]
fn hunger_of_hadar_opens_as_two_coincident_zones() {
    use crate::actions::spells::HUNGER_OF_HADAR;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    use crate::actors::creatures::warlocks::WARLOCK_TEMPLATE;

    let mut e = ei_with_terrain(30, 30, &[]);
    let lock = e
        .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(2, 10), 0, 0)
        .unwrap();
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(16, 10), 1, 0)
        .unwrap();
    let centre = Coordinate::new(16, 10);
    for ef in HUNGER_OF_HADAR.side_effects(&mut e, lock, None, Some(&vec![centre]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 2, "the dark and the acid are separate zones");
    assert!(e.tile_is_obscured(centre));
    assert!(!e.viewer_can_see(lock, ogre));
    // Neither clause has a "when it appears" trigger, so opening the
    // void costs the ogre nothing until its own turn comes round.
    let before = e.actors[&ogre].hitpoints();
    assert_eq!(before, e.actors[&ogre].max_hitpoints());
    e.start_turn_for(ogre);
    assert!(
        e.actors[&ogre].hitpoints() < before,
        "a turn opened inside the void is billed for it"
    );
    // One concentration, both halves.
    e.drop_concentration(lock);
    assert!(e.zones().is_empty());
}

/// Silence is a "while you are in here" condition, which the layer
/// expresses as an `UntilStartOfNextTurn` install the zone renews
/// every turn. A caster who walks out is free on their next turn; a
/// caster who walks in is not.
#[test]
fn silence_follows_the_sphere_rather_than_the_creature() {
    use crate::actions::spells::SILENCE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::MoveActor;

    let mut e = ei_with_terrain(40, 40, &[]);
    let caster = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let inside = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(20, 20), 1, 0)
        .unwrap();
    let outside = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(35, 35), 1, 1)
        .unwrap();
    let centre = Coordinate::new(20, 20);
    for ef in SILENCE.side_effects(&mut e, caster, None, Some(&vec![centre]), None) {
        ef.apply(&mut e);
    }
    assert!(e.actors[&inside].has_condition(Condition::Silenced));
    assert!(!e.actors[&outside].has_condition(Condition::Silenced));
    // Still inside at the top of its turn: the hush is renewed.
    e.start_turn_for(inside);
    assert!(e.actors[&inside].has_condition(Condition::Silenced));
    // Walk clear, and the timer lapses on the next turn instead of
    // riding along for the full minute.
    MoveActor {
        actor_id: inside,
        path: vec![Coordinate::new(35, 20)],
    }
    .apply(&mut e);
    e.start_turn_for(inside);
    assert!(!e.actors[&inside].has_condition(Condition::Silenced));
    // And walking in picks it up, which the cast-time install never
    // did.
    MoveActor {
        actor_id: outside,
        path: vec![Coordinate::new(21, 21)],
    }
    .apply(&mut e);
    assert!(e.actors[&outside].has_condition(Condition::Silenced));
}

/// Fog Cloud lays a heavy-obscurement zone rather than marking the
/// creatures who happened to be standing there. Verifies the lv1
/// slot cost, the zone install, that sight through the cloud fails
/// both ways while sight clear of it still works, and that dropping
/// concentration takes the cloud off the board.
#[test]
fn fog_cloud_lays_an_obscuring_zone_under_concentration() {
    use crate::actions::spells::FOG_CLOUD;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(30, 30, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    // Standing inside the cloud.
    let inside = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(12, 5), 1, 0)
        .unwrap();
    // Well clear of it, on the far side.
    let far = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(20, 5), 1, 0)
        .unwrap();
    let center = Coordinate::new(10, 5);
    let costs = FOG_CLOUD.cost(&e, wiz, None, Some(&vec![center]), None);
    assert!(costs.iter().any(|c| matches!(c, Resource::SpellSlot(1))));
    assert!(e.viewer_can_see(wiz, inside));
    for ef in FOG_CLOUD.side_effects(&mut e, wiz, None, Some(&vec![center]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 1);
    assert!(e.tile_is_obscured(center));
    // The obscurement is a property of the ground, not a mark on
    // anyone: nobody picks up a condition.
    assert!(!e.actors[&inside].has_condition(Condition::Blinded));
    // Sight into the cloud fails, and so does sight out of it —
    // heavy obscurement is symmetric.
    assert!(!e.viewer_can_see(wiz, inside));
    assert!(!e.viewer_can_see(inside, wiz));
    // The wizard's line to the far goblin runs straight through the
    // cloud, so that fails too…
    assert!(!e.viewer_can_see(wiz, far));
    // …while a line that never touches it is unaffected.
    let clear = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 20), 1, 0)
        .unwrap();
    assert!(e.viewer_can_see(wiz, clear));
    assert!(e.actors[&wiz].is_concentrating());
    // Concentration drop takes the cloud off the map.
    e.drop_concentration(wiz);
    assert!(e.zones().is_empty());
    assert!(!e.tile_is_obscured(center));
    assert!(e.viewer_can_see(wiz, inside));
    assert!(!e.actors[&wiz].is_concentrating());
}

/// Moonbeam's second clause: "on each of your turns after you cast
/// this spell, you can use an action to move the beam up to 60
/// feet." The recast costs an action and *no slot*, moves the beam
/// the druid already has rather than laying a second one, and keeps
/// the concentration it was cast under.
#[test]
fn a_second_moonbeam_walks_the_first_one_instead_of_laying_another() {
    use crate::actions::spells::MOONBEAM;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(60, 20, &[]);
    let druid = e
        .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 10), 0, 0)
        .unwrap();
    let first = Coordinate::new(10, 10);
    let cast = |e: &mut EncounterInstance, at: Coordinate| {
        for ef in MOONBEAM.side_effects(e, druid, None, Some(&vec![at]), None) {
            ef.apply(e);
        }
    };
    assert!(
        MOONBEAM
            .cost(&e, druid, None, Some(&vec![first]), None)
            .iter()
            .any(|c| matches!(c, Resource::SpellSlot(2))),
        "the first cast is a level-2 slot"
    );
    cast(&mut e, first);
    assert_eq!(e.zones().len(), 1);
    assert!(e.actors[&druid].is_concentrating());

    // With the beam up, the spell prices itself as an action alone.
    let second = Coordinate::new(20, 10);
    let recast = MOONBEAM.cost(&e, druid, None, Some(&vec![second]), None);
    assert!(
        !recast.iter().any(|c| matches!(c, Resource::SpellSlot(_))),
        "walking the beam costs no second slot"
    );
    assert!(recast.iter().any(|c| matches!(c, Resource::Action)));
    cast(&mut e, second);
    assert_eq!(e.zones().len(), 1, "one beam, moved — not two beams");
    assert_eq!(e.zones()[0].origin, second);
    assert!(
        e.actors[&druid].is_concentrating(),
        "the druid never let go, so the beam it is walking must survive"
    );
}

/// The leash is real: "up to 60 feet" is 24 tiles from where the
/// beam *is*, and a destination past it is not a legal move.
#[test]
fn a_moonbeam_cannot_be_walked_further_than_its_own_range() {
    use crate::actions::spells::MOONBEAM;
    use crate::actors::creatures::druids::DRUID_TEMPLATE;

    let mut e = ei_with_terrain(80, 20, &[]);
    let druid = e
        .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 10), 0, 0)
        .unwrap();
    let first = Coordinate::new(10, 10);
    for ef in MOONBEAM.side_effects(&mut e, druid, None, Some(&vec![first]), None) {
        ef.apply(&mut e);
    }
    let far = Coordinate::new(70, 10);
    assert!(
        !MOONBEAM.custom_validate_input(&e, druid, None, Some(&vec![far]), None),
        "60 tiles is well past the beam's 24-tile step"
    );
    let near = Coordinate::new(30, 10);
    assert!(MOONBEAM.custom_validate_input(&e, druid, None, Some(&vec![near]), None));
}

/// Flaming Sphere's bonus-action roll. Same idiom as Moonbeam, a
/// different resource — which is the whole difference between the
/// two spells' turns.
#[test]
fn a_flaming_sphere_rolls_for_a_bonus_action() {
    use crate::actions::spells::FLAMING_SPHERE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(40, 20, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 10), 0, 0)
        .unwrap();
    let first = Coordinate::new(10, 10);
    for ef in FLAMING_SPHERE.side_effects(&mut e, wiz, None, Some(&vec![first]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 1, "the sphere is a place, not an event");
    let roll_to = Coordinate::new(16, 10);
    let recast = FLAMING_SPHERE.cost(&e, wiz, None, Some(&vec![roll_to]), None);
    assert!(recast.iter().any(|c| matches!(c, Resource::BonusAction)));
    assert!(!recast.iter().any(|c| matches!(c, Resource::SpellSlot(_))));
    for ef in FLAMING_SPHERE.side_effects(&mut e, wiz, None, Some(&vec![roll_to]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 1);
    assert_eq!(e.zones()[0].origin, roll_to);
}

/// Cloudkill's third clause: the fog rolls 10 ft away from the
/// wizard at the top of every one of the wizard's turns, and takes
/// its poison with it.
#[test]
fn a_cloudkill_rolls_away_from_the_wizard_who_cast_it() {
    use crate::actions::spells::CLOUDKILL;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;

    let mut e = ei_with_terrain(60, 20, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 10), 0, 0)
        .unwrap();
    let center = Coordinate::new(20, 10);
    for ef in CLOUDKILL.side_effects(&mut e, wiz, None, Some(&vec![center]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 1);
    assert!(e.tile_is_obscured(center), "its area is heavily obscured");
    e.start_turn_for(wiz);
    assert_eq!(
        e.zones()[0].origin,
        Coordinate::new(24, 10),
        "four tiles further down the line the wizard cast it along"
    );
    assert!(e.tile_is_obscured(Coordinate::new(24, 10)));
}

/// Incendiary Cloud is Cloudkill's level-8 sibling and is built the
/// same way: a concentration-held, obscuring, drifting area rather
/// than a one-shot burst that leaves nothing behind.
#[test]
fn an_incendiary_cloud_is_a_place_that_drifts_and_not_a_detonation() {
    use crate::actions::spells::INCENDIARY_CLOUD;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;

    let mut e = ei_with_terrain(60, 20, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 10), 0, 0)
        .unwrap();
    let center = Coordinate::new(20, 10);
    for ef in INCENDIARY_CLOUD.side_effects(&mut e, wiz, None, Some(&vec![center]), None) {
        ef.apply(&mut e);
    }
    assert_eq!(e.zones().len(), 1);
    assert!(e.tile_is_obscured(center));
    assert!(e.actors[&wiz].is_concentrating());
    e.start_turn_for(wiz);
    assert_eq!(e.zones()[0].origin, Coordinate::new(24, 10));
    // And the concentration anchor still reaches it.
    e.drop_concentration(wiz);
    assert!(e.zones().is_empty());
}

/// Gust of Wind: lv2 concentration line push. Verifies the lv2 slot
/// cost, that an enemy in the wind's path is pushed away from the
/// caster on a failed STR save (driven across seeds), and the caster
/// picks up concentration.
#[test]
fn gust_of_wind_pushes_in_wind_path() {
    use crate::actions::spells::GUST_OF_WIND;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut pushed = false;
    let mut concentrated = false;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain(30, 30, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 5), 0, 0)
            .unwrap();
        // Goblin on the wind's east-bound path.
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 5), 1, 0)
            .unwrap();
        // Target tile to the east — defines the wind direction.
        let target = Coordinate::new(20, 5);
        let costs = GUST_OF_WIND.cost(&e, wiz, None, Some(&vec![target]), None);
        assert!(costs.iter().any(|c| matches!(c, Resource::SpellSlot(2))));
        let start_loc = e.actors[&g].location();
        for ef in GUST_OF_WIND.side_effects(&mut e, wiz, None, Some(&vec![target]), None) {
            ef.apply(&mut e);
        }
        if e.actors[&wiz].is_concentrating() {
            concentrated = true;
        }
        // Goblin pushed east (further from caster at x=2).
        if e.actors[&g].location().x > start_loc.x {
            pushed = true;
        }
        if pushed && concentrated {
            break;
        }
    }
    assert!(concentrated, "Gust of Wind should anchor caster concentration");
    assert!(pushed, "Gust of Wind should eventually push the goblin away on a failed STR save");
}

/// 5e Faerie Fire / Starry Wisp: *"the affected creature can't benefit
/// from the Invisible condition."*
///
/// The rule the engine used to carry only in a docstring. An outlined
/// invisible creature contributed one advantage (the outline) and one
/// disadvantage (the invisibility) and the tally cancelled them to a
/// straight roll — so casting Faerie Fire on something already
/// invisible bought the party nothing at all, which is the opposite of
/// what the spell is for.
#[test]
fn an_outline_burns_off_the_invisibility_underneath_it() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut e = ei_with_terrain(20, 20, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();

    // Invisible alone: the swing is at disadvantage.
    e.actors
        .get_mut(&goblin)
        .unwrap()
        .add_condition(Condition::Invisible, ConditionTimer::Rounds(5));
    assert_eq!(
        e.attack_mode_tally(fighter, goblin, true).resolve(),
        RollMode::Disadvantage,
        "an invisible target is hard to hit"
    );

    // Outlined on top of it: the outline's advantage lands and the
    // invisibility is worth nothing, so the swing comes out at
    // advantage rather than cancelling to a straight roll.
    e.actors
        .get_mut(&goblin)
        .unwrap()
        .add_condition(Condition::Outlined, ConditionTimer::Rounds(5));
    assert_eq!(
        e.attack_mode_tally(fighter, goblin, true).resolve(),
        RollMode::Advantage,
        "faerie fire beats the invisibility it is painted over"
    );

    // And from the other end: an invisible attacker who is themselves
    // outlined stops swinging out of concealment. Starry Wisp's
    // condition carries the same clause without the outline's
    // advantage, which is what makes it the narrower of the two.
    let mut e = ei_with_terrain(20, 20, &[]);
    let sneak = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let mark = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    e.actors
        .get_mut(&sneak)
        .unwrap()
        .add_condition(Condition::Invisible, ConditionTimer::Rounds(5));
    assert_eq!(
        e.attack_mode_tally(sneak, mark, true).resolve(),
        RollMode::Advantage,
        "an unseen attacker swings at advantage"
    );
    e.actors
        .get_mut(&sneak)
        .unwrap()
        .add_condition(Condition::WispLit, ConditionTimer::Rounds(1));
    assert_eq!(
        e.attack_mode_tally(sneak, mark, true).resolve(),
        RollMode::Normal,
        "a wisp-lit attacker is not unseen, and the wisp grants nothing \
         else — that is the whole difference from Faerie Fire"
    );
}

/// 5e: *"when you attack a target that you can't see, you have
/// disadvantage on the attack roll"* — and a creature that has beaten
/// the room's passive Perception with a Stealth check is one you can't
/// see.
///
/// The other half of `Condition::Hidden`, which the engine carried in
/// its docstring and nowhere else: hiding bought the rogue one good
/// swing (the advantage half, consumed by taking it) and no protection
/// at all in between, which is not what anybody hides for.
#[test]
fn a_hidden_creature_is_hard_to_hit_until_something_hears_it() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut e = ei_with_terrain(30, 30, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let rogue = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    assert_eq!(
        e.attack_mode_tally(fighter, rogue, true).resolve(),
        RollMode::Normal
    );
    e.actors
        .get_mut(&rogue)
        .unwrap()
        .add_condition(Condition::Hidden, ConditionTimer::Permanent);
    assert_eq!(
        e.attack_mode_tally(fighter, rogue, true).resolve(),
        RollMode::Disadvantage,
        "you cannot see where it went"
    );

    // A non-visual sense in range finds it anyway — RAW's Blindsense is
    // "aware of the location of any hidden or invisible creature", and
    // every ear and tremor sense on the piercing tier reads the same.
    // The rogue is two tiles away, inside the 10 ft envelope.
    e.actors
        .get_mut(&fighter)
        .unwrap()
        .set_blindsense(true);
    assert_eq!(
        e.attack_mode_tally(fighter, rogue, true).resolve(),
        RollMode::Normal,
        "a listener does not need to see it"
    );
}

/// Starry Wisp: the SRD 5.2 bard / druid cantrip. On a hit it leaves
/// two things behind — a `WispLit` mark and a carried light source —
/// and between them an invisible target stops being hard to hit and
/// starts showing up on the lighting layer.
#[test]
fn starry_wisp_sticks_a_mote_of_light_to_what_it_hits() {
    use crate::actions::spells::STARRY_WISP;
    use crate::actors::creatures::bards::BARD_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut lit = false;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain_seeded(30, 30, &[], seed);
        let bard = e
            .instantiate_creature(&BARD_TEMPLATE, Coordinate::new(2, 5), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 5), 1, 0)
            .unwrap();
        let costs = STARRY_WISP.cost(&e, bard, Some(&vec![goblin]), None, None);
        assert!(
            !costs.iter().any(|c| matches!(c, Resource::SpellSlot(_))),
            "Starry Wisp is a cantrip and must not cost a slot"
        );
        let before = e.actors[&goblin].hitpoints();
        for ef in STARRY_WISP.side_effects(&mut e, bard, Some(&vec![goblin]), None, None) {
            ef.apply(&mut e);
        }
        let hit = e.actors[&goblin].hitpoints() < before;
        // Both riders ride the hit, and neither shows up without one.
        assert_eq!(
            e.actors[&goblin].has_condition(Condition::WispLit),
            hit,
            "seed {}: the mark and the hit are the same event",
            seed
        );
        assert_eq!(
            e.actor_carries_light(goblin),
            hit,
            "seed {}: so is the light",
            seed
        );
        if hit {
            lit = true;
        }
    }
    assert!(lit, "Starry Wisp should connect at least once across seeds");
}

/// Chaos Bolt: lv1 sorcerer attack. Verifies the lv1 slot cost and
/// that the bolt eventually deals damage to the target across seeds
/// (the random damage type doesn't change the hit outcome). Drives
/// the chain rider opportunity by sitting a second enemy within 30 ft
/// of the primary — across enough seeds, a matching double-d8 should
/// fire and damage the secondary target at least once.
#[test]
fn chaos_bolt_damages_primary_and_eventually_chains() {
    use crate::actions::spells::CHAOS_BOLT;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut damaged_primary = false;
    let mut damaged_chain = false;
    for seed in 0..80u64 {
        let mut e = ei_with_terrain(30, 30, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let sor = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 5), 0, 0)
            .unwrap();
        let primary = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 5), 1, 0)
            .unwrap();
        // Chain candidate within 12 tiles (30ft) of the primary.
        let chain = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(13, 5), 1, 0)
            .unwrap();
        let costs =
            CHAOS_BOLT.cost(&e, sor, Some(&vec![primary]), None, None);
        assert!(costs.iter().any(|c| matches!(c, Resource::SpellSlot(1))));
        let hp_primary_before = e.actors[&primary].hitpoints();
        let hp_chain_before = e.actors[&chain].hitpoints();
        for ef in
            CHAOS_BOLT.side_effects(&mut e, sor, Some(&vec![primary]), None, None)
        {
            ef.apply(&mut e);
        }
        if e.actors[&primary].hitpoints() < hp_primary_before {
            damaged_primary = true;
        }
        if e.actors[&chain].hitpoints() < hp_chain_before {
            damaged_chain = true;
        }
        if damaged_primary && damaged_chain {
            break;
        }
    }
    assert!(
        damaged_primary,
        "Chaos Bolt should land damage on the primary target across seeds"
    );
    assert!(
        damaged_chain,
        "Chaos Bolt should eventually chain to a nearby enemy across seeds"
    );
}

/// The exploding-dice lane's budget is a hard cap, not a target: a
/// pool of `n` dice with a cap of `k` can never pay out more than
/// `(n + k) * faces`, however many maxima the chain turns up.
#[test]
fn an_exploding_pool_never_outspends_its_budget() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    const POOL: u32 = 4;
    const FACES: u32 = 8;
    const CAP: u32 = 2;
    for seed in 0..200u64 {
        let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let rolled = e.roll_exploding_spell_damage(g, POOL, FACES, CAP);
        assert!(
            (POOL..=(POOL + CAP) * FACES).contains(&rolled),
            "seed {}: {} is outside the {}..={} an exploding {}d{} pool can produce",
            seed,
            rolled,
            POOL,
            (POOL + CAP) * FACES,
            POOL,
            FACES,
        );
    }
}

/// A die showing its maximum face buys another die, and the new die can
/// buy one in its turn. Rolled on a d2 so the chain is common enough to
/// observe in a bounded sweep — the rule is about the maximum face, not
/// about the number eight.
///
/// The zero-budget half is the load-bearing assertion for the forty-odd
/// spells that don't explode: with no budget the pool cannot exceed its
/// own maximum, which is exactly the behaviour `spell_attack_outcome`
/// hands to everything that isn't Sorcerous Burst.
#[test]
fn a_maximum_face_buys_another_die_until_the_budget_runs_out() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut exploded = false;
    for seed in 0..60u64 {
        let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // One d2 with three dice of budget: anything above 2 can only
        // have come from the chain.
        if e.roll_exploding_spell_damage(g, 1, 2, 3) > 2 {
            exploded = true;
        }
        // The same pool with no budget is a plain 1d2 forever.
        let capped = e.roll_exploding_spell_damage(g, 1, 2, 0);
        assert!(
            (1..=2).contains(&capped),
            "seed {}: a zero-budget pool rolled {}, which is not a 1d2",
            seed,
            capped
        );
    }
    assert!(
        exploded,
        "a d2 pool with three dice of budget should chain at least once in sixty seeds"
    );
}

/// Sorcerous Burst: the SRD 5.2 sorcerer cantrip. Costs no slot, lands
/// damage as a ranged spell attack, and its d8 pool can pay out more
/// than the un-exploded maximum the cantrip ladder allows.
#[test]
fn sorcerous_burst_is_a_slotless_attack_whose_dice_can_explode() {
    use crate::actions::spells::SORCEROUS_BURST;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut damaged = false;
    let mut chained = false;
    for seed in 0..120u64 {
        let mut e = ei_with_terrain_seeded(30, 30, &[], seed);
        let sor = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 5), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 5), 1, 0)
            .unwrap();
        // A cantrip: one Action and nothing else.
        let costs = SORCEROUS_BURST.cost(&e, sor, Some(&vec![goblin]), None, None);
        assert!(
            !costs.iter().any(|c| matches!(c, Resource::SpellSlot(_))),
            "Sorcerous Burst is a cantrip and must not cost a slot"
        );
        let before = e.actors[&goblin].hitpoints();
        let log_before = e.messages().len();
        for ef in SORCEROUS_BURST.side_effects(&mut e, sor, Some(&vec![goblin]), None, None) {
            ef.apply(&mut e);
        }
        if e.actors[&goblin].hitpoints() < before {
            damaged = true;
        }
        // The chain announces itself, which is a steadier signal than
        // the damage total: a d8 that comes up 8 buys a die whether the
        // swing crit or not, and the two are indistinguishable in the
        // final number.
        if e.messages()[log_before..]
            .iter()
            .any(|m| m.contains("exploding dice"))
        {
            chained = true;
        }
    }
    assert!(damaged, "Sorcerous Burst should land damage across seeds");
    assert!(
        chained,
        "Sorcerous Burst's d8s should explode at least once across a hundred and twenty seeds"
    );
}

/// Arms of Hadar: lv1 warlock self-burst. Verifies the lv1 slot cost,
/// damage to an adjacent enemy on a failed STR save, and the
/// NoReaction rider lands on at least one failed-save victim across
/// seeds.
#[test]
fn arms_of_hadar_damages_and_blocks_reactions() {
    use crate::actions::spells::ARMS_OF_HADAR;
    use crate::actors::creatures::warlocks::WARLOCK_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut damaged = false;
    let mut no_reaction_landed = false;
    for seed in 0..30u64 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wl = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        // Adjacent zombie — low STR biases toward failed save.
        let z = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let costs = ARMS_OF_HADAR.cost(&e, wl, None, None, None);
        assert!(costs.iter().any(|c| matches!(c, Resource::SpellSlot(1))));
        let hp_before = e.actors[&z].hitpoints();
        for ef in ARMS_OF_HADAR.side_effects(&mut e, wl, None, None, None) {
            ef.apply(&mut e);
        }
        if e.actors[&z].hitpoints() < hp_before {
            damaged = true;
        }
        if e.actors
            .get(&z)
            .is_some_and(|a| a.has_condition(Condition::NoReaction))
        {
            no_reaction_landed = true;
        }
        if damaged && no_reaction_landed {
            break;
        }
    }
    assert!(damaged, "Arms of Hadar should damage in-burst enemies");
    assert!(
        no_reaction_landed,
        "Arms of Hadar's NoReaction rider should land on failed STR saves"
    );
}

