/// Sapping Sting: Tasha's necromancy cantrip. On a failed CON save,
/// the target takes 1d4 necrotic and is knocked Prone. Verifies the
/// cantrip costs no slot, declares necrotic damage typing, and on
/// at least one seed (across a sweep) the goblin is both damaged
/// and prone after the cast.
#[test]
fn sapping_sting_damages_and_prones_on_failed_save() {
    use crate::actions::spells::SAPPING_STING;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::Resource;
    use crate::engine::types::DamageType;

    // Cost / typing shape.
    {
        let mut e = ei_with_terrain(15, 15, &[]);
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 5), 1, 0)
            .unwrap();
        let costs = SAPPING_STING.cost(&e, wiz, Some(&vec![g]), None, None);
        assert!(costs.iter().any(|c| matches!(c, Resource::Action)));
        assert!(
            !costs.iter().any(|c| matches!(c, Resource::SpellSlot(_))),
            "sapping sting is a cantrip — no slot consumed"
        );
        assert!(SAPPING_STING.damage_types().contains(&DamageType::Necrotic));
    }

    let mut proned_on_hit = false;
    for seed in 0..40u64 {
        let mut e = ei_with_terrain(20, 20, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 5), 1, 0)
            .unwrap();
        let hp_before = e.actors[&g].hitpoints();
        for ef in SAPPING_STING.side_effects(&mut e, wiz, Some(&vec![g]), None, None) {
            ef.apply(&mut e);
        }
        let took_damage = e.actors[&g].hitpoints() < hp_before;
        let is_prone = e.actors[&g].has_condition(Condition::Prone);
        // Both should always travel together — on a save fail the
        // spell applies damage AND prone in a single batch.
        assert_eq!(
            took_damage, is_prone,
            "sapping sting damage and prone should land together (or not at all)"
        );
        if took_damage && is_prone {
            proned_on_hit = true;
            break;
        }
    }
    assert!(
        proned_on_hit,
        "sapping sting should knock the goblin prone on at least one failed save across seeds"
    );
}

/// Verifies `self_concentration_buff_effects` produces the expected
/// 2-effect chain (ApplyCondition + StartConcentration with the
/// condition tagged for cleanup) by casting `Blur` (the first spell
/// converted to the helper) and asserting both flags land plus the
/// concentration mark properly cleans up on drop.
#[test]
fn self_concentration_buff_helper_installs_and_drops_cleanly() {
    use crate::actions::spells::BLUR;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;

    let mut e = ei_with_terrain(15, 15, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    for ef in BLUR.side_effects(&mut e, wiz, None, None, None) {
        ef.apply(&mut e);
    }
    assert!(e.actors[&wiz].has_condition(Condition::Blurred));
    assert!(e.actors[&wiz].is_concentrating());
    e.drop_concentration(wiz);
    assert!(
        !e.actors[&wiz].has_condition(Condition::Blurred),
        "Blurred should drop cleanly with the concentration mark"
    );
    assert!(!e.actors[&wiz].is_concentrating());
}

/// Erupting Earth: lv3 transmutation, DEX-save-for-half bludgeoning
/// burst (3d12 over a 4-tile radius). Verifies the lv3 slot cost,
/// that a low-DEX enemy in the area takes damage, and that an ally
/// outside the burst is untouched (enemy-burst routing).
#[test]
fn erupting_earth_damages_enemies_in_burst() {
    use crate::actions::spells::ERUPTING_EARTH;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::Resource;

    let mut damaged = false;
    for seed in 0..30u64 {
        let mut e = ei_with_terrain(25, 25, &[]);
        for _ in 0..seed {
            let _ = e.roll(&crate::engine::dice::Dice::new(1, 6));
        }
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Low-DEX zombie in the 4-tile burst footprint.
        let z = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(10, 2), 1, 0)
            .unwrap();
        let pt = Coordinate::new(10, 2);
        let costs = ERUPTING_EARTH.cost(&e, wiz, None, Some(&vec![pt]), None);
        assert!(costs.iter().any(|c| matches!(c, Resource::SpellSlot(3))));
        let hp_before = e.actors[&z].hitpoints();
        for ef in ERUPTING_EARTH.side_effects(&mut e, wiz, None, Some(&vec![pt]), None) {
            ef.apply(&mut e);
        }
        if e.actors[&z].hitpoints() < hp_before {
            damaged = true;
            break;
        }
    }
    assert!(
        damaged,
        "Erupting Earth should land 3d12 bludgeoning on a failed DEX save across seeds"
    );
}

