#[test]
fn uncanny_dodge_consumes_reaction_on_hit() {
    let mut e = ei_with_terrain(20, 20, &[]);
    let f_id = e
        .instantiate_creature(
            &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
            Coordinate::new(3, 3),
            0,
            1,
        )
        .unwrap();
    let r_id = e
        .instantiate_creature(
            &crate::actors::creatures::rogues::ROGUE_TEMPLATE,
            Coordinate::new(5, 3),
            1,
            2,
        )
        .unwrap();
    assert!(e.actors[&r_id].has_uncanny_dodge());
    assert!(e.actors[&r_id].has_reaction());
    use crate::engine::attack::{AttackParams, resolve_attack};
    let mut hit_seen = false;
    for _ in 0..100 {
        // Reset reaction to exactly 1 before each attempt
        let rogue = e.actors.get_mut(&r_id).unwrap();
        let max_hp = rogue.max_hitpoints();
        rogue.heal(max_hp);
        // Rebuild reaction state to exactly 1 by resetting the round
        let _ = rogue.reset_for_new_round();
        assert!(e.actors[&r_id].has_reaction());
        let effects = resolve_attack(
            &mut e,
            AttackParams {
                caster_id: f_id,
                target_id: r_id,
                action_name: "longsword",
                attack_bonus: 5,
                damage_dice: Dice::new(1, 8),
                damage_bonus: 3,
                damage_type: DamageType::Slashing,
                is_melee: true,
            long_range: None,
            min_range: None,
            is_spell: false,
            },
        );
        if !effects.is_empty() {
            hit_seen = true;
            assert!(
                !e.actors[&r_id].has_reaction(),
                "Uncanny Dodge should consume the rogue's reaction on hit"
            );
            break;
        }
    }
    assert!(hit_seen, "Expected at least one hit in 100 attempts");
}

/// Deflect Missiles fires on a ranged weapon hit, reduces damage by
/// 1d10 + DEX + level, and consumes the monk's reaction. Melee hits
/// against the monk do NOT consume the reaction (the feature is
/// ranged-only).
#[test]
fn deflect_missiles_reduces_ranged_damage_and_consumes_reaction() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::monks::MONK_TEMPLATE;
    use crate::engine::attack::{AttackParams, resolve_attack};
    let mut e = ei_with_terrain(20, 20, &[]);
    let archer = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 1, 0)
        .unwrap();
    let monk = e
        .instantiate_creature(&MONK_TEMPLATE, Coordinate::new(10, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&monk].has_deflect_missiles());
    // Search for a hit (force damage > 0) and check that the
    // reaction is consumed and the log line lands.
    let mut deflected = false;
    for _ in 0..120 {
        e.actors.get_mut(&monk).unwrap().reset_for_new_round();
        assert!(e.actors[&monk].has_reaction());
        let starting_hp = e.actors[&monk].hitpoints();
        let effects = resolve_attack(
            &mut e,
            AttackParams {
                caster_id: archer,
                target_id: monk,
                action_name: "shortbow",
                attack_bonus: 10,
                damage_dice: Dice::new(1, 6),
                damage_bonus: 2,
                damage_type: DamageType::Piercing,
                is_melee: false,
                long_range: None,
                min_range: None,
                is_spell: false,
            },
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        // If the swing connected (damage was rolled), the reaction
        // should be consumed by Deflect Missiles.
        let after_hp = e.actors[&monk].hitpoints();
        if after_hp < starting_hp || !e.actors[&monk].has_reaction() {
            assert!(
                !e.actors[&monk].has_reaction(),
                "Deflect Missiles should consume monk's reaction on ranged hit"
            );
            deflected = true;
            break;
        }
    }
    assert!(deflected, "expected at least one ranged hit in 120 attempts");
    // Verify the melee gate: a melee swing should NOT fire the
    // deflect, leaving the reaction intact.
    e.actors.get_mut(&monk).unwrap().reset_for_new_round();
    assert!(e.actors[&monk].has_reaction());
    let mut melee_hit_seen = false;
    for _ in 0..120 {
        e.actors.get_mut(&monk).unwrap().reset_for_new_round();
        assert!(e.actors[&monk].has_reaction());
        let starting_hp = e.actors[&monk].hitpoints();
        let effects = resolve_attack(
            &mut e,
            AttackParams {
                caster_id: archer,
                target_id: monk,
                action_name: "club",
                attack_bonus: 10,
                damage_dice: Dice::new(1, 4),
                damage_bonus: 2,
                damage_type: DamageType::Bludgeoning,
                is_melee: true,
                long_range: None,
                min_range: None,
                is_spell: false,
            },
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        let after_hp = e.actors[&monk].hitpoints();
        if after_hp < starting_hp {
            melee_hit_seen = true;
            assert!(
                e.actors[&monk].has_reaction(),
                "Deflect Missiles must NOT fire on a melee hit"
            );
            break;
        }
    }
    assert!(
        melee_hit_seen,
        "expected at least one melee hit in 120 attempts"
    );
}

/// 5e Uncanny Dodge (Rogue 5) sight gate — post-refactor: the RAW
/// "attacker you can see" clause routes through
/// `viewer_can_see`, so an Invisible attacker (illusion-concealed
/// cohort) doesn't trigger the rogue's reaction charge even
/// though the target isn't Blinded. Pre-refactor gated only on
/// `!Blinded`, letting the reaction burn against an Invisible
/// fighter every swing regardless of RAW sight.
#[test]
fn uncanny_dodge_does_not_fire_against_invisible_attacker() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
    use crate::conditions::{Condition, ConditionTimer};
    use crate::engine::attack::{AttackParams, resolve_attack};
    let mut e = ei_with_terrain(20, 20, &[]);
    let attacker = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 3), 1, 0)
        .unwrap();
    let rogue = e
        .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(5, 3), 0, 0)
        .unwrap();
    // Cloak the attacker in Invisible — an illusion-concealed
    // cohort member — so `viewer_can_see(rogue, attacker)` returns
    // false. The rogue holds no piercing sense (Blindsense is a
    // 10-ft flag; the attacker sits 2 tiles away which is within
    // range, so we ship the setup with the ranged 5-tile gap
    // below to avoid the piercer).
    e.actors
        .get_mut(&attacker)
        .unwrap()
        .add_condition(Condition::Invisible, ConditionTimer::Rounds(5));
    // Move the attacker outside the rogue's Blindsense's 10-ft
    // envelope so the sight gate genuinely rejects.
    e.actors
        .get_mut(&attacker)
        .unwrap()
        .set_location(Coordinate::new(12, 12));
    e.actors
        .get_mut(&rogue)
        .unwrap()
        .set_location(Coordinate::new(3, 3));
    assert!(!e.viewer_can_see(rogue, attacker));
    // Force many rolls — every hit should leave the reaction
    // intact since the sight gate rejects Uncanny Dodge.
    let mut hit_seen = false;
    for _ in 0..200 {
        e.actors.get_mut(&rogue).unwrap().reset_for_new_round();
        let max = e.actors[&rogue].max_hitpoints();
        e.actors.get_mut(&rogue).unwrap().heal(max);
        assert!(e.actors[&rogue].has_reaction());
        let starting_hp = e.actors[&rogue].hitpoints();
        let effects = resolve_attack(
            &mut e,
            AttackParams {
                caster_id: attacker,
                target_id: rogue,
                action_name: "longsword",
                attack_bonus: 8,
                damage_dice: Dice::new(1, 8),
                damage_bonus: 3,
                damage_type: DamageType::Slashing,
                is_melee: false,
                long_range: None,
                min_range: None,
                is_spell: false,
            },
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        if e.actors[&rogue].hitpoints() < starting_hp {
            hit_seen = true;
            assert!(
                e.actors[&rogue].has_reaction(),
                "Uncanny Dodge must NOT fire when the rogue can't see the attacker"
            );
            break;
        }
    }
    assert!(hit_seen, "expected at least one hit in 200 attempts");
}

/// 5e Monk Deflect Missiles sight gate — post-refactor: same
/// `viewer_can_see` routing as Uncanny Dodge. A Blinded monk
/// shouldn't burn their deflect charge on incoming arrows RAW,
/// and an Invisible archer shouldn't provoke the deflect either.
