#[test]
fn thunder_step_deals_damage_and_teleports() {
    let mut e = ei_with_terrain(20, 20, &[]);
    let wiz_id = e
        .instantiate_creature(
            &crate::actors::creatures::wizards::WIZARD_TEMPLATE,
            Coordinate::new(5, 5),
            0,
            1,
        )
        .unwrap();
    let goblin_id = e
        .instantiate_creature(
            &crate::actors::creatures::goblins::GOBLIN_TEMPLATE,
            Coordinate::new(6, 5),
            1,
            2,
        )
        .unwrap();
    let goblin_hp_before = e.actors[&goblin_id].hitpoints();
    let action = e.actors[&wiz_id].find_action("thunder step").unwrap();
    let effects = action.side_effects(
        &mut e,
        wiz_id,
        None,
        Some(&vec![Coordinate::new(15, 15)]),
        None,
    );
    for ef in effects {
        ef.apply(&mut e);
    }
    // Wizard should have teleported to dest
    assert_eq!(
        e.actors[&wiz_id].location(),
        Coordinate::new(15, 15),
        "Wizard should teleport to destination"
    );
    // Goblin should have taken some damage (or passed save for half)
    let goblin_hp_after = e.actors[&goblin_id].hitpoints();
    assert!(
        goblin_hp_after <= goblin_hp_before,
        "Goblin should take thunder damage from Thunder Step"
    );
}

#[test]
fn prone_crawling_costs_double_movement() {
    let mut e = ei_with_terrain(20, 20, &[]);
    let f_id = e
        .instantiate_creature(
            &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
            Coordinate::new(3, 3),
            0,
            1,
        )
        .unwrap();
    let actor = e.actors.get_mut(&f_id).unwrap();
    actor.reset_for_new_round();
    let normal_cost = e.path_cost_to(f_id, Coordinate::new(5, 3)).unwrap();

    let actor = e.actors.get_mut(&f_id).unwrap();
    actor.add_condition(
        crate::conditions::Condition::Prone,
        crate::conditions::ConditionTimer::Permanent,
    );
    // 5e: crawling costs double movement per tile. The actor can
    // still move but each step costs 2x.
    let prone_cost = e.path_cost_to(f_id, Coordinate::new(5, 3)).unwrap();
    let ratio = prone_cost / normal_cost;
    assert!(
        (ratio - 2.0).abs() < 0.01,
        "prone crawling should cost exactly 2x (got {:.2}x)",
        ratio
    );
}

#[test]
fn evasion_reduces_dex_save_damage() {
    use crate::actions::action_template::resolve_burst_save_damage;
    let mut e = ei_with_terrain(20, 20, &[]);
    let wiz_id = e
        .instantiate_creature(
            &crate::actors::creatures::wizards::WIZARD_TEMPLATE,
            Coordinate::new(3, 3),
            0,
            1,
        )
        .unwrap();
    let rogue_id = e
        .instantiate_creature(
            &crate::actors::creatures::rogues::ROGUE_TEMPLATE,
            Coordinate::new(5, 5),
            1,
            2,
        )
        .unwrap();
    assert!(e.actors[&rogue_id].has_evasion());
    let effects = resolve_burst_save_damage(
        &mut e,
        wiz_id,
        Coordinate::new(5, 5),
        2,
        crate::engine::types::AbilityScoreType::Dexterity,
        1,
        20,
        DamageType::Fire,
    );
    let has_damage = !effects.is_empty();
    if has_damage {
        for ef in &effects {
            ef.apply(&mut e);
        }
        let hp_after = e.actors[&rogue_id].hitpoints();
        let max_hp = e.actors[&rogue_id].max_hitpoints();
        let dmg_taken = max_hp - hp_after;
        assert!(
            dmg_taken <= 10,
            "Evasion should halve damage on fail (got {} dmg from 20 raw)",
            dmg_taken
        );
    }
}

