#[test]
fn new_creature_chimera_instantiates() {
    let mut roller = FastRandRoller::with_seed(42);
    let chimera = ActorInstance::from_creature_template(
        &crate::actors::creatures::chimeras::CHIMERA_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut roller,
        1,
    );
    assert!(chimera.is_ok(), "Chimera should instantiate");
    let chimera = chimera.unwrap();
    assert_eq!(chimera.size(), Size::Large);
    assert!(chimera.cr() >= 6.0);
}

#[test]
fn new_creature_shadow_instantiates_with_immunities() {
    let mut roller = FastRandRoller::with_seed(42);
    let shadow = ActorInstance::from_creature_template(
        &crate::actors::creatures::shadows::SHADOW_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut roller,
        1,
    );
    assert!(shadow.is_ok(), "Shadow should instantiate");
    let shadow = shadow.unwrap();
    assert!(shadow.is_immune_to(DamageType::Necrotic));
    assert!(shadow.is_immune_to(DamageType::Poison));
    assert!(shadow.is_vulnerable_to(DamageType::Radiant));
    assert!(shadow.is_resistant_to(DamageType::Cold));
}

#[test]
fn new_creature_nightmare_instantiates() {
    let mut roller = FastRandRoller::with_seed(42);
    let nightmare = ActorInstance::from_creature_template(
        &crate::actors::creatures::nightmares::NIGHTMARE_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut roller,
        1,
    );
    assert!(nightmare.is_ok(), "Nightmare should instantiate");
    let nightmare = nightmare.unwrap();
    assert!(nightmare.is_immune_to(DamageType::Fire));
    assert!(nightmare.is_resistant_to(DamageType::Cold));
}

/// A three-tile walled corridor whose middle tile is difficult
/// terrain, with `template` standing at the mouth of it. The only
/// route to the far end runs through the rough tile, so the returned
/// path cost is the terrain surcharge and nothing else — there is no
/// cheaper way around for the pathfinder to find.
///
/// Every difficult-terrain test below wants exactly this board and
/// differs only in who is walking it and what they are holding, so
/// the corridor is built once here.
fn rough_corridor_walker(
    template: &'static crate::actors::actor_template::CreatureTemplate,
) -> (EncounterInstance, usize) {
    use crate::engine::terrain::{TerrainInfo, TerrainType};
    // A Medium creature's footprint is 2x2 tiles on this 2.5-ft
    // grid, so the corridor has to be two tiles tall: rows 3 and 4
    // are the lane, rows 2 and 5 are its walls. That leaves row 3 as
    // the only row a footprint can be anchored on, so the walker
    // cannot slip around the rough tile diagonally.
    let walls: Vec<(isize, isize)> = (1..=9)
        .flat_map(|x: isize| [(x, 2isize), (x, 5isize)])
        .collect();
    let mut e = ei_with_terrain(20, 20, &walls);
    let id = e
        .instantiate_creature(template, Coordinate::new(3, 3), 0, 1)
        .unwrap();
    e.actors.get_mut(&id).unwrap().reset_for_new_round();
    e.terrain[4 + 3 * 20] = TerrainInfo {
        terrain_type: TerrainType::DifficultTerrain,
    };
    (e, id)
}

/// The rough tile at (4,3) is the only way from (3,3) to (5,3), so
/// the two-step walk costs one normal step plus one doubled step.
/// On a 2.5-ft-per-tile grid that is 2.5 + 5.0 = 7.5 ft, against
/// 5.0 ft for the same two steps over clean floor.
#[test]
fn difficult_terrain_costs_more_movement() {
    use crate::engine::terrain::{TerrainInfo, TerrainType};
    let (mut e, f_id) =
        rough_corridor_walker(&crate::actors::creatures::fighters::FIGHTER_TEMPLATE);
    let rough_cost = e
        .path_cost_to(f_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    // Same board, same walk, with the rough tile paved back to floor.
    e.terrain[4 + 3 * 20] = TerrainInfo {
        terrain_type: TerrainType::Floor,
    };
    let clean_cost = e
        .path_cost_to(f_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    assert!(
        rough_cost > clean_cost,
        "difficult terrain should cost more: rough {rough_cost} vs clean {clean_cost}"
    );
    assert!(
        (rough_cost - (clean_cost + 2.5)).abs() < 0.01,
        "the surcharge is one extra tile-step (2.5 ft): rough {rough_cost}, clean {clean_cost}"
    );
}

/// Freedom of Movement's `Footloose` docstring has always promised
/// "the target ignores difficult terrain". Until the
/// `DIFFICULT_TERRAIN_IMMUNITIES` cohort landed, the pathfinder
/// charged the surcharge anyway.
#[test]
fn freedom_of_movement_waives_the_difficult_terrain_surcharge() {
    let (mut e, f_id) =
        rough_corridor_walker(&crate::actors::creatures::fighters::FIGHTER_TEMPLATE);
    let taxed = e
        .path_cost_to(f_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    e.actors
        .get_mut(&f_id)
        .unwrap()
        .add_condition(Condition::Footloose, ConditionTimer::Rounds(10));
    let free = e
        .path_cost_to(f_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    assert!(
        free < taxed,
        "Footloose should waive the surcharge: {free} vs {taxed}"
    );
    assert!(
        (free - 5.0).abs() < 0.01,
        "two clean tile-steps is 5.0 ft, got {free}"
    );
}

/// A creature sixty feet in the air isn't wading through the rubble
/// under it. The flight row deliberately reuses the same triple-OR
/// predicate as the flying-speed bonus, so all three flight
/// conditions are checked here.
#[test]
fn magical_flight_waives_the_difficult_terrain_surcharge() {
    for flight in [
        Condition::Flying,
        Condition::InvestedInWind,
        Condition::OtherworldlyGuised,
    ] {
        let (mut e, f_id) =
            rough_corridor_walker(&crate::actors::creatures::fighters::FIGHTER_TEMPLATE);
        let taxed = e
            .path_cost_to(f_id, Coordinate::new(5, 3))
            .expect("corridor is walkable");
        e.actors
            .get_mut(&f_id)
            .unwrap()
            .add_condition(flight, ConditionTimer::Rounds(10));
        let airborne = e
            .path_cost_to(f_id, Coordinate::new(5, 3))
            .expect("corridor is walkable");
        assert!(
            airborne < taxed,
            "{flight:?} should waive the surcharge: {airborne} vs {taxed}"
        );
    }
}

/// Land's Stride is the build-choice row on the cohort: a baseline
/// Fighter pays the surcharge on the same corridor a baseline Ranger
/// crosses for free.
#[test]
fn lands_stride_waives_the_difficult_terrain_surcharge() {
    use crate::actions::class_features::LANDS_STRIDE_TAG;
    let (e, ranger_id) =
        rough_corridor_walker(&crate::actors::creatures::rangers::RANGER_TEMPLATE);
    assert!(
        e.actors[&ranger_id].has_passive_feature(LANDS_STRIDE_TAG),
        "the baseline Ranger ships Land's Stride"
    );
    let ranger_cost = e
        .path_cost_to(ranger_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    let (e, fighter_id) =
        rough_corridor_walker(&crate::actors::creatures::fighters::FIGHTER_TEMPLATE);
    assert!(
        !e.actors[&fighter_id].has_passive_feature(LANDS_STRIDE_TAG),
        "the Fighter does not"
    );
    let fighter_cost = e
        .path_cost_to(fighter_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    assert!(
        ranger_cost < fighter_cost,
        "Land's Stride should waive the surcharge: ranger {ranger_cost} vs fighter {fighter_cost}"
    );
}

/// Land's Stride reaches every ranger subclass and the Land Druid,
/// and stops there — it is not a blanket grant. Guards the
/// clone-the-baseline-features shape the Hunter Ranger now uses:
/// re-listing baseline tags inline is what let a subclass silently
/// drop one.
#[test]
fn lands_stride_ships_on_the_ranger_line_and_the_land_druid() {
    use crate::actions::class_features::LANDS_STRIDE_TAG;
    use crate::actors::creatures::{druids, rangers};
    let carriers: &[&crate::actors::actor_template::CreatureTemplate] = &[
        &rangers::RANGER_TEMPLATE,
        &rangers::HUNTER_RANGER_TEMPLATE,
        &rangers::GLOOM_STALKER_RANGER_TEMPLATE,
        &rangers::FEY_WANDERER_RANGER_TEMPLATE,
        &rangers::HORIZON_WALKER_RANGER_TEMPLATE,
        &rangers::MONSTER_SLAYER_RANGER_TEMPLATE,
        &rangers::SWARMKEEPER_RANGER_TEMPLATE,
        &rangers::BEAST_MASTER_RANGER_TEMPLATE,
        &druids::LAND_DRUID_TEMPLATE,
    ];
    for t in carriers {
        assert!(
            t.features.contains(LANDS_STRIDE_TAG),
            "{} should ship Land's Stride",
            t.name
        );
    }
    let non_carriers: &[&crate::actors::actor_template::CreatureTemplate] = &[
        &druids::DRUID_TEMPLATE,
        &druids::MOON_DRUID_TEMPLATE,
        &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
    ];
    for t in non_carriers {
        assert!(
            !t.features.contains(LANDS_STRIDE_TAG),
            "{} should not ship Land's Stride",
            t.name
        );
    }
}

// ---------------------------------------------------------------------
// 5e Underwater Combat (PHB p.198)
// ---------------------------------------------------------------------

/// The longest arm in the bestiary is a melee attack, and every
/// consumer of the trait agrees with the die about that.
///
/// The kraken's tentacle reaches six tiles and `MELEE_BAND_REACH` stops
/// at four, so `Action::is_melee_attack`'s inference called it a ranged
/// attack — while `resolve_attack` was handed `is_melee: true` off the
/// same weapon and resolved every swing as the melee attack it is. The
/// swing was never wrong; every decision leading up to it was made on
/// the other answer.
///
/// Pinned against the *field* rather than against a number, because the
/// fix is that `SimpleWeapon` declares instead of inferring: a seventh
/// tile of reach on some future titan must not reintroduce this, and a
/// test that asserted `reach <= 6` would let it.
#[test]
fn the_krakens_tentacle_is_a_melee_attack_however_far_it_reaches() {
    use crate::actions::action_template::MELEE_BAND_REACH;
    use crate::actions::monster_attacks::KRAKEN_TENTACLE;

    let tentacle: &dyn crate::actions::action_template::Action = &KRAKEN_TENTACLE;
    assert!(
        tentacle.reach_tiles().is_some_and(|r| r > MELEE_BAND_REACH),
        "the tentacle is the case that outreaches the inference's band"
    );
    assert!(
        tentacle.is_melee_attack(),
        "and it is still a swing, not a shot"
    );
    assert!(
        tentacle.normal_range().is_none(),
        "a swing has no normal range for the underwater cut to read"
    );
}

/// Every ranged weapon in the engine declares a normal range.
///
/// Two separate rules read that number and neither can ask for it a
/// second way: 5e's long-range disadvantage ("attacks beyond normal
/// range have disadvantage"), and Underwater Combat's harder clause
/// ("automatically misses a target beyond the weapon's normal range").
/// A ranged weapon that left it unset would be a bow with no falloff
/// and a bow you can shoot the length of a lake with, and it would look
/// like a weapon that was simply good.
///
/// Swept over every template's action list rather than over the weapon
/// statics, because the failure is a template shipping an action, and
/// an unused static is nobody's bug. Melee weapons are excluded by
/// construction — reach *is* their range — and so is everything that
/// isn't a weapon attack, since a spell has no normal range and RAW
/// never gives it one.
#[test]
fn every_ranged_weapon_declares_the_normal_range_two_rules_read() {
    let mut checked = 0;
    let templates = EncounterInstance::template_pool().into_iter().chain(
        crate::actors::creatures::pc_template_families()
            .into_iter()
            .flat_map(|(_, ts)| ts),
    );
    for t in templates {
        for action in &t.actions {
            if !action.is_weapon_attack() || action.is_melee_attack() {
                continue;
            }
            checked += 1;
            assert!(
                action.normal_range().is_some(),
                "{}'s {} is a ranged weapon with no normal range",
                t.name,
                action.name()
            );
        }
    }
    assert!(checked > 0, "the sweep found ranged weapons to check");
}

/// The `rough_corridor_walker` board with the middle tile flooded
/// instead of strewn with rubble. The two helpers are deliberately
/// twins: every claim below about what the water charges is a claim
/// about how it differs from the rubble, and comparing two boards that
/// differ in one tile is the only way to say that cleanly.
fn flooded_corridor_walker(
    template: &'static crate::actors::actor_template::CreatureTemplate,
) -> (EncounterInstance, usize) {
    use crate::engine::terrain::{TerrainInfo, TerrainType};
    let (mut e, id) = rough_corridor_walker(template);
    e.terrain[4 + 3 * 20] = TerrainInfo {
        terrain_type: TerrainType::Water,
    };
    (e, id)
}

/// Swimming costs what wading through rubble costs — RAW prices both
/// at "1 extra foot per foot of movement".
#[test]
fn crossing_water_costs_a_non_swimmer_the_same_as_difficult_terrain() {
    use crate::engine::terrain::{TerrainInfo, TerrainType};
    let (mut e, f_id) =
        flooded_corridor_walker(&crate::actors::creatures::fighters::FIGHTER_TEMPLATE);
    let wet = e
        .path_cost_to(f_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    e.terrain[4 + 3 * 20] = TerrainInfo {
        terrain_type: TerrainType::DifficultTerrain,
    };
    let rough = e
        .path_cost_to(f_id, Coordinate::new(5, 3))
        .expect("corridor is walkable");

    assert!(
        (wet - rough).abs() < 0.01,
        "water and rubble cost the same: {wet} vs {rough}"
    );
    assert!((wet - 7.5).abs() < 0.01, "one clean step plus one doubled step, got {wet}");
}

/// …and the two surcharges are waived by different things, which is the
/// entire reason `WATER_SURCHARGE_IMMUNITIES` is a second cohort rather
/// than three more rows on the first.
///
/// The cross is the test. A ranger's Land's Stride covers "nonmagical
/// difficult terrain" and a lake is not that; a shark's swimming speed
/// is no help at all on a pile of rubble. Asserting each waiver against
/// only its own tile would pass just as happily if both cohorts had been
/// collapsed into one.
#[test]
fn the_two_surcharges_are_waived_by_different_things() {
    use crate::actions::class_features::{LANDS_STRIDE_TAG, SWIM_SPEED_TAG};
    let dest = Coordinate::new(5, 3);

    // Land's Stride: free over rubble, charged in water.
    //
    // The Land Druid rather than the Ranger, though both carry the
    // feature, and the reason is the rule this test is about: the
    // Ranger's Roving grants a swimming speed as well, so a ranger
    // crosses both tiles for free and could not tell the two waivers
    // apart. The druid carries Land's Stride and nothing wet.
    let land_druid = &crate::actors::creatures::druids::LAND_DRUID_TEMPLATE;
    let (e, druid) = rough_corridor_walker(land_druid);
    assert!(e.actors[&druid].has_passive_feature(LANDS_STRIDE_TAG));
    assert!(!e.actors[&druid].has_swim_speed(), "and no swimming speed");
    let stride_rough = e.path_cost_to(druid, dest).unwrap();
    let (e, druid) = flooded_corridor_walker(land_druid);
    let stride_wet = e.path_cost_to(druid, dest).unwrap();
    assert!(
        (stride_rough - 5.0).abs() < 0.01,
        "Land's Stride waives the rubble, got {stride_rough}"
    );
    assert!(
        (stride_wet - 7.5).abs() < 0.01,
        "Land's Stride does not waive the water, got {stride_wet}"
    );

    // A swimming speed: the exact mirror. The scout rogue is the one
    // player build with one, which is what makes this comparison
    // possible on the same chassis size as the ranger.
    let (e, scout) =
        rough_corridor_walker(&crate::actors::creatures::rogues::SCOUT_ROGUE_TEMPLATE);
    assert!(e.actors[&scout].has_swim_speed(), "the Scout swims");
    assert!(
        !e.actors[&scout].has_passive_feature(SWIM_SPEED_TAG),
        "…via Superior Mobility rather than via the monster tag"
    );
    let swim_rough = e.path_cost_to(scout, dest).unwrap();
    let (e, scout) =
        flooded_corridor_walker(&crate::actors::creatures::rogues::SCOUT_ROGUE_TEMPLATE);
    let swim_wet = e.path_cost_to(scout, dest).unwrap();
    assert!(
        (swim_rough - 7.5).abs() < 0.01,
        "a swimming speed does not waive the rubble, got {swim_rough}"
    );
    assert!(
        (swim_wet - 5.0).abs() < 0.01,
        "a swimming speed waives the water, got {swim_wet}"
    );
}

/// The two class features that grant a swimming speed reach every build
/// on their chassis, and nothing else on the roster gets one for free.
///
/// Both are a *clause* of a feature whose headline is a speed bump —
/// Roving's "+5 ft… you also have a Climb Speed and a Swim Speed", the
/// Scout's "+10 ft… and climbing and swimming speeds" — which is exactly
/// the kind of clause that ships as flavour and stays that way. They
/// were flavour here too until the board had water in it, and the
/// failure mode if one is dropped is a ranger quietly paying double to
/// cross a pond.
#[test]
fn roving_and_superior_mobility_are_the_two_player_swimming_speeds() {
    use crate::actors::creatures::{druids, fighters, rangers, rogues};
    let swimmers: &[&crate::actors::actor_template::CreatureTemplate] = &[
        &rangers::RANGER_TEMPLATE,
        &rangers::HUNTER_RANGER_TEMPLATE,
        &rangers::GLOOM_STALKER_RANGER_TEMPLATE,
        &rangers::BEAST_MASTER_RANGER_TEMPLATE,
        &rogues::SCOUT_ROGUE_TEMPLATE,
    ];
    let landlubbers: &[&crate::actors::actor_template::CreatureTemplate] = &[
        &fighters::FIGHTER_TEMPLATE,
        // The other carrier of Land's Stride, and the control that says
        // the two features are not the same feature.
        &druids::LAND_DRUID_TEMPLATE,
        // The Scout's siblings on the same chassis: the grant is the
        // subclass's, not the rogue's.
        &rogues::ROGUE_TEMPLATE,
        &rogues::ASSASSIN_ROGUE_TEMPLATE,
    ];
    for t in swimmers {
        let (e, id) = flooded_corridor_walker(t);
        assert!(e.actors[&id].has_swim_speed(), "{} swims", t.name);
        let cost = e.path_cost_to(id, Coordinate::new(5, 3)).unwrap();
        assert!(
            (cost - 5.0).abs() < 0.01,
            "{} crosses the pool for free, got {cost}",
            t.name
        );
    }
    for t in landlubbers {
        let (e, id) = flooded_corridor_walker(t);
        assert!(!e.actors[&id].has_swim_speed(), "{} does not swim", t.name);
        let cost = e.path_cost_to(id, Coordinate::new(5, 3)).unwrap();
        assert!(
            (cost - 7.5).abs() < 0.01,
            "{} pays the swimming surcharge, got {cost}",
            t.name
        );
    }
}

/// Freedom of Movement is the one row on both cohorts, because RAW puts
/// it on both.
#[test]
fn freedom_of_movement_waives_the_swimming_surcharge_too() {
    let (mut e, f_id) =
        flooded_corridor_walker(&crate::actors::creatures::fighters::FIGHTER_TEMPLATE);
    let taxed = e.path_cost_to(f_id, Coordinate::new(5, 3)).unwrap();
    e.actors
        .get_mut(&f_id)
        .unwrap()
        .add_condition(Condition::Footloose, ConditionTimer::Rounds(10));
    let free = e.path_cost_to(f_id, Coordinate::new(5, 3)).unwrap();
    assert!(free < taxed, "Footloose should waive the swim: {free} vs {taxed}");
    assert!((free - 5.0).abs() < 0.01, "two clean tile-steps is 5.0 ft, got {free}");
}

/// A pool with one creature standing in it and one on the bank, both
/// Medium, adjacent, ids returned in that order.
///
/// "Fully immersed" is a footprint-wide claim, and a Medium creature is
/// 2x2 tiles on this grid, so the pool has to be at least that — a
/// single flooded tile would leave the swimmer three-quarters dry and
/// every test below would silently assert nothing.
fn swimmer_and_bystander() -> (EncounterInstance, usize, usize) {
    use crate::engine::terrain::TerrainType;
    let mut e = ei_with_terrain(20, 20, &[]);
    for x in 2..=5isize {
        for y in 2..=5isize {
            e.set_terrain_at(Coordinate::new(x, y), TerrainType::Water);
        }
    }
    let swimmer = e
        .instantiate_creature(
            &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
            Coordinate::new(3, 3),
            0,
            1,
        )
        .unwrap();
    let bystander = e
        .instantiate_creature(
            &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
            Coordinate::new(8, 3),
            1,
            1,
        )
        .unwrap();
    (e, swimmer, bystander)
}

/// "Fully immersed" means every tile, not any tile.
#[test]
fn a_creature_half_out_of_the_water_is_not_immersed() {
    use crate::engine::terrain::TerrainType;
    let (mut e, swimmer, bystander) = swimmer_and_bystander();
    assert!(e.is_immersed(swimmer), "all four tiles are water");
    assert!(!e.is_immersed(bystander), "the bank is dry");

    // Drain one corner of the swimmer's own 2x2 footprint. RAW's
    // "fully immersed" is now false, and every underwater rule has to
    // switch off with it.
    e.set_terrain_at(Coordinate::new(4, 4), TerrainType::Floor);
    assert!(
        !e.is_immersed(swimmer),
        "one dry tile under the footprint is enough to haul them out"
    );
}

/// Flight lifts a creature out of the water without draining it — the
/// row `is_immersed` shares with the movement cohort so the two can't
/// disagree about who the water has a hold on.
#[test]
fn a_flying_creature_over_a_pool_is_not_in_it() {
    let (mut e, swimmer, _) = swimmer_and_bystander();
    assert!(e.is_immersed(swimmer));
    e.actors
        .get_mut(&swimmer)
        .unwrap()
        .add_condition(Condition::Flying, ConditionTimer::Rounds(10));
    assert!(!e.is_immersed(swimmer), "they are over the pool, not in it");
}

/// A rider is in the water exactly when the thing carrying it is, and
/// its own swimming speed (or lack of one) still decides how it swings.
///
/// The two halves come apart on a mounted pair and nowhere else, which
/// is why the pair is the fixture. A Medium knight has a 2x2 footprint
/// and a Large warhorse a 4x4, and while the knight is in the saddle
/// only the horse's is stamped on the board — so reading the knight's
/// own span from the horse's anchor measures a quarter of the horse
/// that nothing occupies, and a horse standing with its forequarters in
/// a pool would have reported the knight submerged and itself dry.
#[test]
fn a_rider_is_immersed_when_its_mount_is_and_not_before() {
    use crate::actors::creatures::warhorses::WARHORSE_TEMPLATE;
    use crate::engine::terrain::TerrainType;

    let mut e = ei_with_terrain(20, 20, &[]);
    // A pool wide enough for the horse's whole 4x4 footprint, and one
    // tile of dry land at its edge for the half-in case.
    for x in 2..=5isize {
        for y in 2..=5isize {
            e.set_terrain_at(Coordinate::new(x, y), TerrainType::Water);
        }
    }
    let rider = e
        .instantiate_creature(
            &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
            Coordinate::new(10, 10),
            0,
            1,
        )
        .unwrap();
    let horse = e
        .instantiate_creature(&WARHORSE_TEMPLATE, Coordinate::new(2, 2), 0, 2)
        .unwrap();
    // Bring the rider alongside and mount up; the pair then moves as the
    // horse.
    e.place_actor_at(rider, Coordinate::new(6, 2)).unwrap();
    assert!(e.mount(rider, horse).is_ok());

    assert!(e.is_immersed(horse), "the horse's whole footprint is water");
    assert!(
        e.is_immersed(rider),
        "and a rider on a swimming horse is in the water with it"
    );

    // Drain one tile under the horse. Neither of them is fully immersed
    // any more — and in particular the rider stops being immersed even
    // though the tile that dried is outside the 2x2 its own span would
    // have covered.
    e.set_terrain_at(Coordinate::new(5, 5), TerrainType::Floor);
    assert!(!e.is_immersed(horse), "the horse is half out");
    assert!(
        !e.is_immersed(rider),
        "so is the rider, whose body is the horse's"
    );
}

/// The melee clause, end to end through the real verdict chokepoint:
/// the weapon decides, and a swimming speed excuses the whole question.
#[test]
fn the_melee_clause_reads_the_weapon_and_the_swimming_speed() {
    use crate::engine::underwater::UnderwaterVerdict;
    let (mut e, swimmer, _) = swimmer_and_bystander();

    let verdict = |e: &EncounterInstance, weapon: &str| {
        e.underwater_verdict(swimmer, weapon, true, true, false)
    };
    assert_eq!(verdict(&e, "longsword"), UnderwaterVerdict::Disadvantage);
    assert_eq!(verdict(&e, "trident"), UnderwaterVerdict::Unaffected);

    // A swimming speed excuses the longsword as well — RAW exempts the
    // creature, not just the five weapons.
    e.actors
        .get_mut(&swimmer)
        .unwrap()
        .grant_feature_for_test(crate::actions::class_features::SWIM_SPEED_TAG);
    assert_eq!(verdict(&e, "longsword"), UnderwaterVerdict::Unaffected);
}

/// The ranged clause, and the asymmetry that is easiest to get wrong: a
/// swimming speed saves the swing and not the shot.
#[test]
fn the_ranged_clause_ignores_a_swimming_speed() {
    use crate::engine::underwater::UnderwaterVerdict;
    let (mut e, swimmer, _) = swimmer_and_bystander();
    e.actors
        .get_mut(&swimmer)
        .unwrap()
        .grant_feature_for_test(crate::actions::class_features::SWIM_SPEED_TAG);

    assert_eq!(
        e.underwater_verdict(swimmer, "longbow", false, true, false),
        UnderwaterVerdict::Disadvantage,
        "a swimming speed does not restring a bow"
    );
    assert_eq!(
        e.underwater_verdict(swimmer, "heavy crossbow", false, true, false),
        UnderwaterVerdict::Unaffected,
        "a crossbow is on the ranged cohort"
    );
    assert_eq!(
        e.underwater_verdict(swimmer, "heavy crossbow", false, true, true),
        UnderwaterVerdict::AutoMiss,
        "and nothing survives the range cut"
    );
}

/// A shot past normal range from the water misses, however good the
/// roll — and it misses as a *swing that happened*, spending its
/// resource and printing a line, rather than as an action that was
/// never taken.
#[test]
fn a_shot_past_normal_range_from_the_water_cannot_land() {
    use crate::engine::dice::Dice;
    use crate::engine::types::DamageType;
    let (mut e, swimmer, bystander) = swimmer_and_bystander();
    // Park the target well outside a 2-tile normal range but inside the
    // reach the attack is allowed to try at.
    e.place_actor_at(bystander, Coordinate::new(14, 3)).unwrap();

    let params = crate::engine::attack::AttackParams {
        caster_id: swimmer,
        target_id: bystander,
        action_name: "longbow",
        // Absurd enough that no AC on the board could survive it.
        attack_bonus: 50,
        damage_dice: Dice::new(1, 8),
        damage_bonus: 0,
        damage_type: DamageType::Piercing,
        is_melee: false,
        long_range: Some(2),
        min_range: None,
        is_spell: false,
    };
    let (effects, damage) = crate::engine::attack::resolve_attack_outcome(&mut e, params);
    assert_eq!(damage, 0, "the shot cannot hit");
    assert!(effects.is_empty(), "and lands no damage side effect");
    assert!(
        e.messages()
            .iter()
            .any(|l| l.contains("underwater, past normal range")),
        "the log says why: {:?}",
        e.messages().last()
    );
}

/// The same shot from dry land, with everything else identical, lands.
/// Without this the test above would pass on a bug that made every
/// longbow shot miss.
#[test]
fn the_same_shot_from_the_bank_connects() {
    use crate::engine::dice::Dice;
    use crate::engine::types::DamageType;
    let (mut e, swimmer, bystander) = swimmer_and_bystander();
    e.place_actor_at(bystander, Coordinate::new(14, 3)).unwrap();
    // Haul the archer onto dry ground; the pool is at 2..=5.
    e.place_actor_at(swimmer, Coordinate::new(8, 8)).unwrap();
    assert!(!e.is_immersed(swimmer));

    let params = crate::engine::attack::AttackParams {
        caster_id: swimmer,
        target_id: bystander,
        action_name: "longbow",
        attack_bonus: 50,
        damage_dice: Dice::new(1, 8),
        damage_bonus: 0,
        damage_type: DamageType::Piercing,
        is_melee: false,
        long_range: Some(2),
        min_range: None,
        is_spell: false,
    };
    let (_, damage) = crate::engine::attack::resolve_attack_outcome(&mut e, params);
    assert!(damage > 0, "a +50 shot from the bank connects");
}

/// "Weapon attack", throughout: a spell attack out of the water is
/// unaffected by all three clauses, including the range cut.
#[test]
fn a_spell_attack_out_of_the_water_is_untouched() {
    use crate::engine::underwater::UnderwaterVerdict;
    let (e, swimmer, _) = swimmer_and_bystander();
    for (melee, past_range) in [(true, false), (false, false), (false, true)] {
        assert_eq!(
            e.underwater_verdict(swimmer, "fire bolt", melee, false, past_range),
            UnderwaterVerdict::Unaffected,
            "melee={melee} past_range={past_range}"
        );
    }
}

/// The picker's answer to "is this a weapon attack" and the die's are
/// the same answer, for every weapon chassis in the armoury.
///
/// There are two copies of that fact and there have to be.
/// `resolve_attack` reads `!AttackParams::is_spell`, which is
/// authoritative; the AI's attack picker holds a `&dyn Action` and can
/// only ask `Action::is_weapon_attack`. Four chassis used to answer
/// `false` there while answering `true` down at the die — every
/// save-rider and flat-rider natural weapon in the bestiary, plus the
/// drow's hand crossbow.
///
/// The visible cost was in the water. The picker ranked a swing as
/// though the water cost it nothing and the die then rolled it at
/// disadvantage, and a shot the water makes impossible was never
/// dropped from the candidate list — the `AutoMiss` early-out is the
/// one underwater clause the picker owns outright, and it fires only
/// for something it believes is a weapon.
///
/// **Read off the armoury source rather than off the templates**, and
/// for the reason `a_weapon_deals_the_damage_its_name_implies` gives
/// next door: a template walk can only see chassis that something in
/// the pool happens to carry, and the failure being guarded against is
/// a whole chassis — the unit a fifth one would be added as. Every
/// `impl Action for Weapon*` block in the armoury is a shared weapon
/// chassis by construction of its name, and every one of them has to
/// answer the question the same way the die does.
#[test]
fn every_weapon_chassis_in_the_armoury_admits_to_being_one() {
    use std::path::Path;
    let source = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("src/actions/monster_attacks.rs"),
    )
    .expect("the armoury should be readable");

    let blocks: Vec<&str> = source.split("\nimpl Action for ").skip(1).collect();
    let mut checked = 0;
    for block in blocks {
        let name = block.split_whitespace().next().unwrap_or("");
        // The shared chassis, by the naming convention they are
        // declared under. Bespoke one-off actions (`GhoulClaws`,
        // `BeholderEyeRay`) are deliberately out of scope: the trait
        // doc says a bespoke natural weapon may leave the flag false,
        // and a sweep that demanded otherwise would be inventing a
        // rule rather than enforcing one.
        if !name.starts_with("Weapon") && name != "SimpleWeapon" {
            continue;
        }
        checked += 1;
        assert!(
            block.contains("fn is_weapon_attack"),
            "{} is a shared weapon chassis and does not declare is_weapon_attack — \
             the AI's picker will read it as a spell while the die reads it as a swing",
            name
        );
    }
    assert!(
        checked >= 5,
        "expected the armoury's five weapon chassis, found {}",
        checked
    );

    // …and one live instance of each, so a regression that deletes an
    // override fails on the weapon's name as well as the chassis's.
    use crate::actions::action_template::Action;
    use crate::actions::monster_attacks::{
        BEARDED_DEVIL_BEARD, CHUUL_PINCER, DROW_POISONED_CROSSBOW, WOLF_BITE, YETI_CLAWS,
    };
    for a in [
        &YETI_CLAWS as &dyn Action,          // WeaponWithRider
        &WOLF_BITE,                          // WeaponWithSaveCondition
        &BEARDED_DEVIL_BEARD,                // …and a second of the same
        &CHUUL_PINCER,                       // WeaponWithCondition
        &DROW_POISONED_CROSSBOW,             // WeaponWithSaveDamage, ranged
    ] {
        assert!(
            a.is_weapon_attack(),
            "{} resolves as a weapon swing and must say so",
            a.name()
        );
    }

    // …and the drow's crossbow declares the band the `AutoMiss` clause
    // needs. Without it `beyond_normal_range` is never true and the
    // clause cannot fire however honest the weapon flag is.
    assert_eq!(DROW_POISONED_CROSSBOW.normal_range, Some(12));
}

/// The three underwater outcomes, read off a rider-chassis weapon
/// rather than a `SimpleWeapon` — which is the case that used to come
/// back `Unaffected` for all three.
#[test]
fn a_save_rider_weapon_obeys_the_water_like_any_other() {
    use crate::actions::action_template::Action;
    use crate::actions::monster_attacks::{DROW_POISONED_CROSSBOW, WOLF_BITE};
    use crate::engine::underwater::UnderwaterVerdict;
    let (e, swimmer, _) = swimmer_and_bystander();

    // A bite is not one of RAW's five thrusting weapons, so a swimmer
    // without a swimming speed bites at disadvantage. This is the
    // verdict that used to come back `Unaffected` — not because the
    // wolf was exempt, but because the chassis claimed the bite was not
    // a weapon attack and the whole rule was skipped.
    let bite: &dyn Action = &WOLF_BITE;
    assert_eq!(
        e.underwater_verdict(swimmer, bite.name(), true, bite.is_weapon_attack(), false),
        UnderwaterVerdict::Disadvantage,
        "a bite drags through the water like any other swing"
    );

    // A crossbow is exempt from the ranged disadvantage clause…
    let bow: &dyn Action = &DROW_POISONED_CROSSBOW;
    assert_eq!(
        e.underwater_verdict(swimmer, bow.name(), false, bow.is_weapon_attack(), false),
        UnderwaterVerdict::Unaffected,
    );
    // …and exempt from nothing at all past its normal range.
    assert_eq!(
        e.underwater_verdict(swimmer, bow.name(), false, bow.is_weapon_attack(), true),
        UnderwaterVerdict::AutoMiss,
        "no ranged weapon escapes the range cut"
    );
}

/// "Creatures and objects that are fully immersed in water have
/// resistance to fire damage."
#[test]
fn being_immersed_halves_fire_damage() {
    use crate::engine::side_effects::DealDamage;
    use crate::engine::types::DamageType;
    let (mut e, swimmer, bystander) = swimmer_and_bystander();

    // Small enough that neither fighter's HP pool clamps the subtraction
    // — a creature dropped to 0 would report the halving and the clamp
    // as the same number and prove nothing.
    for (id, expected, who) in [(swimmer, 4u32, "the swimmer"), (bystander, 8, "the bystander")] {
        let before = e.actors[&id].hitpoints();
        assert!(before > 8, "{who} has room to take the hit");
        DealDamage {
            actor_id: id,
            amount: 8,
            damage_type: DamageType::Fire,
        }
        .apply(&mut e);
        let took = before - e.actors[&id].hitpoints();
        assert_eq!(took, expected, "{who} took {took} of 8 fire");
    }
}

/// The water shields against fire and nothing else — the row is
/// type-filtered, and a positional halving that covered everything
/// would be a resistance to all damage.
#[test]
fn the_water_does_not_shield_against_anything_but_fire() {
    use crate::engine::side_effects::DealDamage;
    use crate::engine::types::DamageType;
    for dt in [DamageType::Cold, DamageType::Lightning, DamageType::Slashing] {
        let (mut e, swimmer, _) = swimmer_and_bystander();
        let before = e.actors[&swimmer].hitpoints();
        assert!(before > 8, "the swimmer has room to take the hit");
        DealDamage {
            actor_id: swimmer,
            amount: 8,
            damage_type: dt,
        }
        .apply(&mut e);
        assert_eq!(
            before - e.actors[&swimmer].hitpoints(),
            8,
            "{dt:?} is not halved by standing in a pool"
        );
    }
}

/// 5e's "multiple instances of resistance count as only one": a
/// fire-resistant creature standing in a pool takes half, not a
/// quarter. The gate that holds this is `has_own_typed_reduction`, and
/// it is shared with the aura row rather than re-derived per row.
#[test]
fn a_fire_resistant_creature_in_a_pool_is_not_resistant_twice() {
    use crate::engine::side_effects::DealDamage;
    use crate::engine::types::DamageType;
    let (mut e, _, _) = swimmer_and_bystander();
    // A magmin is fire-immune, which is the strongest form of "has its
    // own reduction" — the positional row must stand down entirely
    // rather than halving on top of a zero.
    let magmin = e
        .instantiate_creature(
            &crate::actors::creatures::magmins::MAGMIN_TEMPLATE,
            Coordinate::new(2, 2),
            1,
            1,
        )
        .unwrap();
    assert!(e.is_immersed(magmin));
    let before = e.actors[&magmin].hitpoints();
    DealDamage {
        actor_id: magmin,
        amount: 20,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    assert_eq!(
        before,
        e.actors[&magmin].hitpoints(),
        "immunity still wins outright"
    );
}

#[test]
fn short_rest_heals_some_hp() {
    let mut roller = FastRandRoller::with_seed(42);
    let mut fighter = ActorInstance::from_creature_template(
        &crate::actors::creatures::fighters::FIGHTER_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut roller,
        1,
    )
    .unwrap();
    let max_hp = fighter.max_hitpoints();
    fighter.take_damage(max_hp / 2);
    let hp_before = fighter.hitpoints();
    assert!(hp_before < max_hp);
    fighter.short_rest(&mut roller);
    assert!(
        fighter.hitpoints() >= hp_before,
        "short rest should heal at least some HP"
    );
}

/// A short rest should restore every feature in `SHORT_REST_FEATURES`
/// for actors that have it on their template. Catch any new feature
/// that gets registered in the short-rest list but skipped by the
/// per-actor refresh path.
#[test]
fn short_rest_restores_arcane_recovery() {
    use crate::actions::class_features::ARCANE_RECOVERY_TAG;
    let mut roller = FastRandRoller::with_seed(42);
    let mut wizard = ActorInstance::from_creature_template(
        &crate::actors::creatures::wizards::WIZARD_TEMPLATE,
        Coordinate::new(0, 0),
        0,
        &mut roller,
        1,
    )
    .unwrap();
    assert!(wizard.feature_available(ARCANE_RECOVERY_TAG));
    wizard.spend_feature(ARCANE_RECOVERY_TAG);
    assert!(!wizard.feature_available(ARCANE_RECOVERY_TAG));
    wizard.short_rest(&mut roller);
    assert!(
        wizard.feature_available(ARCANE_RECOVERY_TAG),
        "arcane recovery should refresh on short rest"
    );
}

