/// Pearl of Power: a caster who has spent a level-1 slot can crush
/// the pearl as a bonus action to refund the slot. Single-use — the
/// pearl is removed from inventory whether or not the refund lands
/// (mirrors the rest of the consumable lane). Verifies the slot
/// returns to its template max and the pearl is consumed.
#[test]
fn pearl_of_power_restores_a_level_one_slot() {
    use crate::actions::action_template::Action;
    use crate::actions::item_actions::USE_PEARL_OF_POWER;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::items::item_template::PEARL_OF_POWER;

    let mut e = ei_with_terrain(15, 15, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    // Spend a level-1 slot and pocket the pearl.
    let pre = e.actors[&wiz].spell_slot_manager.spell_slots(1);
    assert!(pre.max_spell_slots > 0, "wizard should have lvl-1 slots");
    e.actors.get_mut(&wiz).unwrap().spell_slot_manager.consume_spell_slot(1);
    e.actors.get_mut(&wiz).unwrap().pickup_item(&PEARL_OF_POWER);
    let after_spend = e.actors[&wiz].spell_slot_manager.spell_slots(1);
    assert_eq!(after_spend.spell_slots, pre.spell_slots - 1);

    // Use the pearl — bonus action, restores the slot, consumes the item.
    let action: &dyn Action = &USE_PEARL_OF_POWER;
    for ef in action.side_effects(&mut e, wiz, None, None, None) {
        ef.apply(&mut e);
    }
    let after = e.actors[&wiz].spell_slot_manager.spell_slots(1);
    assert_eq!(after.spell_slots, pre.spell_slots, "slot should be restored");
    assert!(
        !e.actors[&wiz].has_item_named("Pearl of Power"),
        "pearl should be consumed on use"
    );
}

/// Greater Pearl of Power: refunds a level-2 slot instead of the
/// regular Pearl's level-1. Verifies the parameterized
/// `PearlOfPowerItem` config picks up the right slot tier and
/// rejects when no level-2 slot is spent (no-op guard).
#[test]
fn greater_pearl_of_power_restores_a_level_two_slot() {
    use crate::actions::action_template::Action;
    use crate::actions::item_actions::USE_GREATER_PEARL_OF_POWER;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::items::item_template::GREATER_PEARL_OF_POWER;

    let mut e = ei_with_terrain(15, 15, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let pre = e.actors[&wiz].spell_slot_manager.spell_slots(2);
    assert!(pre.max_spell_slots > 0, "wizard should have lvl-2 slots");
    e.actors.get_mut(&wiz).unwrap().pickup_item(&GREATER_PEARL_OF_POWER);

    // Validate gate: with no level-2 slot spent, the pearl rejects.
    let action: &dyn Action = &USE_GREATER_PEARL_OF_POWER;
    assert!(
        !action.validate_input(&e, wiz, None, None, None),
        "no-op pearl use should be rejected when all slots are full"
    );

    // Spend a level-2 slot so the pearl has work to do.
    e.actors.get_mut(&wiz).unwrap().spell_slot_manager.consume_spell_slot(2);
    let after_spend = e.actors[&wiz].spell_slot_manager.spell_slots(2);
    assert_eq!(after_spend.spell_slots, pre.spell_slots - 1);

    // Fire the side-effects; verify the slot returns and the pearl
    // is consumed.
    for ef in action.side_effects(&mut e, wiz, None, None, None) {
        ef.apply(&mut e);
    }
    let after = e.actors[&wiz].spell_slot_manager.spell_slots(2);
    assert_eq!(
        after.spell_slots, pre.spell_slots,
        "level-2 slot should be restored"
    );
    assert!(
        !e.actors[&wiz].has_item_named("Greater Pearl of Power"),
        "greater pearl should be consumed on use"
    );
}

/// Supreme Pearl of Power: refunds a level-3 slot. Mirror of the
/// Greater Pearl test; verifies the top tier in the pearl ladder.
#[test]
fn supreme_pearl_of_power_restores_a_level_three_slot() {
    use crate::actions::action_template::Action;
    use crate::actions::item_actions::USE_SUPREME_PEARL_OF_POWER;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::items::item_template::SUPREME_PEARL_OF_POWER;

    let mut e = ei_with_terrain(15, 15, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let pre = e.actors[&wiz].spell_slot_manager.spell_slots(3);
    assert!(pre.max_spell_slots > 0, "wizard should have lvl-3 slots");
    e.actors.get_mut(&wiz).unwrap().spell_slot_manager.consume_spell_slot(3);
    e.actors.get_mut(&wiz).unwrap().pickup_item(&SUPREME_PEARL_OF_POWER);

    let action: &dyn Action = &USE_SUPREME_PEARL_OF_POWER;
    for ef in action.side_effects(&mut e, wiz, None, None, None) {
        ef.apply(&mut e);
    }
    let after = e.actors[&wiz].spell_slot_manager.spell_slots(3);
    assert_eq!(
        after.spell_slots, pre.spell_slots,
        "level-3 slot should be restored"
    );
    assert!(
        !e.actors[&wiz].has_item_named("Supreme Pearl of Power"),
        "supreme pearl should be consumed on use"
    );
}

/// Ring of Poison Resistance: passive trinket; the wearer takes half
/// poison damage. Mirrors the existing elemental-resistance ring
/// tests for the four classic burst types.
#[test]
fn ring_of_poison_resistance_halves_poison_damage() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::types::DamageType;
    use crate::items::item_template::RING_OF_POISON_RESISTANCE;

    let mut e = ei_with_terrain(15, 15, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&fighter)
        .unwrap()
        .pickup_item(&RING_OF_POISON_RESISTANCE);
    let before = e.actors[&fighter].hitpoints();
    crate::engine::side_effects::DealDamage {
        actor_id: fighter,
        amount: 10,
        damage_type: DamageType::Poison,
    }
    .apply(&mut e);
    let after = e.actors[&fighter].hitpoints();
    assert_eq!(
        before - after,
        5,
        "ring of poison resistance should halve incoming poison damage"
    );
}

/// Ring of Radiant / Necrotic / Thunder / Psychic Resistance: same
/// resistance shape as the poison ring; this folds the four siblings
/// into one parameterized table-driven check so the loot pool's
/// resistance lane is covered end-to-end.
#[test]
fn secondary_resistance_rings_halve_damage() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::engine::types::DamageType;
    use crate::items::item_template::{
        Item, RING_OF_NECROTIC_RESISTANCE, RING_OF_PSYCHIC_RESISTANCE,
        RING_OF_RADIANT_RESISTANCE, RING_OF_THUNDER_RESISTANCE,
    };

    let cases: &[(&'static Item, DamageType)] = &[
        (&RING_OF_RADIANT_RESISTANCE, DamageType::Radiant),
        (&RING_OF_NECROTIC_RESISTANCE, DamageType::Necrotic),
        (&RING_OF_THUNDER_RESISTANCE, DamageType::Thunder),
        (&RING_OF_PSYCHIC_RESISTANCE, DamageType::Psychic),
    ];
    for (ring, dtype) in cases {
        let mut e = ei_with_terrain(15, 15, &[]);
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        e.actors.get_mut(&f).unwrap().pickup_item(ring);
        let before = e.actors[&f].hitpoints();
        crate::engine::side_effects::DealDamage {
            actor_id: f,
            amount: 10,
            damage_type: *dtype,
        }
        .apply(&mut e);
        let dealt = before - e.actors[&f].hitpoints();
        assert_eq!(
            dealt, 5,
            "{} should halve incoming {:?} damage",
            ring.name, dtype
        );
    }
}

/// Scroll of Mass Healing Word: bonus-action consumable that heals
/// up to 6 nearest allies in 60 ft for 1d4+3. Verifies that the
/// scroll heals the caster, heals at least one nearby ally, and
/// is removed from inventory.
#[test]
fn scroll_of_mass_healing_word_heals_allies_and_consumes() {
    use crate::actions::action_template::Action;
    use crate::actions::item_actions::READ_MASS_HEALING_WORD_SCROLL;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::items::item_template::SCROLL_OF_MASS_HEALING_WORD;

    let mut e = ei_with_terrain(15, 15, &[]);
    let cleric = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(7, 5), 0, 0)
        .unwrap();
    // Wound both lightly so the heal has something to do but neither
    // drops to dying / dead.
    e.actors.get_mut(&cleric).unwrap().take_damage(2);
    e.actors.get_mut(&ally).unwrap().take_damage(2);
    let cleric_hp_before = e.actors[&cleric].hitpoints();
    let ally_hp_before = e.actors[&ally].hitpoints();
    e.actors
        .get_mut(&cleric)
        .unwrap()
        .pickup_item(&SCROLL_OF_MASS_HEALING_WORD);

    let action: &dyn Action = &READ_MASS_HEALING_WORD_SCROLL;
    for ef in action.side_effects(&mut e, cleric, None, None, None) {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&cleric].hitpoints() > cleric_hp_before,
        "scroll should heal the reader"
    );
    assert!(
        e.actors[&ally].hitpoints() > ally_hp_before,
        "scroll should heal the nearby ally"
    );
    assert!(
        !e.actors[&cleric].has_item_named("Scroll of Mass Healing Word"),
        "scroll should be consumed on use"
    );
}

/// Boots of Speed: bonus-action consumable that installs `Fleet` for
/// 10 rounds and removes the boots from inventory.
///
/// `Fleet` and not `Hasted`, which is what it used to install. RAW's
/// boots read "your walking speed is doubled" and stop there; borrowing
/// the spell's condition for that one clause also handed the wearer +2
/// AC, advantage on Dexterity saves and — once the spell's own extra
/// Action landed — a second Action every round, off a bonus action and
/// no spell slot. The doubled speed is asserted here alongside the
/// install, because it is the only clause either printing agrees on.
#[test]
fn boots_of_speed_install_fleet_and_consume() {
    use crate::actions::action_template::Action;
    use crate::actions::item_actions::WEAR_BOOTS_OF_SPEED;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::items::item_template::BOOTS_OF_SPEED;

    let mut e = ei_with_terrain(15, 15, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    e.actors.get_mut(&fighter).unwrap().pickup_item(&BOOTS_OF_SPEED);
    assert!(!e.actors[&fighter].has_condition(Condition::Fleet));
    let base_speed = e.actors[&fighter].speed();

    let action: &dyn Action = &WEAR_BOOTS_OF_SPEED;
    for ef in action.side_effects(&mut e, fighter, None, None, None) {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&fighter].has_condition(Condition::Fleet),
        "boots should install Fleet"
    );
    assert_eq!(
        e.actors[&fighter].speed(),
        base_speed * 2.0,
        "which is RAW's whole first sentence"
    );
    assert!(
        !e.actors[&fighter].has_condition(Condition::Hasted),
        "and none of the spell that used to come with it"
    );
    assert!(
        !e.actors[&fighter].has_item_named("Boots of Speed"),
        "boots should be consumed on use"
    );
}

/// Wand of Paralysis aimed at a Ring-of-Free-Action wearer is a
/// no-op: the wearer is condition-immune to Paralyzed, so the save
/// is skipped entirely (preserving the Heightened Spell prime if
/// one is up). Wand still consumes — the player chose to fire it.
/// Regression test for the `SingleSaveConditionItem` immunity-skip
/// optimization.
#[test]
fn wand_of_paralysis_skips_save_on_immune_target() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::USE_WAND_OF_PARALYSIS;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::Condition;
    use crate::items::item_template::{RING_OF_FREE_ACTION, WAND_OF_PARALYSIS};

    let mut e = ei_with_terrain(15, 15, &[]);
    let caster = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let immune_target = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(6, 2), 1, 0)
        .unwrap();
    e.actors
        .get_mut(&caster)
        .unwrap()
        .pickup_item(&WAND_OF_PARALYSIS);
    // Ring of Free Action makes the target immune to Paralyzed.
    e.actors
        .get_mut(&immune_target)
        .unwrap()
        .pickup_item(&RING_OF_FREE_ACTION);
    let aei = ActionExecutionInfo::new(
        &USE_WAND_OF_PARALYSIS,
        caster,
        Some(vec![immune_target]),
        None,
        None,
    );
    assert!(aei.validate(&e));
    e.push_action(aei);
    e.process_stack();
    // Target was immune so the install can't land — confirm the
    // condition is NOT installed (would happen anyway via the
    // `add_condition` immunity gate, but the skip preserves the
    // Heightened prime by avoiding the save roll).
    assert!(
        !e.actors[&immune_target].has_condition(Condition::Paralyzed),
        "Ring of Free Action should block Paralyzed install"
    );
    // Wand still consumes — UX matches the player's intent.
    assert!(
        !e.actors[&caster].has_item_named("Wand of Paralysis"),
        "wand should still be consumed even on a no-op shot"
    );
}

/// Scroll of Bless: install `Blessed` for 10 rounds on a single ally
/// at touch range. Confirms the scroll consumes, the install lands on
/// the right actor, and the buff doesn't leak onto the caster (no
/// "self-target by default" surprise).
#[test]
fn scroll_of_bless_installs_blessed_on_ally() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::READ_BLESS_SCROLL;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::Condition;
    use crate::items::item_template::SCROLL_OF_BLESS;

    let mut e = ei_with_terrain(10, 10, &[]);
    let caster = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    e.actors
        .get_mut(&caster)
        .unwrap()
        .pickup_item(&SCROLL_OF_BLESS);
    let aei = ActionExecutionInfo::new(
        &READ_BLESS_SCROLL,
        caster,
        Some(vec![ally]),
        None,
        None,
    );
    assert!(aei.validate(&e));
    e.push_action(aei);
    e.process_stack();
    assert!(
        e.actors[&ally].has_condition(Condition::Blessed),
        "ally should be Blessed after scroll use"
    );
    assert!(
        !e.actors[&caster].has_condition(Condition::Blessed),
        "caster should not pick up Blessed (scroll targets the picked ally only)"
    );
    assert!(
        e.actors[&caster].items().is_empty(),
        "bless scroll should be consumed on use"
    );
}

/// Scroll of Bless rejects a re-cast on an already-Blessed ally.
/// `add_condition` would keep the longer timer either way, so the
/// re-cast would be a no-op — the `reject_when_active` gate spares
/// the consumable from being burned on a refresh.
#[test]
fn scroll_of_bless_rejects_already_blessed_target() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::READ_BLESS_SCROLL;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::{Condition, ConditionTimer};
    use crate::items::item_template::SCROLL_OF_BLESS;

    let mut e = ei_with_terrain(10, 10, &[]);
    let caster = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    e.actors
        .get_mut(&caster)
        .unwrap()
        .pickup_item(&SCROLL_OF_BLESS);
    // Pre-install Blessed; the re-cast should reject.
    e.actors
        .get_mut(&ally)
        .unwrap()
        .add_condition(Condition::Blessed, ConditionTimer::Rounds(10));
    let aei = ActionExecutionInfo::new(
        &READ_BLESS_SCROLL,
        caster,
        Some(vec![ally]),
        None,
        None,
    );
    assert!(
        !aei.validate(&e),
        "re-cast Bless on an already-blessed ally should be rejected"
    );
    // Scroll should still be in inventory (not consumed by the rejection).
    assert!(
        e.actors[&caster].has_item_named("Scroll of Bless"),
        "rejected validate must not consume the scroll"
    );
}

/// Scroll of Bane: 4-tile burst, CHA save vs DC 13, fail = Baned for
/// 10 rounds. Seed-swept so the probabilistic save path lands at least
/// once; the burst should hit enemies (Baned debuff) but spare the
/// caster (enemy-only burst filter).
#[test]
fn scroll_of_bane_installs_baned_on_failed_save() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::READ_BANE_SCROLL;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::Condition;
    use crate::items::item_template::SCROLL_OF_BANE;

    let trials = 50u64;
    let mut any_baned = false;
    for seed in 0..trials {
        let mut e = ei_seeded(20, 20, &[], seed);
        let caster = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let enemy = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(7, 7), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&caster)
            .unwrap()
            .pickup_item(&SCROLL_OF_BANE);
        let aei = ActionExecutionInfo::new(
            &READ_BANE_SCROLL,
            caster,
            None,
            Some(vec![Coordinate::new(7, 7)]),
            None,
        );
        assert!(aei.validate(&e));
        e.push_action(aei);
        e.process_stack();
        assert!(
            e.actors[&caster].items().is_empty(),
            "bane scroll should be consumed on use (seed {})",
            seed
        );
        // Caster never makes a save — enemy-burst filter excludes
        // them, so they shouldn't be Baned.
        assert!(
            !e.actors[&caster].has_condition(Condition::Baned),
            "caster should not be Baned (enemy-only burst, seed {})",
            seed
        );
        if e.actors[&enemy].has_condition(Condition::Baned) {
            any_baned = true;
            break;
        }
    }
    assert!(
        any_baned,
        "scroll of bane never installed Baned across {} seeds",
        trials
    );
}

/// Wand of Polymorph: single-target WIS save vs DC 15, fail =
/// Polymorphed for 10 rounds. Seed-swept; should land on a zombie
/// (poor WIS, no WIS save proficiency, no Polymorphed-immunity).
#[test]
fn wand_of_polymorph_installs_polymorphed_on_failed_save() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::USE_WAND_OF_POLYMORPH;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::Condition;
    use crate::items::item_template::WAND_OF_POLYMORPH;

    let trials = 50u64;
    let mut any_polymorphed = false;
    for seed in 0..trials {
        let mut e = ei_seeded(20, 20, &[], seed);
        let caster = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let zombie = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(6, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&caster)
            .unwrap()
            .pickup_item(&WAND_OF_POLYMORPH);
        let aei = ActionExecutionInfo::new(
            &USE_WAND_OF_POLYMORPH,
            caster,
            Some(vec![zombie]),
            None,
            None,
        );
        assert!(aei.validate(&e));
        e.push_action(aei);
        e.process_stack();
        assert!(
            e.actors[&caster].items().is_empty(),
            "wand should be consumed on use (seed {})",
            seed
        );
        if e.actors[&zombie].has_condition(Condition::Polymorphed) {
            any_polymorphed = true;
            // The wand also grants the beast-form 30 temp HP buffer
            // (mirroring the Polymorph spell). Confirm the buffer
            // lands alongside the condition install.
            assert_eq!(
                e.actors[&zombie].temp_hp(),
                30,
                "wand of polymorph should grant 30 temp HP buffer (seed {})",
                seed
            );
            break;
        }
    }
    assert!(
        any_polymorphed,
        "wand of polymorph never installed Polymorphed across {} seeds",
        trials
    );
}

/// Potion of Barkskin: bonus-action self-install of `Barkskinned`
/// for 10 rounds. Consumes the potion and rejects a re-drink on the
/// same actor (the SelfConditionItem reject-when-active gate).
#[test]
fn potion_of_barkskin_installs_and_rejects_redrink() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::DRINK_POTION_OF_BARKSKIN;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::Condition;
    use crate::items::item_template::POTION_OF_BARKSKIN;

    let mut e = ei_with_terrain(10, 10, &[]);
    let actor = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&actor)
        .unwrap()
        .pickup_item(&POTION_OF_BARKSKIN);
    // Give a second potion so the redrink-reject test can verify the
    // second potion is NOT consumed.
    e.actors
        .get_mut(&actor)
        .unwrap()
        .pickup_item(&POTION_OF_BARKSKIN);
    let aei = ActionExecutionInfo::new(
        &DRINK_POTION_OF_BARKSKIN,
        actor,
        None,
        None,
        None,
    );
    assert!(aei.validate(&e));
    e.push_action(aei);
    e.process_stack();
    assert!(
        e.actors[&actor].has_condition(Condition::Barkskinned),
        "drinking should install Barkskinned"
    );
    assert_eq!(
        e.actors[&actor].items().len(),
        1,
        "one potion should be consumed, one should remain"
    );
    // Re-drink while the buff is up should fail to validate.
    let aei2 = ActionExecutionInfo::new(
        &DRINK_POTION_OF_BARKSKIN,
        actor,
        None,
        None,
        None,
    );
    assert!(
        !aei2.validate(&e),
        "re-drink while Barkskinned should be rejected"
    );
}

