/// Potion of Resistance: action self-install of `DamageResistant` for
/// 10 rounds. Mirrors the Potion of Stoneskin envelope (same condition,
/// same timer) — confirms the install and the redrink-rejection gate.
#[test]
fn potion_of_resistance_installs_and_rejects_redrink() {
    use crate::actions::action_template::ActionExecutionInfo;
    use crate::actions::item_actions::DRINK_POTION_OF_RESISTANCE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::conditions::Condition;
    use crate::items::item_template::POTION_OF_RESISTANCE;

    let mut e = ei_with_terrain(10, 10, &[]);
    let actor = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&actor)
        .unwrap()
        .pickup_item(&POTION_OF_RESISTANCE);
    e.actors
        .get_mut(&actor)
        .unwrap()
        .pickup_item(&POTION_OF_RESISTANCE);
    let aei = ActionExecutionInfo::new(
        &DRINK_POTION_OF_RESISTANCE,
        actor,
        None,
        None,
        None,
    );
    assert!(aei.validate(&e));
    e.push_action(aei);
    e.process_stack();
    assert!(
        e.actors[&actor].has_condition(Condition::EnergyWarded),
        "drinking should install the ward"
    );
    // The unlabelled bottle picks a type on the way down, and it must
    // pick *a* type — a ward with no type recorded resists nothing and
    // would look exactly like a ward that works.
    assert!(
        e.actors[&actor]
            .damage_type_of(Condition::EnergyWarded)
            .is_some(),
        "the potion warded against nothing in particular"
    );
    assert_eq!(
        e.actors[&actor].items().len(),
        1,
        "one potion should be consumed, one should remain"
    );
    let aei2 = ActionExecutionInfo::new(
        &DRINK_POTION_OF_RESISTANCE,
        actor,
        None,
        None,
        None,
    );
    assert!(
        !aei2.validate(&e),
        "re-drink while already warded should be rejected"
    );
}

