/// Seeded sibling of `ei_with_terrain` — same hand-crafted terrain
/// shape but the encounter's RNG is initialized from `seed` so callers
/// can sweep seeds for probabilistic assertions while keeping a
/// deterministic per-iteration roll trace.
fn ei_seeded(
    width: usize,
    height: usize,
    walls: &[(isize, isize)],
    seed: u64,
) -> EncounterInstance {
    let tp = TerrainGenParams {
        width,
        height,
        branch_depth: 0,
        branch_prob: 0.0,
    };
    let ap = ActorGenParams {
        cr_target: 0.0,
        n_teams: 0,
        pc_template: None,
        start_team: 0,
    };
    let mut e = EncounterInstance::from_params(&tp, &ap, Some(seed)).unwrap();
    e.terrain = vec![
        TerrainInfo {
            terrain_type: TerrainType::Floor,
        };
        width * height
    ];
    for &(x, y) in walls {
        let idx = e.idx(Coordinate::new(x, y)).unwrap();
        e.terrain[idx] = TerrainInfo {
            terrain_type: TerrainType::Wall,
        };
    }
    e
}

/// Flame Arrows: self-cast installs `FlamingArrowed` on the caster
/// AND starts concentration. Drops cleanly on concentration end.
#[test]
fn flame_arrows_self_install_and_concentration_drop() {
    use crate::actions::spells::FLAME_ARROWS;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    let mut e = ei_with_terrain(10, 10, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let effs = FLAME_ARROWS.side_effects(&mut e, wiz, None, None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&wiz].has_condition(Condition::FlamingArrowed),
        "Flame Arrows installs FlamingArrowed on the caster"
    );
    assert!(
        e.actors[&wiz].is_concentrating(),
        "Flame Arrows is concentration-bound"
    );
    e.drop_concentration(wiz);
    assert!(
        !e.actors[&wiz].has_condition(Condition::FlamingArrowed),
        "dropping concentration strips FlamingArrowed"
    );
}

