/// Raise Dead: cast on a dying ally revives them to 1 HP. Validate
/// gates on `is_dying` — a healthy target rejects the cast.
#[test]
fn raise_dead_revives_dying_ally_to_1_hp() {
    use crate::actions::spells::RAISE_DEAD;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let cleric = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 0)
        .unwrap();
    // Knock the ally to dying via a massive damage hit.
    let max_hp = e.actors[&ally].max_hitpoints();
    e.actors.get_mut(&ally).unwrap().take_damage(max_hp);
    assert!(
        e.actors[&ally].is_dying(),
        "ally should be dying after massive damage"
    );
    let tv = vec![ally];
    assert!(
        RAISE_DEAD.validate_input(&e, cleric, Some(&tv), None, None),
        "Raise Dead should validate on a dying ally"
    );
    let effs = RAISE_DEAD.side_effects(&mut e, cleric, Some(&tv), None, None);
    for ef in effs {
        ef.apply(&mut e);
    }
    assert!(
        !e.actors[&ally].is_dying(),
        "Raise Dead pulls the ally out of dying"
    );
    assert_eq!(
        e.actors[&ally].hitpoints(),
        1,
        "Raise Dead restores to 1 HP (Revivify-style floor)"
    );
}

/// Raise Dead rejects a healthy target — slot-burning Cure Wounds
/// would be the wrong tool. Mirrors True Resurrection's gate.
#[test]
fn raise_dead_rejects_healthy_target() {
    use crate::actions::spells::RAISE_DEAD;
    use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    let mut e = ei_with_terrain(15, 15, &[]);
    let cleric = e
        .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 0, 0)
        .unwrap();
    let tv = vec![ally];
    assert!(
        !RAISE_DEAD.validate_input(&e, cleric, Some(&tv), None, None),
        "Raise Dead must reject a healthy target"
    );
}

/// Darkness lays a sphere of heavy obscurement rather than marking
/// whoever stood in it. The attack-mode consequence is the same
/// symmetric envelope the old `Darkened` condition hand-rolled —
/// nobody in the dark can see out and nobody outside can see in —
/// but it now follows the ground: a creature that steps clear can
/// see again, and one that steps in cannot.
#[test]
fn darkness_lays_a_sphere_nobody_sees_through() {
    use crate::actions::spells::DARKNESS;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::side_effects::MoveActor;

    let mut e = ei_with_terrain(30, 30, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let enemy = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(16, 16), 1, 0)
        .unwrap();
    assert!(e.viewer_can_see(wiz, enemy));
    let pt = vec![Coordinate::new(16, 16)];
    for ef in DARKNESS.side_effects(&mut e, wiz, None, Some(&pt), None) {
        ef.apply(&mut e);
    }
    // Nobody picks up a condition; the dark is on the map.
    assert!(e.actors[&enemy].conditions().is_empty());
    assert!(e.tile_is_obscured(Coordinate::new(16, 16)));
    assert!(!e.viewer_can_see(wiz, enemy));
    assert!(!e.viewer_can_see(enemy, wiz));
    // Blind both ways means the two clauses cancel at the attack
    // roll — 5e's unseen-attacker rule.
    assert_eq!(
        e.compute_attack_mode(wiz, enemy, false),
        RollMode::Normal
    );
    assert!(e.actors[&wiz].is_concentrating());
    // Walking clear of the sphere restores sight, which the old
    // condition-stamped model could not do. Somewhere the wizard's
    // line of sight doesn't have to cross the dark to reach.
    MoveActor {
        actor_id: enemy,
        path: vec![Coordinate::new(2, 25)],
    }
    .apply(&mut e);
    assert!(e.viewer_can_see(wiz, enemy));
    // …and dropping the caster's grip takes the dark off the board.
    e.drop_concentration(wiz);
    assert!(e.zones().is_empty());
}

#[test]
fn sahuagin_blood_frenzy_grants_advantage_on_wounded_target() {
    use crate::actors::creatures::sahuagins::SAHUAGIN_TEMPLATE;
    let mut e = ei_with_terrain(20, 20, &[]);
    let sah = e
        .instantiate_creature(&SAHUAGIN_TEMPLATE, Coordinate::new(3, 3), 0, 0)
        .unwrap();
    let enemy = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 3), 1, 0)
        .unwrap();
    // Full-HP target — no Blood Frenzy yet.
    let baseline = e.compute_attack_mode(sah, enemy, true);
    assert_eq!(
        baseline,
        crate::engine::dice::RollMode::Normal,
        "blood frenzy should NOT fire vs a full-HP target",
    );
    // Wound the enemy by chipping one HP.
    e.actors.get_mut(&enemy).unwrap().take_damage(1);
    // Now the next melee swing should land with advantage.
    let frenzy = e.compute_attack_mode(sah, enemy, true);
    assert_eq!(
        frenzy,
        crate::engine::dice::RollMode::Advantage,
        "blood frenzy should grant advantage vs a wounded target",
    );
}

#[test]
fn sahuagin_blood_frenzy_does_not_apply_to_ranged_attacks() {
    use crate::actors::creatures::sahuagins::SAHUAGIN_TEMPLATE;
    let mut e = ei_with_terrain(30, 20, &[]);
    // Far apart so the ranged "adjacent hostile = disadvantage" clause
    // can't fire and muddle the assertion.
    let sah = e
        .instantiate_creature(&SAHUAGIN_TEMPLATE, Coordinate::new(3, 3), 0, 0)
        .unwrap();
    let enemy = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(25, 3), 1, 0)
        .unwrap();
    // Wound the enemy by chipping one HP.
    e.actors.get_mut(&enemy).unwrap().take_damage(1);
    // Ranged swing: blood frenzy is melee-only per RAW.
    let mode = e.compute_attack_mode(sah, enemy, false);
    assert_eq!(
        mode,
        crate::engine::dice::RollMode::Normal,
        "blood frenzy should NOT apply to ranged attacks",
    );
}

/// Horn of Blasting: RAW's 30-foot thunder cone. It damages what the
/// wielder points it at, never the wielder (the cone's origin is not in
/// its own area), and consumes the trinket. Sweeps seeds to confirm at
/// least one fail — the Deafened rider, observed on an enemy tough
/// enough to survive the 5d6.
#[test]
fn horn_of_blasting_damages_enemies_and_deafens_on_fail() {
    use crate::actions::item_actions::BLOW_HORN_OF_BLASTING;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    use crate::items::item_template::HORN_OF_BLASTING;
    let mut saw_damage = false;
    let mut saw_deaf = false;
    for seed in 0..30u64 {
        let mut e = ei_seeded(15, 15, &[], seed);
        let user = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Ogre is tough enough (~59 HP) to survive 5d6 thunder so we
        // can observe the Deafened rider — a Goblin would die first.
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(5, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&user)
            .unwrap()
            .pickup_item(&HORN_OF_BLASTING);
        let user_hp_pre = e.actors[&user].hitpoints();
        let ogre_hp_pre = e.actors[&ogre].hitpoints();
        // Aimed at the ogre: a cone is a direction, not a centre.
        let aim = e.actors[&ogre].location();
        let aei =
            ActionExecutionInfo::new(&BLOW_HORN_OF_BLASTING, user, None, Some(vec![aim]), None);
        assert!(aei.validate(&e));
        e.push_action(aei);
        e.process_stack();
        // Horn consumed regardless of save outcomes.
        assert!(
            !e.actors[&user].has_item_named("Horn of Blasting"),
            "horn should be consumed on use"
        );
        // Wielder must never eat their own blast. Two clauses now say
        // so: the caster is excluded from the target list, and RAW's
        // cone does not include the point it comes out of.
        assert_eq!(
            e.actors[&user].hitpoints(),
            user_hp_pre,
            "Horn of Blasting must not damage its wielder"
        );
        let ogre_hp_post = e
            .actors
            .get(&ogre)
            .map(|a| a.hitpoints())
            .unwrap_or(0);
        if ogre_hp_post < ogre_hp_pre {
            saw_damage = true;
        }
        if e.actors
            .get(&ogre)
            .is_some_and(|a| a.has_condition(Condition::Deafened))
        {
            saw_deaf = true;
        }
        if saw_damage && saw_deaf {
            break;
        }
    }
    assert!(saw_damage, "horn should damage the ogre across seeds");
    assert!(saw_deaf, "horn should deafen the ogre on at least one fail");
}

