/// Guardian Coil measures its radius from the tentacle, not from
/// the warlock — the whole reason `ClampScope::NearBeacon` exists.
/// A Fathomless warlock thirty tiles away shields an ally standing
/// next to their coils, and stops shielding the moment the coils
/// die.
#[test]
fn guardian_coil_shields_whatever_stands_beside_the_tentacle() {
    use crate::actions::class_features::GUARDIAN_COIL_TAG;
    use crate::actors::creatures::deep_tentacles::TENTACLE_OF_THE_DEEP_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::warlocks::FATHOMLESS_WARLOCK_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::attack::apply_reactive_damage_clamps;
    let mut e = ei_with_terrain(60, 20, &[]);
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 5), 1, 0)
        .unwrap();
    let wizard = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(3, 5), 0, 0)
        .unwrap();
    // Forty tiles from the wizard — past every other ally-scoped
    // row in the cohort, and past anything RAW would let a warlock
    // reach with their own body.
    let warlock = e
        .instantiate_creature(&FATHOMLESS_WARLOCK_TEMPLATE, Coordinate::new(45, 5), 0, 1)
        .unwrap();
    // No tentacle yet: the coils shield nobody.
    assert_eq!(
        apply_reactive_damage_clamps(&mut e, goblin, wizard, 20, true, false, DamageType::Slashing),
        20,
        "a warlock with no tentacle on the board has no radius to shield inside"
    );
    assert!(e.actors[&warlock].feature_available(GUARDIAN_COIL_TAG));

    let tentacle = e
        .instantiate_creature(&TENTACLE_OF_THE_DEEP_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let reduced = apply_reactive_damage_clamps(&mut e, goblin, wizard, 20, true, false, DamageType::Slashing);
    assert!(
        reduced < 20,
        "the coils should clamp damage taken beside them"
    );
    assert!(
        !e.actors[&warlock].feature_available(GUARDIAN_COIL_TAG),
        "firing spends the coil charge"
    );

    // Refresh the charge and move the wizard out of the coils'
    // ten feet: the same swing passes through untouched.
    e.actors
        .get_mut(&warlock)
        .unwrap()
        .restore_feature_charge(GUARDIAN_COIL_TAG);
    e.actors
        .get_mut(&tentacle)
        .unwrap()
        .set_location(Coordinate::new(30, 15));
    assert_eq!(
        apply_reactive_damage_clamps(&mut e, goblin, wizard, 20, true, false, DamageType::Slashing),
        20,
        "the shield is a radius around the tentacle, and the wizard left it"
    );
    assert!(e.actors[&warlock].feature_available(GUARDIAN_COIL_TAG));
}

/// Psionic Strike lays +1d8 Force on the Psi Warrior's first hit of
/// the turn and no more: the shared once-per-turn ledger gates it,
/// so a template carrying the tag out-damages the baseline Fighter
/// but by a bounded amount.
#[test]
fn psionic_strike_fires_once_per_turn() {
    use crate::actions::class_features::PSIONIC_STRIKE_TAG;
    use crate::actors::creatures::fighters::PSI_WARRIOR_FIGHTER_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;
    use crate::engine::attack::{
        AttackParams, ONCE_PER_TURN_WEAPON_DIE_RIDERS, try_fire_once_per_turn_weapon_die_rider,
    };
    let spec = ONCE_PER_TURN_WEAPON_DIE_RIDERS
        .iter()
        .find(|s| s.tag == PSIONIC_STRIKE_TAG)
        .expect("psionic strike should be a row on the shared rider cohort");
    let mut e = ei_with_terrain(20, 20, &[]);
    let psi = e
        .instantiate_creature(&PSI_WARRIOR_FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let ogre = e
        .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(6, 5), 1, 0)
        .unwrap();
    let params = AttackParams {
        caster_id: psi,
        target_id: ogre,
        action_name: "scimitar",
        attack_bonus: 5,
        damage_dice: Dice::new(1, 6),
        damage_bonus: 3,
        damage_type: DamageType::Slashing,
        is_melee: true,
        long_range: None,
        min_range: None,
        is_spell: false,
    };
    let mut effects = Vec::new();
    assert!(
        try_fire_once_per_turn_weapon_die_rider(&mut e, &mut effects, &params, false, spec),
        "the first hit of the turn carries the strike"
    );
    assert_eq!(effects.len(), 1, "one Force payload queued");
    assert!(
        !try_fire_once_per_turn_weapon_die_rider(&mut e, &mut effects, &params, false, spec),
        "the second hit of the same turn does not"
    );
    assert_eq!(effects.len(), 1);
    // Turn-start clears the shared ledger, re-arming the rider.
    let _ = e.actors.get_mut(&psi).unwrap().reset_for_new_round();
    assert!(try_fire_once_per_turn_weapon_die_rider(
        &mut e,
        &mut effects,
        &params,
        false,
        spec
    ));
}

/// Eldritch Knight template drift pin. The subclass adds three tags,
/// five spells, one bonus action, a slot table and an INT bump — and
/// must still inherit the whole baseline Fighter kit through the
/// `..FIGHTER_TEMPLATE.clone()` tail. Any of those going missing is
/// a silent regression, since the missing half only shows up as
/// "the knight is weaker than expected" in play.
#[test]
fn eldritch_knight_ships_its_kit_and_inherits_the_fighter_chassis() {
    use crate::actions::class_features::{
        ACTION_SURGE_TAG, ELDRITCH_STRIKE_TAG, INDOMITABLE_TAG, PARRY_TAG, RIPOSTE_TAG,
        SECOND_WIND_TAG, TRIP_ATTACK_TAG, WAR_MAGIC_TAG, WEAPON_BOND_TAG,
    };
    use crate::actors::creatures::fighters::{
        ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
    };
    let mut e = ei_with_terrain(15, 15, &[]);
    let knight = e
        .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // The three subclass tells.
    for tag in [WEAPON_BOND_TAG, WAR_MAGIC_TAG, ELDRITCH_STRIKE_TAG] {
        assert!(
            e.actors[&knight].has_passive_feature(tag),
            "Eldritch Knight should carry its own subclass tag {}",
            tag
        );
    }
    // Baseline chassis, inherited wholesale.
    for tag in [
        SECOND_WIND_TAG,
        ACTION_SURGE_TAG,
        INDOMITABLE_TAG,
        PARRY_TAG,
        RIPOSTE_TAG,
        TRIP_ATTACK_TAG,
    ] {
        assert!(
            e.actors[&knight].has_passive_feature(tag),
            "Eldritch Knight should inherit baseline Fighter tag {}",
            tag
        );
    }
    assert!(e.actors[&knight].has_extra_attack());
    // The spell kit, plus the bonus action that cashes War Magic.
    for name in [
        "fire bolt",
        "booming blade",
        "shield",
        "magic missile",
        "misty step",
        "war magic",
    ] {
        assert!(
            e.actors[&knight].find_action(name).is_some(),
            "Eldritch Knight should carry the {} action",
            name
        );
    }
    // Third-caster slot table and the INT bump that anchors the DC —
    // both distinguish this template from the baseline, which has
    // neither.
    assert_eq!(
        ELDRITCH_KNIGHT_FIGHTER_TEMPLATE.spell_slots_by_level,
        vec![4, 3],
        "third-caster progression"
    );
    assert!(
        ELDRITCH_KNIGHT_FIGHTER_TEMPLATE.intelligence
            > FIGHTER_TEMPLATE.intelligence,
        "the knight's INT rises above the baseline fighter's to anchor the spell DC"
    );
    assert!(
        FIGHTER_TEMPLATE.spell_slots_by_level.is_empty(),
        "the baseline fighter stays slotless"
    );
}

/// Eldritch Strike stamps the mark plus its back-link on any
/// connecting weapon hit. Driven over a seed sweep so at least one
/// swing lands; a knight without the tag never stamps.
#[test]
fn eldritch_strike_marks_the_target_on_a_weapon_hit() {
    use crate::actors::creatures::fighters::{
        ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
    };
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::attack::{AttackParams, resolve_attack_outcome};

    // (hits, marks) — a nat 1 auto-misses, so the sweep can't assume
    // every swing connects; what's under test is that the mark
    // tracks hits exactly.
    let run = |template: &'static CreatureTemplate| -> (usize, usize) {
        let (mut hits, mut marked) = (0usize, 0usize);
        for seed in 0..40u64 {
            let mut e = ei_with_terrain(15, 15, &[]);
            e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
            let knight = e
                .instantiate_creature(template, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                .unwrap();
            let (effects, dealt) = resolve_attack_outcome(
                &mut e,
                AttackParams {
                    caster_id: knight,
                    target_id: target,
                    action_name: "scimitar",
                    attack_bonus: 20, // force the hit; the mark is what's under test
                    damage_dice: Dice::new(1, 6),
                    damage_bonus: 3,
                    damage_type: DamageType::Slashing,
                    is_melee: true,
                    long_range: None,
                    min_range: None,
                    is_spell: false,
                },
            );
            if dealt > 0 {
                hits += 1;
            }
            for ef in effects {
                ef.apply(&mut e);
            }
            if e.actors[&target].has_condition(Condition::EldritchStruck) {
                assert_eq!(
                    e.actors[&target].linked_by(Condition::EldritchStruck),
                    Some(knight),
                    "the mark carries the striking knight's id"
                );
                marked += 1;
            }
        }
        (hits, marked)
    };
    let (knight_hits, knight_marks) = run(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE);
    assert!(knight_hits > 0, "attack_bonus 20 should connect most swings");
    assert_eq!(
        knight_marks, knight_hits,
        "every connecting swing stamps the mark, and only a connecting one"
    );
    let (plain_hits, plain_marks) = run(&FIGHTER_TEMPLATE);
    assert!(plain_hits > 0, "control arm should also be landing swings");
    assert_eq!(
        plain_marks, 0,
        "a fighter without the tag never stamps the mark"
    );
}

/// The mark is caster-specific. A save against a *different*
/// caster's spell reads clean and leaves the mark standing; the save
/// against the knight who placed it consumes the mark and clears the
/// back-link with it.
#[test]
fn eldritch_strike_bends_only_the_marking_knights_spell_save() {
    use crate::actors::creatures::fighters::ELDRITCH_KNIGHT_FIGHTER_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::{Condition, ConditionTimer};
    use crate::engine::side_effects::{ApplicableSideEffect, SetConditionLink};
    use crate::engine::types::AbilityScoreType;

    let mut e = ei_with_terrain(15, 15, &[]);
    let knight = e
        .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let wizard = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(3, 2), 0, 1)
        .unwrap();
    let target = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
        .unwrap();
    e.actors
        .get_mut(&target)
        .unwrap()
        .add_condition(Condition::EldritchStruck, ConditionTimer::Rounds(2));
    SetConditionLink {
        target_id: target,
        condition: Condition::EldritchStruck,
        source: Some(knight),
    }
    .apply(&mut e);

    // The team's wizard casting at the same target gets nothing —
    // the mark belongs to the knight who swung.
    let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, wizard);
    assert!(
        e.actors[&target].has_condition(Condition::EldritchStruck),
        "another caster's spell neither fires nor consumes the mark"
    );

    // The knight's own spell cashes it, once.
    let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, knight);
    assert!(
        !e.actors[&target].has_condition(Condition::EldritchStruck),
        "the marking knight's spell consumes the mark"
    );
    assert_eq!(
        e.actors[&target].linked_by(Condition::EldritchStruck),
        None,
        "removing the condition clears the back-link"
    );
}

/// War Magic's prime is cantrip-only: `spell_level == 0` arms it,
/// any levelled cast leaves it alone, and a fighter without the tag
/// never arms it at all.
#[test]
fn war_magic_primes_on_cantrips_only() {
    use crate::actors::creatures::fighters::{
        ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
    };
    use crate::conditions::Condition;

    let mut e = ei_with_terrain(15, 15, &[]);
    let knight = e
        .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let plain = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 2), 0, 1)
        .unwrap();

    // A levelled cast is not a cantrip.
    let _ = e.dispatch_post_cast_triggers(knight, 2, &[], Some(SpellSchool::Evocation), None);
    assert!(
        !e.actors[&knight].has_condition(Condition::WarMagicPrimed),
        "a levelled spell doesn't arm War Magic"
    );
    // Neither is a non-spell action: `Action::execute` opens a
    // level-0 cast frame for every action it runs, and only the
    // school tag separates a Fire Bolt from a scimitar swing. A
    // knight who could arm the prime by swinging would get the
    // War Magic follow-up for free.
    let _ = e.dispatch_post_cast_triggers(knight, 0, &[], None, None);
    assert!(
        !e.actors[&knight].has_condition(Condition::WarMagicPrimed),
        "an untagged level-0 action is a weapon swing, not a cantrip"
    );
    // A cantrip is.
    let _ = e.dispatch_post_cast_triggers(knight, 0, &[], Some(SpellSchool::Evocation), None);
    assert!(
        e.actors[&knight].has_condition(Condition::WarMagicPrimed),
        "a cantrip arms War Magic"
    );
    // No tag, no prime.
    let _ = e.dispatch_post_cast_triggers(plain, 0, &[], Some(SpellSchool::Evocation), None);
    assert!(
        !e.actors[&plain].has_condition(Condition::WarMagicPrimed),
        "a fighter without the tag never arms War Magic"
    );
}

/// The War Magic bonus action is gated on the prime, hands back an
/// Action token, and burns the prime so it can't be cashed twice.
#[test]
fn war_magic_strike_trades_the_prime_for_an_action() {
    use crate::actions::class_features::WAR_MAGIC_STRIKE;
    use crate::actors::creatures::fighters::ELDRITCH_KNIGHT_FIGHTER_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let knight = e
        .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Unprimed: the bonus action isn't available at all.
    assert!(
        !WAR_MAGIC_STRIKE.validate_input(&e, knight, None, None, None),
        "War Magic needs a cantrip cast first"
    );

    let _ = e.dispatch_post_cast_triggers(knight, 0, &[], Some(SpellSchool::Evocation), None);
    let actor = e.actors.get_mut(&knight).unwrap();
    actor.give_resource(Resource::BonusAction);
    // Spend the Action the (notional) cantrip cost so the grant is
    // observable rather than masked by an unspent token.
    actor.consume_resource(Resource::Action);
    assert!(!e.actors[&knight].can_consume_resource(Resource::Action));

    assert!(WAR_MAGIC_STRIKE.validate_input(&e, knight, None, None, None));
    let effects = WAR_MAGIC_STRIKE.execute(&mut e, knight, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&knight].can_consume_resource(Resource::Action),
        "War Magic hands back an Action for the follow-up swing"
    );
    assert!(
        !e.actors[&knight].has_condition(Condition::WarMagicPrimed),
        "the prime is one-shot"
    );
    assert!(
        !WAR_MAGIC_STRIKE.validate_input(&e, knight, None, None, None),
        "and can't be cashed a second time"
    );
}

/// Every actor the engine prompts has had `start_turn_for` run for
/// them first. That is the invariant `ensure_turn_started` exists to
/// hold, and it used to have two holes.
///
/// **Hole one — the first actor of the encounter.** `initialize`
/// leaves the initiative slot at index 0 and nothing calls
/// `start_turn_for`; the only two production callers both sat
/// *after* an `advance_initiative`. So the actor who won initiative
/// was prompted without their turn ever starting — no
/// `mark_taken_turn_in_combat` (an Assassin got Assassinate
/// advantage against them all round, after they had already acted),
/// no `UntilStartOfNextTurn` expiry, no recharge roll.
///
/// **Hole two — an actor who dies on their own turn.**
/// `InitiativeTracker::remove_actor` deliberately lets the next
/// actor slide into the vacated index, on the documented assumption
/// that the caller won't advance. But the actor who slid in is then
/// prompted through the same no-advance path, so they too were
/// prompted with no turn start — inheriting whatever resources they
/// had left from their *previous* turn. Reachable through every
/// damage-reflect lane (Fire Shield, Armor of Agathys, a
/// salamander's Heated Body) and through Hellish Rebuke.
///
/// This pins the first hole directly, which is the one that needs no
/// setup: initiative order is seed-dependent, so the test asserts
/// against whoever won rather than a fixed id.
#[test]
fn the_first_actor_prompted_has_had_their_turn_started() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::skeletons::SKELETON_TEMPLATE;

    // `ei_with_terrain` builds an already-initialized encounter, so
    // spawn into it and let `instantiate_creature` wire the queue.
    let mut e = ei_with_terrain(15, 15, &[]);
    let a = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let b = e
        .instantiate_creature(&SKELETON_TEMPLATE, Coordinate::new(8, 8), 1, 0)
        .unwrap();
    for id in [a, b] {
        assert!(
            !e.actors[&id].has_taken_turn_in_combat(),
            "latch starts clear"
        );
    }
    e.process_stack();
    let prompted = e.peek_prompt().map(|p| p.actor_id()).expect("a prompt");
    assert!(
        e.actors[&prompted].has_taken_turn_in_combat(),
        "the actor being prompted has had their turn started"
    );
    // And the one who hasn't been prompted still hasn't — the latch
    // is per-actor, not a blanket flip.
    let other = if prompted == a { b } else { a };
    assert!(
        !e.actors[&other].has_taken_turn_in_combat(),
        "an actor whose slot hasn't come up is untouched"
    );
}

/// 5e Oath of the Crown Paladin **Divine Allegiance**: the damage
/// lands on the paladin and not at all on the ally it was aimed at.
///
/// Driven through `DealDamage` rather than through an attack,
/// because that is the point of the lane. Interception and Warding
/// Maneuver hang off the attack chokepoints and cannot see a failed
/// save, a round-end drip or a death burst; this hangs off the
/// damage itself and catches all of them.
#[test]
fn divine_allegiance_moves_the_damage_onto_the_paladin() {
    use crate::actors::creatures::paladins::CROWN_PALADIN_TEMPLATE;
    use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
    use crate::engine::side_effects::DealDamage;

    let mut e = ei_with_terrain(15, 15, &[]);
    let paladin = e
        .instantiate_creature(&CROWN_PALADIN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(6, 5), 0, 0)
        .unwrap();
    let ally_before = e.actors[&ally].hitpoints();
    let paladin_before = e.actors[&paladin].hitpoints();

    DealDamage {
        actor_id: ally,
        amount: 9,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);

    assert_eq!(
        e.actors[&ally].hitpoints(),
        ally_before,
        "the blow never reaches the creature it was aimed at"
    );
    assert_eq!(
        paladin_before - e.actors[&paladin].hitpoints(),
        9,
        "and arrives whole on the paladin"
    );
    assert!(
        !e.actors[&paladin].has_reaction(),
        "carrying it costs the reaction"
    );

    // Reaction spent: the next blow lands where it was aimed.
    DealDamage {
        actor_id: ally,
        amount: 4,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    assert_eq!(
        ally_before - e.actors[&ally].hitpoints(),
        4,
        "with no reaction left the paladin cannot step in again"
    );
}

/// Two Crown Paladins standing beside each other don't volley the
/// same blow between them.
///
/// Nothing in RAW forbids the chain — each paladin is separately
/// entitled to take damage a neighbour is taking — but the result is
/// a single hit bouncing until both reactions are gone, which is not
/// what either of them meant. `within_damage_redirect` refuses to
/// hand on damage that is already being carried, so exactly one
/// paladin pays and exactly one reaction is spent.
#[test]
fn a_carried_blow_is_not_handed_on_again() {
    use crate::actors::creatures::paladins::CROWN_PALADIN_TEMPLATE;
    use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
    use crate::engine::side_effects::DealDamage;

    let mut e = ei_with_terrain(15, 15, &[]);
    let first = e
        .instantiate_creature(&CROWN_PALADIN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let second = e
        .instantiate_creature(&CROWN_PALADIN_TEMPLATE, Coordinate::new(6, 5), 0, 1)
        .unwrap();
    let ally = e
        .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(6, 6), 0, 0)
        .unwrap();
    let before: Vec<u32> = [first, second, ally]
        .iter()
        .map(|id| e.actors[id].hitpoints())
        .collect();

    DealDamage {
        actor_id: ally,
        amount: 7,
        damage_type: DamageType::Force,
    }
    .apply(&mut e);

    let after: Vec<u32> = [first, second, ally]
        .iter()
        .map(|id| e.actors[id].hitpoints())
        .collect();
    let losses: Vec<u32> = before.iter().zip(&after).map(|(b, a)| b - a).collect();
    assert_eq!(
        losses.iter().sum::<u32>(),
        7,
        "the blow is paid once, not once per paladin: {:?}",
        losses
    );
    assert_eq!(
        losses.iter().filter(|l| **l > 0).count(),
        1,
        "exactly one creature pays it: {:?}",
        losses
    );
    let reactions_spent = [first, second]
        .iter()
        .filter(|id| !e.actors[id].has_reaction())
        .count();
    assert_eq!(reactions_spent, 1, "and exactly one reaction is spent");
}

/// A paladin doesn't step in front of an enemy, and doesn't burn a
/// reaction on damage that was going to be zero anyway.
#[test]
fn divine_allegiance_only_covers_allies_and_only_for_real_damage() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::CROWN_PALADIN_TEMPLATE;
    use crate::engine::side_effects::DealDamage;

    let mut e = ei_with_terrain(15, 15, &[]);
    let paladin = e
        .instantiate_creature(&CROWN_PALADIN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let enemy = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
        .unwrap();
    let enemy_before = e.actors[&enemy].hitpoints();

    DealDamage {
        actor_id: enemy,
        amount: 3,
        damage_type: DamageType::Slashing,
    }
    .apply(&mut e);
    assert_eq!(
        enemy_before - e.actors[&enemy].hitpoints(),
        3,
        "an enemy carries their own damage"
    );
    assert!(
        e.actors[&paladin].has_reaction(),
        "and the paladin's reaction is untouched"
    );

    // A zero-damage instance is not worth a reaction.
    let ally = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 5), 0, 1)
        .unwrap();
    DealDamage {
        actor_id: ally,
        amount: 0,
        damage_type: DamageType::Slashing,
    }
    .apply(&mut e);
    assert!(
        e.actors[&paladin].has_reaction(),
        "nothing to take means nothing to spend"
    );
}

/// The lineage builds are reachable from both registries.
///
/// All twenty-one — fifteen dragonborn ancestries and six
/// single-lineage builds — were fully implemented, carried racial
/// traits nothing else on the roster has, and could be reached by
/// nothing but a unit test: they were in neither
/// `pc_template_families` (so no player could pick one) nor
/// `template_pool` (so no encounter could roll one). This pins both
/// halves of that fix.
///
/// The asymmetry is deliberate and is the second thing pinned here:
/// every ancestry is playable, but only one dragonborn is in the
/// bestiary. The fifteen differ solely in their breath weapon's
/// damage type, so putting them all in the pool would tilt the
/// generator a sixth of the way towards "a dragonborn, again" and
/// buy no variety for it.
#[test]
fn the_lineage_builds_are_playable_and_in_the_bestiary() {
    use crate::actors::creatures::pc_template_families;

    let playable: std::collections::HashSet<&str> = pc_template_families()
        .into_iter()
        .flat_map(|(_family, templates)| templates)
        .map(|t| t.name)
        .collect();
    let bestiary: std::collections::HashSet<&str> = EncounterInstance::template_pool()
        .into_iter()
        .map(|t| t.name)
        .collect();

    // Both registries, for the builds that carry a racial trait no
    // other template sources: Hellish Rebuke, Healing Hands, Dwarven
    // Resilience, Halfling Luck, Relentless Endurance, Gnome
    // Cunning, and the breath weapon.
    for name in [
        "Tiefling",
        "Aasimar",
        "Mountain Dwarf Defender",
        "Halfling Scout",
        "Half-Orc Marauder",
        "Rock Gnome Illusionist",
        "Red Dragonborn Champion",
    ] {
        assert!(playable.contains(name), "{} is not playable", name);
        assert!(bestiary.contains(name), "{} cannot be rolled", name);
    }

    // The other fourteen ancestries: playable, and deliberately not
    // in the bestiary.
    for name in [
        "Black Dragonborn Champion",
        "Gold Dragonborn Champion",
        "Amethyst Dragonborn Champion",
    ] {
        assert!(playable.contains(name), "{} is not playable", name);
        assert!(
            !bestiary.contains(name),
            "{} should stay out of the generator — see the doc above",
            name
        );
    }
}

/// Every encounter reports a seed, and replaying that seed
/// reproduces it — including the encounters nobody named a seed for.
///
/// That second half is the point. An unseeded run used to take its
/// dice from a thread-local RNG whose starting state was discarded
/// on first use, so the one encounter anyone wants to reproduce, the
/// one they just played, was exactly the one that couldn't be.
///
/// Sameness is checked against the generated actor roster and the
/// terrain rather than against the seed field alone: the field
/// matching proves only that a number was stored, where the roster
/// proves the number was the one both RNGs were actually built from.
#[test]
fn an_unseeded_encounter_still_reports_a_seed_that_replays_it() {
    let tp = TerrainGenParams {
        width: 24,
        height: 16,
        branch_depth: 4,
        branch_prob: 0.5,
    };
    let ap = ActorGenParams {
        cr_target: 2.0,
        n_teams: 2,
        pc_template: None,
        start_team: 0,
    };

    let fingerprint = |e: &EncounterInstance| {
        let mut roster: Vec<(usize, String, u32, isize, isize)> = e
            .actors
            .iter()
            .map(|(id, a)| {
                let loc = a.location();
                (*id, a.name().to_string(), a.max_hitpoints(), loc.x, loc.y)
            })
            .collect();
        roster.sort();
        let walls: Vec<bool> = e
            .terrain
            .iter()
            .map(|t| t.terrain_type == TerrainType::Wall)
            .collect();
        (roster, walls)
    };

    let unseeded = EncounterInstance::from_params(&tp, &ap, None).unwrap();
    let replay =
        EncounterInstance::from_params(&tp, &ap, Some(unseeded.seed())).unwrap();
    assert_eq!(
        fingerprint(&unseeded),
        fingerprint(&replay),
        "seed {} did not reproduce the encounter it came from",
        unseeded.seed()
    );

    // And an explicitly seeded encounter reports back what it was
    // given, rather than a fresh draw that happens to be stored.
    let explicit = EncounterInstance::from_params(&tp, &ap, Some(99)).unwrap();
    assert_eq!(explicit.seed(), 99);
}

/// 5e Sun Soul Monk **Searing Sunburst** zeroes on a successful save
/// rather than halving.
///
/// The distinction is invisible on any single roll — a failed save
/// looks the same under either policy — so the test sweeps seeds and
/// checks the *shape* of the outcomes: every hit is either the full
/// shared roll or nothing at all, and both show up. A regression to
/// `HalfOnSave` fails on the first seed where the save lands, which
/// across twenty-four seeds is not a coin flip.
///
/// The rolled total is read back off the burst's own log line, which
/// is the only place the shared roll is published — and pinning it
/// this way means the log stays honest too.
#[test]
fn searing_sunburst_deals_nothing_on_a_successful_save() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::SEARING_SUNBURST;
    use crate::actors::creatures::monks::SUN_SOUL_MONK_TEMPLATE;
    use crate::actors::creatures::ogres::OGRE_TEMPLATE;

    let mut zeroed = 0;
    let mut fully_hit = 0;
    for seed in 0..24u64 {
        let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
        let monk = e
            .instantiate_creature(&SUN_SOUL_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // An ogre rather than a goblin: 2d6 can exceed a goblin's
        // whole HP bar, and a target that drops to 0 reports a
        // smaller delta than it actually took, which would read as
        // a third outcome the policy doesn't have.
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(10, 10), 1, 0)
            .unwrap();
        let before = e.actors[&ogre].hitpoints();
        let log_len = e.messages().len();

        let action: &dyn Action = &*SEARING_SUNBURST;
        let center = vec![Coordinate::new(10, 10)];
        for eff in action.side_effects(&mut e, monk, None, Some(&center), None) {
            eff.apply(&mut e);
        }

        // "  searing sunburst: 2d6(N) radiant, ..." — N is the
        // shared roll every target in the burst is measured against.
        let rolled: u32 = e.messages()[log_len..]
            .iter()
            .find_map(|m| {
                let tail = m.split("2d6(").nth(1)?;
                tail.split(')').next()?.parse().ok()
            })
            .expect("the burst logs its shared roll");
        assert!(rolled >= 2, "2d6 cannot roll below 2");

        let taken = before - e.actors[&ogre].hitpoints();
        assert!(
            taken == 0 || taken == rolled,
            "seed {}: took {} against a shared roll of {} — \
             save-for-nothing admits only those two",
            seed,
            taken,
            rolled
        );
        if taken == 0 {
            zeroed += 1;
        } else {
            fully_hit += 1;
        }
    }
    assert!(
        zeroed > 0,
        "no seed in 24 passed the save — the fixture isn't exercising the policy"
    );
    assert!(fully_hit > 0, "no seed in 24 failed the save");
}

/// 5e Thief Rogue **Thief's Reflexes**: two turns in round 1, one
/// per round after that.
///
/// Driven by walking the whole queue twice and counting how often
/// each id comes up. Round 1 should name the Thief twice and the
/// goblin once; round 2 should name each of them once. Counting is
/// the assertion rather than checking a flag because the feature's
/// whole claim is about *how many turns happen* — a version that
/// handed out a spare Action instead would pass a flag check and
/// fail this one.
#[test]
fn thiefs_reflexes_grants_a_second_turn_only_in_round_one() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::rogues::THIEF_ROGUE_TEMPLATE;

    let mut e = ei_with_terrain(15, 15, &[]);
    let thief = e
        .instantiate_creature(&THIEF_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
        .unwrap();

    let round_one: Vec<usize> = e.initiative_slots().iter().map(|s| s.actor_id).collect();
    assert_eq!(
        round_one.iter().filter(|&&id| id == thief).count(),
        2,
        "the Thief holds two slots in round 1: {:?}",
        round_one
    );
    assert_eq!(
        round_one.iter().filter(|&&id| id == goblin).count(),
        1,
        "nobody else gains a slot"
    );
    // The extra slot sits *below* the Thief's own — RAW's "your second
    // turn at your initiative minus 10" — and it is the one flagged as
    // extra, which is what the panel reads to explain a name appearing
    // twice.
    //
    // What is deliberately *not* asserted is that somebody else acts in
    // between. That reads like the point of the ten-point drop and is
    // not an invariant: whether an enemy's roll lands inside the window
    // is a fact about their initiative, and a goblin that rolls under
    // the Thief's second slot leaves the two adjacent with nothing
    // wrong. The old assertion said otherwise and held only while the
    // goblin's dice happened to cooperate.
    let first = round_one.iter().position(|&id| id == thief).unwrap();
    let second = round_one.iter().rposition(|&id| id == thief).unwrap();
    assert!(second > first, "the extra turn comes after the rolled one");
    let slots = e.initiative_slots();
    assert!(!slots[first].is_extra, "the first slot is the rolled one");
    assert!(slots[second].is_extra, "the second is the granted one");

    // Walk out of round 1. `skip_turn` advances one slot at a time,
    // so the queue length is exactly the number of steps to a wrap.
    assert_eq!(e.round(), 1);
    for _ in 0..round_one.len() {
        e.skip_turn();
    }
    assert_eq!(e.round(), 2, "one full pass is one round");

    let round_two: Vec<usize> = e.initiative_slots().iter().map(|s| s.actor_id).collect();
    assert_eq!(
        round_two.iter().filter(|&&id| id == thief).count(),
        1,
        "the extra slot retires with round 1: {:?}",
        round_two
    );
    assert_eq!(round_two.len(), 2, "and nothing else changed shape");
}

/// A Thief who dies during round 1 takes their extra slot with them.
///
/// The queue is keyed by position and the Thief owns two of them, so
/// a removal that stopped at the first match would leave a corpse
/// holding a turn — `start_turn_for` would find no actor, and the
/// slot would sit in the order forever. `remove_actor` sweeps every
/// slot an actor owns, which is what this pins.
#[test]
fn a_dead_thief_keeps_neither_of_their_slots() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::rogues::THIEF_ROGUE_TEMPLATE;

    let mut e = ei_with_terrain(15, 15, &[]);
    let thief = e
        .instantiate_creature(&THIEF_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
        .unwrap();
    assert_eq!(
        e.initiative_slots()
            .iter()
            .filter(|s| s.actor_id == thief)
            .count(),
        2
    );

    e.remove_actor(thief);
    let left: Vec<usize> = e.initiative_slots().iter().map(|s| s.actor_id).collect();
    assert!(
        !left.contains(&thief),
        "no slot survives the actor: {:?}",
        left
    );
}

/// 5e Thief Rogue **Fast Hands**: a potion costs the Thief their
/// bonus action while they still have one, and their Action once
/// they don't.
///
/// The fallback half is the interesting one. `cost()` hands back a
/// list of resources that must *all* be paid, so a static swap to
/// "bonus action" would have silently taken the Action price away —
/// a Thief who had already spent their bonus action on Cunning Dash
/// would find the potion unusable, which is strictly worse than the
/// baseline rogue and the opposite of what the feature says.
#[test]
fn fast_hands_prices_a_potion_against_what_the_thief_has_left() {
    use crate::actions::item_actions::DRINK_HEALING_POTION;
    use crate::actors::creatures::rogues::{ROGUE_TEMPLATE, THIEF_ROGUE_TEMPLATE};
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let thief = e
        .instantiate_creature(&THIEF_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let plain = e
        .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();

    let price = |e: &EncounterInstance, id: usize| {
        DRINK_HEALING_POTION.cost(e, id, None, None, None)
    };
    assert_eq!(
        price(&e, thief),
        vec![Resource::BonusAction],
        "Fast Hands moves the potion onto the bonus action"
    );
    assert_eq!(
        price(&e, plain),
        vec![Resource::Action],
        "and leaves every other rogue paying an Action"
    );

    // Spend the bonus action; the price falls back rather than
    // becoming unpayable.
    e.actors
        .get_mut(&thief)
        .unwrap()
        .consume_resource(Resource::BonusAction);
    assert_eq!(
        price(&e, thief),
        vec![Resource::Action],
        "with no bonus action left, the Action price comes back"
    );
}

/// Conditions that bar casting bar *cantrips* too. The only gate for
/// this used to live on the `SpellSlot` resource lane, which
/// cantrips never touch — so a Silenced caster could Fire Bolt out
/// of a zone of magical silence, and a wild-shaped druid (a bear)
/// could cast Poison Spray. Both conditions' RAW text is
/// unqualified.
///
/// Driven from both sides of the split so the fix can't regress by
/// half: a levelled spell (Fireball, which the old resource gate
/// already caught) and a cantrip (Fire Bolt, which it didn't).
#[test]
fn silence_and_wild_shape_block_cantrips_not_just_slots() {
    use crate::actions::spells::{FIRE_BOLT, FIREBALL};
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::{Condition, ConditionTimer};

    for blocker in [Condition::Silenced, Condition::WildShaped] {
        let mut e = ei_with_terrain(20, 20, &[]);
        let caster = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(6, 2), 1, 0)
            .unwrap();
        let ids = vec![target];
        let point = vec![Coordinate::new(6, 2)];
        // Baseline: both casts are legal.
        assert!(
            FIRE_BOLT.validate_input(&e, caster, Some(&ids), None, None),
            "{:?}: cantrip legal before the block",
            blocker
        );
        assert!(
            FIREBALL.validate_input(&e, caster, None, Some(&point), None),
            "{:?}: levelled spell legal before the block",
            blocker
        );

        e.actors
            .get_mut(&caster)
            .unwrap()
            .add_condition(blocker, ConditionTimer::Rounds(5));

        assert!(
            !FIREBALL.validate_input(&e, caster, None, Some(&point), None),
            "{:?} should block a levelled spell",
            blocker
        );
        assert!(
            !FIRE_BOLT.validate_input(&e, caster, Some(&ids), None, None),
            "{:?} should block a cantrip too",
            blocker
        );
        // Non-spell actions are untouched — the gate keys off
        // `school()`, not off being an action.
        assert!(
            e.actors[&caster].find_action("dodge").is_some_and(|a| a
                .validate_input(&e, caster, None, None, None)),
            "{:?} shouldn't stop the caster from Dodging",
            blocker
        );
    }
}

/// A per-target Help grant reaches *weapon* attacks, not just spell
/// attacks.
///
/// The engine has two advantage-from-help lanes: the `Helped`
/// condition, read by `compute_attack_mode`, and the per-target
/// `HelpGrant` ledger, read only by `attack_mode_with_riders`.
/// `spell_attack_outcome` called the latter; `resolve_attack_outcome`
/// called `compute_attack_mode` directly and then cleared the
/// one-shot rider stack — which *consumes* the grant. So a grant
/// installed without the condition was silently eaten by the next
/// weapon swing without ever granting advantage.
///
/// Three shipped features install only the grant: the Battle
/// Master's Feinting Attack, Commander's Strike (on the ordered
/// ally), and the Arcane Trickster's Versatile Trickster. All three
/// exist to make a *weapon* swing land, so all three did nothing on
/// the lane they were written for. The `Help` action itself was
/// unaffected because it installs both.
///
/// Driven through `resolve_attack_outcome` on the log line, which is
/// where the mode is rendered, over both polarities: with the grant
/// naming this target, and with it naming somebody else.
#[test]
fn a_help_grant_grants_advantage_on_a_weapon_swing() {
    use crate::actors::actor_template::HelpGrant;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::engine::attack::{AttackParams, resolve_attack_outcome};

    let swing = |grant_against: Option<usize>| -> bool {
        let mut e = ei_with_terrain(15, 15, &[]);
        let fighter = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        let decoy = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(9, 9), 1, 1)
            .unwrap();
        let against = grant_against.map(|_| decoy).unwrap_or(target);
        // `None` means "grant names the real target"; `Some` means
        // "grant names the decoy" — read that way so the closure
        // takes one flag rather than an id the caller can't know yet.
        let named = if grant_against.is_some() {
            against
        } else {
            target
        };
        e.actors
            .get_mut(&fighter)
            .unwrap()
            .set_help_grant(Some(HelpGrant {
                helper_id: fighter,
                against: named,
            }));
        let before = e.messages().len();
        let _ = resolve_attack_outcome(
            &mut e,
            AttackParams {
                caster_id: fighter,
                target_id: target,
                action_name: "scimitar",
                attack_bonus: 5,
                damage_dice: Dice::new(1, 6),
                damage_bonus: 3,
                damage_type: DamageType::Slashing,
                is_melee: true,
                long_range: None,
                min_range: None,
                is_spell: false,
            },
        );
        e.messages()[before..]
            .iter()
            .any(|m| m.contains("scimitar") && m.contains("(adv)"))
    };
    assert!(
        swing(None),
        "a grant naming this target should read as advantage on the swing"
    );
    assert!(
        !swing(Some(0)),
        "a grant naming somebody else should not"
    );
}

/// `peek_attack_mode` sees the per-target Help grant and leaves it
/// standing; `attack_mode_with_riders` sees it and spends it.
///
/// The pair matters because the AI's target ranking only has
/// `&EncounterInstance` and so used to call `compute_attack_mode` —
/// the only read-only option — which doesn't read the grant at all.
/// A fighter who spent a bonus action feinting then ranked that
/// target no higher than any other.
#[test]
fn peeking_the_attack_mode_reads_the_help_grant_without_spending_it() {
    use crate::actors::actor_template::HelpGrant;
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;

    let mut e = ei_with_terrain(15, 15, &[]);
    let fighter = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let target = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    let other = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(9, 9), 1, 1)
        .unwrap();
    e.actors
        .get_mut(&fighter)
        .unwrap()
        .set_help_grant(Some(HelpGrant {
            helper_id: fighter,
            against: target,
        }));

    assert_eq!(
        e.peek_attack_mode(fighter, target, true),
        RollMode::Advantage,
        "the grant is visible to a read-only peek"
    );
    assert_eq!(
        e.peek_attack_mode(fighter, other, true),
        RollMode::Normal,
        "and only against the target it names"
    );
    // Peeking twice still reads Advantage — nothing was spent.
    assert_eq!(
        e.peek_attack_mode(fighter, target, true),
        RollMode::Advantage,
        "peeking is idempotent"
    );

    // The mutating twin spends it.
    assert_eq!(
        e.attack_mode_with_riders(fighter, target, true),
        RollMode::Advantage
    );
    assert_eq!(
        e.peek_attack_mode(fighter, target, true),
        RollMode::Normal,
        "the swing consumed the grant"
    );
}

/// Typing a spell's own name casts *that* spell, even when another
/// action on the same sheet claims the name as an alias.
///
/// The wizard is the live case: Maddening Darkness (level 8) is
/// pushed onto the action list before Darkness (level 2) and aliases
/// "darkness". Under the old single-pass search — which tested
/// canonical name and alias in one `find`, and so resolved by
/// action-list order — typing `darkness` burned the wizard's only
/// 8th-level slot on the wrong spell, with nothing in the log to say
/// so. `every_pc_action_is_reachable_by_its_canonical_name` sweeps
/// the invariant across every class; this is the one case driven
/// end-to-end through the parser.
#[test]
fn typing_a_spell_name_beats_another_actions_alias() {
    use crate::actions::spells::{DARKNESS, MADDENING_DARKNESS};
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::prompt::Prompt;

    let mut e = ei_with_terrain(20, 20, &[]);
    let wiz = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 4), 0, 0)
        .unwrap();
    // The collision, in the order `WIZARD_TEMPLATE` builds it.
    let prompt = Prompt::new(wiz, vec![&*MADDENING_DARKNESS, &*DARKNESS]);
    let resolved = prompt
        .process_input("darkness 8,4", &e)
        .expect("darkness should parse and validate for a wizard");
    assert_eq!(
        resolved.action().name(),
        "darkness",
        "the canonical name wins over another action's alias"
    );
    // And the alias still resolves when nothing shadows it.
    let by_alias = prompt
        .process_input("maddening 8,4", &e)
        .expect("maddening should parse and validate");
    assert_eq!(by_alias.action().name(), "maddening darkness");
}

/// A fight in which nothing happens is over, even when everybody can
/// reach everybody.
///
/// The positional half of `is_stalemate` cannot see this one: the two
/// combatants are standing next to each other, so `can_engage` is
/// true in both directions and the reachability walk correctly says
/// the fight is live. It is live. It is also never going to end, and
/// the only thing that separates the two is time.
///
/// Two goblins that never swing are the honest minimum of the case
/// that found this — a Yeti that could hit a Shield Guardian but not
/// out-damage its regeneration, which is the same fight with more
/// dice in it.
#[test]
fn a_fight_where_nobody_lands_anything_is_eventually_called_a_draw() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

    let mut e = ei_with_terrain(20, 20, &[]);
    let a = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    let b = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 1)
        .unwrap();

    // Adjacent and on opposite teams, so the reachability half is
    // emphatically not what ends this.
    assert!(!e.is_stalemate(), "a fresh fight is not a draw");

    // Now let both of them do nothing, round after round. `SKIP` is
    // the whole turn, so this is the cleanest possible zero-progress
    // fight: no damage, no healing, no conditions, no movement.
    let mut steps = 0usize;
    while !e.is_complete() && steps < 200_000 {
        steps += 1;
        e.process_stack();
        if e.is_complete() {
            break;
        }
        let Some(prompt) = e.peek_prompt() else { break };
        let actor_id = prompt.actor_id();
        e.pop_prompt();
        e.push_action(ActionExecutionInfo::new(
            &*crate::actions::default_actions::SKIP,
            actor_id,
            None,
            None,
            None,
        ));
    }

    assert!(
        e.is_complete(),
        "two goblins staring at each other for {} rounds is not an ongoing fight",
        e.round()
    );
    assert!(
        e.is_stalemate(),
        "and it ended as a draw rather than as somebody's win"
    );
    assert_eq!(
        e.winning_team(),
        None,
        "a draw has no winner — both goblins are still standing"
    );
    // Both alive, so this really was the attrition rule and not one of
    // them quietly dying to something.
    assert!(e.actors[&a].is_combat_active() && e.actors[&b].is_combat_active());
    // And it took roughly the declared threshold to call it, rather
    // than firing early on the opening rounds.
    assert!(
        e.round() >= EncounterInstance::NO_PROGRESS_ROUNDS,
        "the draw was called at round {} — earlier than the threshold that \
         is supposed to govern it",
        e.round()
    );
}

/// Every creature template written in the bestiary is reachable in
/// play — by the encounter generator, by a player picking a class, by
/// a summoning spell, or by a class feature.
///
/// This is the sweep for the engine's oldest recurring bug, and it has
/// bitten at least twice. Twenty-one PC templates — every dragonborn
/// ancestry and six lineage builds — sat fully implemented and
/// completely unreachable until `pc_template_families` was written:
/// absent from the player's picker and absent from the encounter
/// pool, instantiated only by a unit test. The four SRD conjurations
/// added alongside this test are the same story from the other
/// direction: five stat blocks in the pool that no caster could ever
/// call up as an ally.
///
/// The failure is silent by construction. An unreachable template
/// compiles, passes its own file's tests, and is indistinguishable
/// from a working one in every way except that nobody will ever see
/// it. Nothing short of a sweep finds it.
///
/// **How the declared side is counted.** There is no reflection in
/// Rust to enumerate statics with, so the count comes from reading the
/// bestiary directory at test time and counting
/// `pub static …_TEMPLATE` declarations. Blunt, and the right
/// instrument: the alternative is a hand-maintained list of four
/// hundred and sixty entries, which is one more thing to forget to
/// edit and so reintroduces the bug it would exist to catch.
///
/// **How the reachable side is counted.** Pointer identity across the
/// four registries a template can be reachable through, plus the
/// short list below of templates reachable only through a class
/// feature's own action — those have no registry to walk, so they are
/// named here.
#[test]
fn every_creature_template_in_the_bestiary_is_reachable() {
    use crate::actors::creatures::pc_template_families;
    use crate::actors::actor_template::CreatureTemplate;
    use std::collections::HashSet;

    // Reachable only through a class feature's own action — a Beast
    // Master's companion, an Artillerist's cannon, a Shepherd Druid's
    // totem. Each is summoned by a bespoke action rather than by a
    // `SummonSpell`, so no registry lists them and the sweep would
    // otherwise call them unreachable. They are named here rather than
    // exempted by pattern, so that a *genuinely* stranded template
    // cannot hide behind a rule like "anything ending in _COMPANION".
    let by_class_feature: &[&'static CreatureTemplate] = &[
        &crate::actors::creatures::spirit_totems::BEAR_SPIRIT_TOTEM_TEMPLATE,
        &crate::actors::creatures::spirit_totems::UNICORN_SPIRIT_TOTEM_TEMPLATE,
        &crate::actors::creatures::drakes::DRAKE_COMPANION_TEMPLATE,
        &crate::actors::creatures::wolves::RANGERS_COMPANION_TEMPLATE,
        &crate::actors::creatures::steel_defenders::STEEL_DEFENDER_TEMPLATE,
        &crate::actors::creatures::wildfire_spirits::WILDFIRE_SPIRIT_TEMPLATE,
        &crate::actors::creatures::deep_tentacles::TENTACLE_OF_THE_DEEP_TEMPLATE,
        &crate::actors::creatures::eldritch_cannons::FLAMETHROWER_CANNON_TEMPLATE,
        &crate::actors::creatures::eldritch_cannons::FORCE_BALLISTA_CANNON_TEMPLATE,
        &crate::actors::creatures::eldritch_cannons::PROTECTOR_CANNON_TEMPLATE,
        &crate::actors::creatures::tiny_animated_objects::TINY_ANIMATED_OBJECT_TEMPLATE,
    ];

    let mut reachable: HashSet<usize> = HashSet::new();
    let mut note = |t: &'static CreatureTemplate| {
        reachable.insert(std::ptr::from_ref(t) as usize);
    };
    for t in EncounterInstance::template_pool() {
        note(t);
    }
    for (_family, templates) in pc_template_families() {
        for t in templates {
            note(t);
        }
    }
    for spell in crate::actions::spells::all_summon_spells() {
        note(spell.template);
    }
    for t in by_class_feature {
        note(t);
    }

    // Cargo runs tests with the working directory set to the package
    // root, which is what makes reading the tree here work at all.
    let dir = std::path::Path::new("src/actors/creatures");
    let mut declared = 0usize;
    let mut files = 0usize;
    for entry in std::fs::read_dir(dir).expect("the bestiary directory is readable") {
        let path = entry.expect("a readable directory entry").path();
        if path.extension().is_none_or(|e| e != "rs") {
            continue;
        }
        files += 1;
        let source = std::fs::read_to_string(&path).expect("a readable bestiary file");
        declared += source
            .lines()
            .filter(|line| {
                line.starts_with("pub static ") && line.contains("_TEMPLATE: LazyLock<")
            })
            .count();
    }
    // Guard against the scan silently finding nothing and the whole
    // test passing vacuously — the exact way a source-reading check
    // rots.
    assert!(
        files > 300 && declared > 400,
        "the bestiary scan found {declared} templates across {files} files, \
         which means it stopped working rather than that the bestiary shrank"
    );

    assert_eq!(
        reachable.len(),
        declared,
        "the bestiary declares {declared} creature templates but only {} are \
         reachable — a template that no pool, no class picker, no summon and no \
         feature can produce is a stat block nobody will ever see. Add it to \
         `EncounterInstance::template_pool`, `pc_template_families`, \
         `all_summon_spells`, or the by-class-feature list in this test.",
        reachable.len()
    );
}

/// Every PC class family renders unambiguously *within itself*: no
/// two templates in a family share a name or a map glyph.
///
/// This replaces five near-identical per-family checks that had
/// accumulated one subclass at a time (the wizard traditions, plus
/// an inline block inside each of the fighter / monk / rogue / druid
/// drift pins). Each was the same twelve lines with a different
/// import list, and each only covered the family whose newest member
/// prompted it — so barbarian, bard, cleric, paladin, ranger,
/// sorcerer and warlock were never checked at all despite carrying
/// thirteen, five, eight, seven, seven, six and ten templates.
///
/// The scope is deliberately per-family rather than global.
/// Cross-family glyph collisions are an explicit policy of the
/// template docs — Samurai Fighter 'S' shares with Tempest Cleric
/// 'S', Scout Rogue 'K' with Killer Whale, Assassin Rogue 'A' with
/// Ape — because the team colour and team id disambiguate them on
/// the map. What is *not* acceptable is two members of one class
/// family colliding, since those are exactly the templates a player
/// sets against each other by name and reads side by side in an
/// initiative list.
///
/// A new subclass template lands as one row on the family it joins.
#[test]
fn every_pc_class_family_renders_unambiguously() {
    let families = crate::actors::creatures::pc_template_families();
    for (label, family) in families {
        let names: std::collections::HashSet<&str> =
            family.iter().map(|t| t.name).collect();
        assert_eq!(
            names.len(),
            family.len(),
            "two {} templates share a name",
            label
        );
        let glyphs: std::collections::HashSet<char> =
            family.iter().map(|t| t.glyph).collect();
        assert_eq!(
            glyphs.len(),
            family.len(),
            "two {} templates share a glyph: {:?}",
            label,
            family.iter().map(|t| (t.name, t.glyph)).collect::<Vec<_>>()
        );
    }
}

/// The second hole in the same invariant: an actor who dies on their
/// own turn vacates their initiative index without an
/// `advance_initiative`, and `InitiativeTracker::remove_actor` lets
/// the next actor slide into it. That actor gets prompted off a slot
/// change nothing announced, so before `ensure_turn_started` they
/// acted with no turn start — carrying whatever action economy was
/// left from their previous turn, with `UntilStartOfNextTurn`
/// conditions unexpired and recharge abilities un-rolled.
///
/// Four actors, two per team, so killing the leader leaves both
/// teams standing and the encounter still wants a prompt. Which
/// actor leads is seed-dependent, so the test kills whoever it is.
#[test]
fn dying_on_your_own_turn_still_starts_the_next_actors_turn() {
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::skeletons::SKELETON_TEMPLATE;

    let mut e = ei_with_terrain(20, 20, &[]);
    let mut ids = Vec::new();
    for (i, (tpl, team)) in [
        (&*GOBLIN_TEMPLATE, 0usize),
        (&*GOBLIN_TEMPLATE, 0),
        (&*SKELETON_TEMPLATE, 1),
        (&*SKELETON_TEMPLATE, 1),
    ]
    .into_iter()
    .enumerate()
    {
        ids.push(
            e.instantiate_creature(
                tpl,
                Coordinate::new(2 + (i as isize) * 4, 2),
                team,
                i,
            )
            .unwrap(),
        );
    }
    e.process_stack();
    let leader = e.peek_prompt().map(|p| p.actor_id()).expect("a prompt");
    e.pop_prompt();
    // The actor next in line hasn't had a turn yet.
    let next = e.initiative_slots()[1].actor_id;
    assert_ne!(next, leader);
    assert!(!e.actors[&next].has_taken_turn_in_combat());

    // Kill the leader from *inside* a `process_stack` drain, the way
    // a damage reflect resolving off the leader's own swing does.
    // Queueing the damage as a side-effect rather than mutating HP
    // directly is what makes this exercise the pre-prompt half of
    // the fix: the slot changes after `process_stack` has already
    // opened the leader's turn, so only the second
    // `ensure_turn_started` can catch it.
    let hp = e.actors[&leader].max_hitpoints() + 1;
    e.enqueue_event(StackElementEntry::SideEffect(Box::new(
        crate::engine::side_effects::DealDamage {
            actor_id: leader,
            amount: hp,
            damage_type: DamageType::Slashing,
        },
    )));
    e.process_stack();
    assert!(!e.actors.contains_key(&leader), "leader is gone");
    let prompted = e
        .peek_prompt()
        .map(|p| p.actor_id())
        .expect("the next actor is prompted");
    assert_eq!(prompted, next, "the slot passes to the next actor in line");
    assert!(
        e.actors[&next].has_taken_turn_in_combat(),
        "and their turn is actually opened rather than inherited"
    );
}

/// Moon Druid template drift pin. Name / glyph uniqueness across the
/// druid family is covered family-wide by
/// `every_pc_class_family_renders_unambiguously`. The Moon Druid is the
/// baseline caster plus three actions and one tag — nothing about
/// the stat block or the spell list moves, which is both RAW and
/// the reason the form's numbers live on the form.
#[test]
fn moon_druid_ships_its_kit_and_leaves_the_caster_chassis_alone() {
    use crate::actions::class_features::COMBAT_WILD_SHAPE_TAG;
    use crate::actors::creatures::druids::{
        DRUID_TEMPLATE, MOON_DRUID_TEMPLATE,
    };
    let mut e = ei_with_terrain(15, 15, &[]);
    let druid = e
        .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&druid].has_passive_feature(COMBAT_WILD_SHAPE_TAG));
    for name in ["wild shape", "wild heal", "beast claws", "moonbeam", "scimitar"] {
        assert!(
            e.actors[&druid].find_action(name).is_some(),
            "Moon Druid should carry the {} action",
            name
        );
    }
    // The caster chassis is untouched: same stats, same slots.
    assert_eq!(MOON_DRUID_TEMPLATE.wisdom, DRUID_TEMPLATE.wisdom);
    assert_eq!(MOON_DRUID_TEMPLATE.ac, DRUID_TEMPLATE.ac);
    assert_eq!(
        MOON_DRUID_TEMPLATE.spell_slots_by_level,
        DRUID_TEMPLATE.spell_slots_by_level
    );

}

/// Wild Shape hands over the beast body and takes the spell list in
/// exchange: temp HP lands, the claws unlock, and every levelled
/// spell stops being affordable. Reverting restores all three.
/// Form of the Beast only exists while the rage does, and each form
/// only answers to its own tag.
#[test]
fn the_beast_forms_need_both_the_rage_and_their_own_tag() {
    use crate::actions::class_attacks::{BEAST_BITE, BEAST_CLAWS, BEAST_TAIL};
    use crate::actors::creatures::barbarians::{
        BITE_BEAST_BARBARIAN_TEMPLATE, CLAW_BEAST_BARBARIAN_TEMPLATE,
        TAIL_BEAST_BARBARIAN_TEMPLATE,
    };
    use crate::actions::action_template::Action;

    let mut e = ei_with_terrain(15, 15, &[]);
    let bite_barb = e
        .instantiate_creature(&BITE_BEAST_BARBARIAN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let target = e
        .instantiate_creature(
            &crate::actors::creatures::zombies::ZOMBIE_TEMPLATE,
            Coordinate::new(4, 2),
            1,
            0,
        )
        .unwrap();
    let targets = vec![target];

    assert!(
        !BEAST_BITE.validate_input(&e, bite_barb, Some(&targets), None, None),
        "the form manifests with the rage, not before it"
    );
    e.actors
        .get_mut(&bite_barb)
        .unwrap()
        .add_condition(Condition::Raging, ConditionTimer::Rounds(10));
    assert!(
        BEAST_BITE.validate_input(&e, bite_barb, Some(&targets), None, None),
        "raging, the bite is live"
    );
    // The tag is what makes the three forms exclusive: a raging bite
    // barbarian handed the claws would still be refused.
    assert!(
        !BEAST_CLAWS.validate_input(&e, bite_barb, Some(&targets), None, None),
        "one form per build"
    );
    assert!(!BEAST_TAIL.validate_input(&e, bite_barb, Some(&targets), None, None));

    // And each sibling template answers to its own.
    for (template, weapon) in [
        (
            &*CLAW_BEAST_BARBARIAN_TEMPLATE,
            &*BEAST_CLAWS as &dyn Action,
        ),
        (&*TAIL_BEAST_BARBARIAN_TEMPLATE, &*BEAST_TAIL as &dyn Action),
    ] {
        let id = e
            .instantiate_creature(template, Coordinate::new(8, 8), 0, 0)
            .unwrap();
        e.actors
            .get_mut(&id)
            .unwrap()
            .add_condition(Condition::Raging, ConditionTimer::Rounds(10));
        let near = e
            .instantiate_creature(
                &crate::actors::creatures::zombies::ZOMBIE_TEMPLATE,
                Coordinate::new(10, 8),
                1,
                0,
            )
            .unwrap();
        let near_targets = vec![near];
        assert!(
            weapon.validate_input(&e, id, Some(&near_targets), None, None),
            "{} should be able to swing its own form",
            template.name
        );
        assert!(
            !BEAST_BITE.validate_input(&e, id, Some(&near_targets), None, None),
            "{} should not be able to bite",
            template.name
        );
    }
}

/// The bite's heal is gated three ways — below half hit points, once
/// per turn, and only on a swing that landed.
#[test]
fn the_beast_bite_heals_only_a_bloodied_barbarian_and_only_once_a_turn() {
    use crate::actions::class_attacks::BEAST_BITE;
    use crate::actions::class_features::FORM_OF_THE_BEAST_BITE_TAG;
    use crate::actors::creatures::barbarians::BITE_BEAST_BARBARIAN_TEMPLATE;

    // The zombie is AC 8 and the raging barbarian swings at +7, so
    // across a handful of seeds at least one bite lands; the assert
    // below is on the heal, not on the roll.
    let mut healed_in = 0;
    let mut healed_while_healthy = 0;
    for seed in 0..8u64 {
        for bloodied in [false, true] {
            let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
            let barb = e
                .instantiate_creature(
                    &BITE_BEAST_BARBARIAN_TEMPLATE,
                    Coordinate::new(2, 2),
                    0,
                    0,
                )
                .unwrap();
            let target = e
                .instantiate_creature(
                    &crate::actors::creatures::zombies::ZOMBIE_TEMPLATE,
                    Coordinate::new(4, 2),
                    1,
                    0,
                )
                .unwrap();
            e.actors
                .get_mut(&barb)
                .unwrap()
                .add_condition(Condition::Raging, ConditionTimer::Rounds(10));
            let max = e.actors[&barb].max_hitpoints();
            // Hurt either way so the heal has room to show; only the
            // `bloodied` arm crosses below half.
            let wound = if bloodied { max / 2 + 1 } else { 1 };
            e.actors.get_mut(&barb).unwrap().take_damage(wound);
            let before = e.actors[&barb].hitpoints();

            let targets = vec![target];
            let effects = BEAST_BITE.side_effects(&mut e, barb, Some(&targets), None, None);
            for ef in effects {
                ef.apply(&mut e);
            }
            let gained = e.actors[&barb].hitpoints().saturating_sub(before);
            if bloodied {
                if gained > 0 {
                    healed_in += 1;
                    assert_eq!(
                        gained,
                        e.actors[&barb].proficiency_bonus() as u32,
                        "the heal is the proficiency bonus, flat"
                    );
                    assert!(
                        e.actors[&barb].once_per_turn_used(FORM_OF_THE_BEAST_BITE_TAG),
                        "a fired heal marks itself spent for the turn"
                    );
                    // Extra Attack already swung twice inside that
                    // one Action; the mark is what kept the second
                    // swing from healing again.
                    assert!(
                        gained <= e.actors[&barb].proficiency_bonus() as u32,
                        "once per turn, not once per swing"
                    );
                }
            } else if gained > 0 {
                healed_while_healthy += 1;
            }
        }
    }
    assert!(
        healed_in > 0,
        "the bite should have healed a bloodied barbarian in at least one of 8 seeds"
    );
    assert_eq!(
        healed_while_healthy, 0,
        "a barbarian above half hit points should never have healed"
    );
}

#[test]
fn wild_shape_trades_the_spell_list_for_a_beast_body() {
    use crate::actions::class_features::WILD_SHAPE;
    use crate::actions::spells::MOONBEAM;
    use crate::actors::creatures::druids::MOON_DRUID_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let druid = e
        .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let target = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    e.actors
        .get_mut(&druid)
        .unwrap()
        .give_resource(Resource::BonusAction);

    // Out of form: the claws are refused and the spell list works.
    let targets = vec![target];
    assert!(
        !crate::actions::class_attacks::BEAST_FORM_CLAWS
            .validate_input(&e, druid, Some(&targets), None, None),
        "no claws without a beast body"
    );
    assert!(
        e.actors[&druid].can_consume_resource(Resource::SpellSlot(2)),
        "a druid out of shape casts normally"
    );

    assert!(WILD_SHAPE.validate_input(&e, druid, None, None, None));
    let effects = WILD_SHAPE.execute(&mut e, druid, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    assert!(e.actors[&druid].has_condition(Condition::WildShaped));
    assert_eq!(
        e.actors[&druid].temp_hp(),
        34,
        "the brown bear's hit points arrive as the form's pool"
    );
    assert!(
        crate::actions::class_attacks::BEAST_FORM_CLAWS
            .validate_input(&e, druid, Some(&targets), None, None),
        "the form unlocks its natural weapon"
    );
    // The cost: RAW's "you can't cast spells", via the same
    // `blocks_spell_slots` gate the Silence spell uses.
    assert!(
        !e.actors[&druid].can_consume_resource(Resource::SpellSlot(2)),
        "a bear casts nothing"
    );
    assert!(
        !MOONBEAM.validate_input(
            &e,
            druid,
            None,
            Some(&vec![Coordinate::new(6, 2)]),
            None
        ),
        "and the spell list refuses at the action layer too"
    );
    // The charge is spent, so the button doesn't re-fire.
    assert!(!WILD_SHAPE.validate_input(&e, druid, None, None, None));

    // Reverting gives everything back.
    e.actors
        .get_mut(&druid)
        .unwrap()
        .remove_condition(Condition::WildShaped);
    assert!(e.actors[&druid].can_consume_resource(Resource::SpellSlot(2)));
    assert!(
        !crate::actions::class_attacks::BEAST_FORM_CLAWS
            .validate_input(&e, druid, Some(&targets), None, None)
    );
}

/// Wild Heal burns the lowest slot for `level`d8 HP, and does it
/// *through* the can't-cast gate the form imposes — the whole point
/// of draining the slot manager directly rather than declaring a
/// `SpellSlot` cost.
#[test]
fn wild_heal_spends_a_slot_the_form_would_otherwise_block() {
    use crate::actions::class_features::WILD_HEAL;
    use crate::actors::creatures::druids::MOON_DRUID_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let druid = e
        .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    {
        let a = e.actors.get_mut(&druid).unwrap();
        a.give_resource(Resource::BonusAction);
        a.give_resource(Resource::BonusAction);
    }
    // Install the form directly rather than through `WILD_SHAPE`:
    // the real button also grants 34 temp HP, which would absorb
    // the wound this test needs to be healing. What's under test is
    // the conversion, not the transform.
    {
        let a = e.actors.get_mut(&druid).unwrap();
        a.add_condition(Condition::WildShaped, ConditionTimer::Rounds(10));
        let _ = a.take_damage(20);
    }
    let hp_before = e.actors[&druid].hitpoints();
    assert!(hp_before < e.actors[&druid].max_hitpoints());
    let slots_before = e.actors[&druid].lowest_available_spell_slot();
    assert_eq!(slots_before, Some(1), "lowest slot first");

    assert!(WILD_HEAL.validate_input(&e, druid, None, None, None));
    let effects = WILD_HEAL.execute(&mut e, druid, None, None, None);
    for ef in effects {
        ef.apply(&mut e);
    }
    assert!(
        e.actors[&druid].hitpoints() > hp_before,
        "the conversion actually heals"
    );
    assert_eq!(
        e.actors[&druid]
            .spell_slot_manager
            .spell_slots(1)
            .spell_slots,
        MOON_DRUID_TEMPLATE.spell_slots_by_level[0] - 1,
        "exactly one level-1 slot burned"
    );
}

/// Wild Heal is form-gated and full-HP-gated: a druid out of shape
/// can't reach it at all, and a druid at full HP shouldn't burn a
/// slot for nothing.
#[test]
fn wild_heal_declines_out_of_form_and_at_full_health() {
    use crate::actions::class_features::WILD_HEAL;
    use crate::actors::creatures::druids::MOON_DRUID_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(15, 15, &[]);
    let druid = e
        .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors
        .get_mut(&druid)
        .unwrap()
        .give_resource(Resource::BonusAction);
    e.actors
        .get_mut(&druid)
        .unwrap()
        .take_damage(20);
    assert!(
        !WILD_HEAL.validate_input(&e, druid, None, None, None),
        "wounded but not in form"
    );

    {
        let a = e.actors.get_mut(&druid).unwrap();
        a.add_condition(Condition::WildShaped, ConditionTimer::Rounds(10));
    }
    assert!(WILD_HEAL.validate_input(&e, druid, None, None, None));

    // Top back up: nothing to convert a slot into.
    let max = e.actors[&druid].max_hitpoints();
    e.actors.get_mut(&druid).unwrap().heal(max);
    assert!(
        !WILD_HEAL.validate_input(&e, druid, None, None, None),
        "in form but at full HP"
    );
}

/// Shadow Monk template drift pin. Name / glyph uniqueness across
/// the monk family is covered family-wide by
/// `every_pc_class_family_renders_unambiguously`.
#[test]
fn shadow_monk_ships_its_kit_and_inherits_the_monk_chassis() {
    use crate::actions::class_features::{
        EMPTY_BODY_TAG, SHADOW_ARTS_TAG, SHADOW_STEP_TAG, STUNNING_STRIKE_TAG,
        UNARMORED_MOVEMENT_TAG,
    };
    use crate::actors::creatures::monks::{
        MONK_TEMPLATE, SHADOW_MONK_TEMPLATE,
    };
    let mut e = ei_with_terrain(15, 15, &[]);
    let monk = e
        .instantiate_creature(&SHADOW_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    for tag in [SHADOW_ARTS_TAG, SHADOW_STEP_TAG] {
        assert!(
            e.actors[&monk].has_passive_feature(tag),
            "Shadow Monk should carry {}",
            tag
        );
    }
    // Baseline chassis rides through the clone tail.
    for tag in [STUNNING_STRIKE_TAG, EMPTY_BODY_TAG, UNARMORED_MOVEMENT_TAG] {
        assert!(
            e.actors[&monk].has_passive_feature(tag),
            "Shadow Monk should inherit baseline Monk tag {}",
            tag
        );
    }
    assert!(e.actors[&monk].has_evasion());
    assert!(e.actors[&monk].has_extra_attack());
    for name in ["shadow step", "silence", "pass without trace", "flurry of blows"] {
        assert!(
            e.actors[&monk].find_action(name).is_some(),
            "Shadow Monk should carry the {} action",
            name
        );
    }
    // The slot table is Shadow Arts' ki budget: no level-1 slots,
    // two level-2s — exactly two casts and no other magic.
    assert_eq!(
        SHADOW_MONK_TEMPLATE.spell_slots_by_level,
        vec![0, 2],
        "two level-2 slots, no level-1"
    );
    assert!(
        MONK_TEMPLATE.spell_slots_by_level.is_empty(),
        "the baseline monk stays slotless"
    );

}

/// Shadow Step teleports the monk and arms the melee-only advantage
/// prime — which reads as Advantage on a melee swing, Normal on a
/// ranged one, and is gone after the first attack either way.
#[test]
fn shadow_step_teleports_and_arms_a_melee_only_prime() {
    use crate::actions::class_features::SHADOW_STEP;
    use crate::actors::creatures::monks::SHADOW_MONK_TEMPLATE;
    use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::side_effects::Resource;

    let mut e = ei_with_terrain(20, 20, &[]);
    let monk = e
        .instantiate_creature(&SHADOW_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let target = e
        .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(12, 2), 1, 0)
        .unwrap();
    e.actors
        .get_mut(&monk)
        .unwrap()
        .give_resource(Resource::BonusAction);

    // Medium creatures are 2x2 on this 2.5 ft grid. Land clear of
    // the zombie rather than beside it: the point of the assertions
    // below is the Shadow Step prime alone, and standing in contact
    // would fold the "ranged attacks while a hostile is adjacent"
    // disadvantage into the ranged reading.
    let dest = vec![Coordinate::new(6, 2)];
    assert!(SHADOW_STEP.validate_input(&e, monk, None, Some(&dest), None));
    let effects = SHADOW_STEP.execute(&mut e, monk, None, Some(&dest), None);
    for ef in effects {
        ef.apply(&mut e);
    }
    assert_eq!(
        e.actors[&monk].location(),
        Coordinate::new(6, 2),
        "the monk arrives where they aimed"
    );
    assert!(e.actors[&monk].has_condition(Condition::Shadowstepping));
    // Melee reads Advantage; ranged reads Normal — the whole reason
    // this rides its own melee-gated cohort rather than the broader
    // `grants_self_attack_advantage` one its siblings use.
    assert_eq!(
        e.compute_attack_mode(monk, target, false),
        RollMode::Normal,
        "a ranged swing collects nothing from Shadow Step"
    );
    assert_eq!(
        e.compute_attack_mode(monk, target, true),
        RollMode::Advantage,
        "a melee swing collects the prime"
    );
    // One-shot.
    e.clear_attack_advantage_riders(monk, target);
    assert!(!e.actors[&monk].has_condition(Condition::Shadowstepping));
    assert_eq!(e.compute_attack_mode(monk, target, true), RollMode::Normal);
}

