fn aura_of_hate_does_not_fire_on_ranged_weapon_hits() {
    use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
    use crate::actors::creatures::skeletons::SKELETON_TEMPLATE;
    use crate::engine::attack::{AttackParams, resolve_attack_outcome};

    let trials = 200u64;
    let mut aura_dmg: u32 = 0;
    let mut baseline_dmg: u32 = 0;
    for seed in 0..trials {
        let mut e = ei_with_terrain(15, 15, &[]);
        e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
        let attacker = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.actors.get_mut(&attacker).unwrap().set_aura_of_hate(true);
        let target = e
            .instantiate_creature(&SKELETON_TEMPLATE, Coordinate::new(5, 2), 1, 0)
            .unwrap();
        let (_, dealt) = resolve_attack_outcome(
            &mut e,
            AttackParams {
                caster_id: attacker,
                target_id: target,
                action_name: "longbow",
                attack_bonus: 5,
                damage_dice: Dice::new(1, 8),
                damage_bonus: 3,
                damage_type: DamageType::Piercing,
                is_melee: false,
                long_range: Some(30),
                min_range: None,
                is_spell: false,
            },
        );
        aura_dmg = aura_dmg.saturating_add(dealt);
    }
    for seed in 0..trials {
        let mut e = ei_with_terrain(15, 15, &[]);
        e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
        let attacker = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.actors.get_mut(&attacker).unwrap().set_aura_of_hate(false);
        let target = e
            .instantiate_creature(&SKELETON_TEMPLATE, Coordinate::new(5, 2), 1, 0)
            .unwrap();
        let (_, dealt) = resolve_attack_outcome(
            &mut e,
            AttackParams {
                caster_id: attacker,
                target_id: target,
                action_name: "longbow",
                attack_bonus: 5,
                damage_dice: Dice::new(1, 8),
                damage_bonus: 3,
                damage_type: DamageType::Piercing,
                is_melee: false,
                long_range: Some(30),
                min_range: None,
                is_spell: false,
            },
        );
        baseline_dmg = baseline_dmg.saturating_add(dealt);
    }
    assert_eq!(
        aura_dmg, baseline_dmg,
        "aura of hate must NOT fire on ranged swings (aura {} vs baseline {})",
        aura_dmg, baseline_dmg,
    );
}

/// The Oathbreaker Paladin subclass template ships both Aura of
/// Hate AND Fanatical Focus; other paladin subclasses (Devotion,
/// Ancients, Vengeance) and the baseline paladin don't. Pins
/// the subclass-of layering so a future template refactor
/// surfaces breakage here.
#[test]
fn oathbreaker_paladin_ships_aura_of_hate_and_fanatical_focus() {
    use crate::actions::class_features::FANATICAL_FOCUS_TAG;
    use crate::actors::creatures::paladins::{
        ANCIENTS_PALADIN_TEMPLATE, DEVOTION_PALADIN_TEMPLATE, OATHBREAKER_PALADIN_TEMPLATE,
        PALADIN_TEMPLATE, VENGEANCE_PALADIN_TEMPLATE,
    };
    // Aura of Hate template flag.
    assert!(OATHBREAKER_PALADIN_TEMPLATE.has_aura_of_hate);
    assert!(!PALADIN_TEMPLATE.has_aura_of_hate);
    assert!(!DEVOTION_PALADIN_TEMPLATE.has_aura_of_hate);
    assert!(!ANCIENTS_PALADIN_TEMPLATE.has_aura_of_hate);
    assert!(!VENGEANCE_PALADIN_TEMPLATE.has_aura_of_hate);
    // Fanatical Focus feature tag on `features` set.
    assert!(OATHBREAKER_PALADIN_TEMPLATE
        .features
        .contains(FANATICAL_FOCUS_TAG));
    assert!(!PALADIN_TEMPLATE.features.contains(FANATICAL_FOCUS_TAG));
    assert!(!DEVOTION_PALADIN_TEMPLATE
        .features
        .contains(FANATICAL_FOCUS_TAG));
    assert!(!ANCIENTS_PALADIN_TEMPLATE
        .features
        .contains(FANATICAL_FOCUS_TAG));
    assert!(!VENGEANCE_PALADIN_TEMPLATE
        .features
        .contains(FANATICAL_FOCUS_TAG));
}

/// Fanatical Focus auto-fires on the first failed save while
/// the tag is unspent. The reroll fires without an Action call
/// (distinct from Fighter Indomitable's pre-primed shape) and
/// spends the tag on trigger. Fails a save deterministically
/// with a very high DC so the first roll can't accidentally
/// pass; picks a mid-CHA paladin (CHA 14 = mod +2) so the
/// reroll's own d20 is the only variable.
#[test]
fn fanatical_focus_auto_fires_on_failed_save_and_spends_charge() {
    use crate::actions::class_features::FANATICAL_FOCUS_TAG;
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    let mut e = ei_with_terrain(15, 15, &[]);
    // Seed 42 chosen so the initial d20 roll on WIS save with
    // the paladin's CHA-mod bonuses lands under DC 100 — a
    // guaranteed fail across every reasonable seed since 100 is
    // uncatchable on a 1d20+modifier envelope.
    e.roller = FastRandRoller::with_seed(42);
    let id = e
        .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Precondition: the paladin's Fanatical Focus charge is
    // unspent at spawn.
    assert!(
        e.actors[&id].feature_available(FANATICAL_FOCUS_TAG),
        "Fanatical Focus charge starts full",
    );
    // `modifier + 20` is the highest DC a reroll can still clear —
    // the initial roll fails on nearly every face and the reroll is
    // worth firing. The charge burns on trigger regardless of the
    // reroll's own pass/fail; what it must not do is burn against a
    // DC 100, which is what this fixture used to assert.
    let dc = e.actors[&id].save_modifier(AbilityScoreType::Wisdom) + 20;
    let mut spent = false;
    for seed in 0u64..32 {
        e.roller = FastRandRoller::with_seed(seed);
        let _outcome = e.roll_save(id, AbilityScoreType::Wisdom, dc);
        if !e.actors[&id].feature_available(FANATICAL_FOCUS_TAG) {
            spent = true;
            break;
        }
    }
    assert!(
        spent,
        "Fanatical Focus should have fired on one of 32 rescuable failed saves",
    );
}

/// Fanatical Focus refreshes on a short rest (distinct from
/// Indomitable which is long-rest only). Pins the tag in
/// `SHORT_REST_FEATURES` — spending the charge, taking a short
/// rest, and re-checking the availability isolates the short-
/// rest refresh path.
#[test]
fn fanatical_focus_refreshes_on_short_rest() {
    use crate::actions::class_features::FANATICAL_FOCUS_TAG;
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::engine::dice::FastRandRoller;

    let mut e = ei_with_terrain(15, 15, &[]);
    e.roller = FastRandRoller::with_seed(7);
    let id = e
        .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Burn the charge directly — driving it off a save means
    // picking a DC the reroll can reach and a seed that fails
    // against it, which is
    // `fanatical_focus_auto_fires_on_failed_save_and_spends_charge`'s
    // job. This test is about the refresh.
    e.actors
        .get_mut(&id)
        .unwrap()
        .spend_feature(FANATICAL_FOCUS_TAG);
    assert!(!e.actors[&id].feature_available(FANATICAL_FOCUS_TAG));
    // Short rest — the tag is on `SHORT_REST_FEATURES` so the
    // charge refills.
    let mut roller = FastRandRoller::with_seed(0);
    e.actors.get_mut(&id).unwrap().short_rest(&mut roller);
    assert!(
        e.actors[&id].feature_available(FANATICAL_FOCUS_TAG),
        "short rest must refresh Fanatical Focus",
    );
}

/// Fanatical Focus stays quiet on a passing save — no charge
/// burn unless the save actually failed. Uses DC 0 so the
/// save auto-passes on any reasonable roll, and asserts the
/// tag survives untouched.
#[test]
fn fanatical_focus_does_not_fire_on_passing_save() {
    use crate::actions::class_features::FANATICAL_FOCUS_TAG;
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    let mut e = ei_with_terrain(15, 15, &[]);
    e.roller = FastRandRoller::with_seed(1);
    let id = e
        .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let outcome = e.roll_save(id, AbilityScoreType::Constitution, 0);
    assert!(outcome.passed(), "DC 0 must pass");
    assert!(
        e.actors[&id].feature_available(FANATICAL_FOCUS_TAG),
        "Fanatical Focus charge must NOT burn on a passing save",
    );
}

/// A paladin/fighter multiclass with both Indomitable AND
/// Fanatical Focus available spends Indomitable first per the
/// ordering in `FAILED_SAVE_REROLL_SOURCES`. Confirms that
/// pre-primed sources fire before automatic ones (RAW: the
/// pre-primed choice was explicit so it burns first).
#[test]
fn indomitable_burns_before_fanatical_focus_on_multiclass() {
    use crate::actions::class_features::{FANATICAL_FOCUS_TAG, INDOMITABLE_TAG};
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    let mut e = ei_with_terrain(15, 15, &[]);
    e.roller = FastRandRoller::with_seed(3);
    let id = e
        .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Multiclass fixture: grant Indomitable + pre-prime the
    // pending latch. The paladin already carries Fanatical
    // Focus from the template.
    {
        let actor = e.actors.get_mut(&id).unwrap();
        actor.grant_feature_for_test(INDOMITABLE_TAG);
        actor.mark_indomitable_pending();
    }
    assert!(e.actors[&id].feature_available(FANATICAL_FOCUS_TAG));
    assert!(e.actors[&id].indomitable_pending());
    // Fail a save the reroll could in principle answer — `modifier
    // + 20`. Indomitable (first in the cohort) burns; the paladin's
    // Fanatical Focus charge stays untouched, because the cohort
    // stops after one reroll. DC 100, the old fixture, is a save
    // neither source now fires on at all.
    let dc = e.actors[&id].save_modifier(AbilityScoreType::Wisdom) + 20;
    let mut fired = false;
    for seed in 0u64..32 {
        e.roller = FastRandRoller::with_seed(seed);
        e.actors.get_mut(&id).unwrap().mark_indomitable_pending();
        let _ = e.roll_save(id, AbilityScoreType::Wisdom, dc);
        if !e.actors[&id].indomitable_pending() {
            fired = true;
            break;
        }
    }
    assert!(
        fired,
        "Indomitable's pre-primed latch should have spent first on one of 32 seeds"
    );
    assert!(
        e.actors[&id].feature_available(FANATICAL_FOCUS_TAG),
        "Fanatical Focus preserved — cohort iteration stopped after Indomitable's reroll landed"
    );
}

/// 5e Oathbreaker Paladin **Dreadful Aspect** (subclass lv3 CD):
/// once-per-short-rest 30ft WIS-save burst → Frightened on fail,
/// with NO creature-type filter — every combat-active hostile in
/// range rolls the save. Verifies the tag ships on the Oathbreaker
/// template and NOT on other paladin subclasses, mirroring the
/// per-subclass CD-lane split (Turn the Faithless / Nature's Wrath
/// / Abjure Enemy).
#[test]
fn dreadful_aspect_ships_on_oathbreaker_paladin_only() {
    use crate::actions::class_features::DREADFUL_ASPECT_TAG;
    use crate::actors::creatures::paladins::{
        ANCIENTS_PALADIN_TEMPLATE, DEVOTION_PALADIN_TEMPLATE, OATHBREAKER_PALADIN_TEMPLATE,
        PALADIN_TEMPLATE, VENGEANCE_PALADIN_TEMPLATE,
    };
    assert!(OATHBREAKER_PALADIN_TEMPLATE
        .features
        .contains(DREADFUL_ASPECT_TAG));
    assert!(!PALADIN_TEMPLATE.features.contains(DREADFUL_ASPECT_TAG));
    assert!(!DEVOTION_PALADIN_TEMPLATE
        .features
        .contains(DREADFUL_ASPECT_TAG));
    assert!(!ANCIENTS_PALADIN_TEMPLATE
        .features
        .contains(DREADFUL_ASPECT_TAG));
    assert!(!VENGEANCE_PALADIN_TEMPLATE
        .features
        .contains(DREADFUL_ASPECT_TAG));
}

/// Dreadful Aspect fires on hostiles regardless of creature type
/// (no fey/fiend/undead filter — RAW: any creature within 30ft
/// that can see the paladin). Uses a humanoid target (goblin)
/// that would be OUTSIDE the Turn the Faithless / Turn Undead
/// filters — Dreadful Aspect's pass-through closure should still
/// pick it up. Also verifies the once-per-short-rest charge is
/// spent regardless of the target's save outcome.
/// Nature Domain template drift pin: the Dampen Elements tag and
/// charge, the Acolyte of Nature cantrip and skill, and the baseline
/// Cleric kit inherited through the clone tail.
#[test]
fn nature_cleric_ships_its_kit_and_inherits_the_cleric_chassis() {
    use crate::actions::class_features::{
        CHARM_ANIMALS_AND_PLANTS_TAG, DAMPEN_ELEMENTS_TAG, DESTROY_UNDEAD_TAG,
        DIVINE_STRIKE_TAG, PRESERVE_LIFE_TAG, TURN_UNDEAD_TAG,
    };
    use crate::actors::creatures::clerics::{CLERIC_TEMPLATE, NATURE_CLERIC_TEMPLATE};
    use crate::engine::types::Skill;
    let mut e = ei_with_terrain(15, 15, &[]);
    let cleric = e
        .instantiate_creature(&NATURE_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&cleric].has_passive_feature(DAMPEN_ELEMENTS_TAG));
    assert!(e.actors[&cleric].feature_available(DAMPEN_ELEMENTS_TAG));
    assert!(
        e.actors[&cleric].find_action("thorn whip").is_some(),
        "Acolyte of Nature's druid cantrip should be on the action list"
    );
    assert!(e.actors[&cleric].has_passive_feature(CHARM_ANIMALS_AND_PLANTS_TAG));
    assert!(e.actors[&cleric].feature_available(CHARM_ANIMALS_AND_PLANTS_TAG));
    assert!(
        e.actors[&cleric]
            .find_action("charm animals and plants")
            .is_some(),
        "the Channel Divinity needs an action surface"
    );
    assert!(NATURE_CLERIC_TEMPLATE.skills.contains(&Skill::Nature));
    assert!(
        !CLERIC_TEMPLATE.skills.contains(&Skill::Nature),
        "the baseline cleric must not already carry the skill"
    );
    for tag in [
        TURN_UNDEAD_TAG,
        DIVINE_STRIKE_TAG,
        PRESERVE_LIFE_TAG,
        DESTROY_UNDEAD_TAG,
    ] {
        assert!(
            e.actors[&cleric].has_passive_feature(tag),
            "Nature Cleric should inherit baseline Cleric tag {}",
            tag
        );
    }
}

/// Charm Animals and Plants installs Charmed — not Frightened — and
/// installs it *with* the `Charmed` back-link, which is what makes
/// the "can't attack your charmer" gate fire. Pins the `installed`
/// column the config gained for this feature, plus the link the
/// shared resolver now queues on its behalf. A humanoid in range is
/// untouched by the beast/plant filter.
#[test]
fn charm_animals_and_plants_charms_a_beast_with_its_link() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{
        CHARM_ANIMALS_AND_PLANTS, CHARM_ANIMALS_AND_PLANTS_TAG,
    };
    use crate::actors::creatures::clerics::NATURE_CLERIC_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wolves::WOLF_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    let mut saw_charm = false;
    for seed in 0..40 {
        let mut e = ei_with_terrain(20, 20, &[]);
        e.roller = FastRandRoller::with_seed(seed);
        let cleric = e
            .instantiate_creature(&NATURE_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let wolf = e
            .instantiate_creature(&WOLF_TEMPLATE, Coordinate::new(4, 4), 1, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 4), 1, 1)
            .unwrap();
        let effects = CHARM_ANIMALS_AND_PLANTS.side_effects(&mut e, cleric, None, None, None);
        for eff in effects {
            eff.apply(&mut e);
        }
        assert!(e.actors[&cleric].feature_charges_remaining(CHARM_ANIMALS_AND_PLANTS_TAG) < 2);
        assert!(
            !e.actors[&goblin].has_condition(Condition::Charmed),
            "a humanoid is outside the beast/plant filter"
        );
        if e.actors[&wolf].has_condition(Condition::Charmed) {
            assert_eq!(
                e.actors[&wolf].linked_by(Condition::Charmed),
                Some(cleric),
                "the charm must carry its back-link to the cleric"
            );
            saw_charm = true;
            break;
        }
    }
    assert!(saw_charm, "charm animals and plants never landed on the wolf");
}

/// Dampen Elements is the cohort's only damage-type-filtered clamp: it
/// halves fire aimed at an ally 30 ft away and leaves slashing alone,
/// keeping its charge for damage it can actually answer.
#[test]
fn dampen_elements_halves_only_elemental_damage() {
    use crate::actions::class_features::DAMPEN_ELEMENTS_TAG;
    use crate::actors::creatures::clerics::NATURE_CLERIC_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
    use crate::engine::attack::apply_reactive_damage_clamps;
    use crate::engine::side_effects::Resource;
    let mut e = ei_with_terrain(30, 30, &[]);
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 5), 1, 0)
        .unwrap();
    let wizard = e
        .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(3, 5), 0, 0)
        .unwrap();
    let cleric = e
        .instantiate_creature(&NATURE_CLERIC_TEMPLATE, Coordinate::new(11, 5), 0, 1)
        .unwrap();
    // Slashing: outside the filter, so nothing fires and the charge
    // stays in hand.
    assert_eq!(
        apply_reactive_damage_clamps(
            &mut e,
            goblin,
            wizard,
            20,
            false,
            false,
            DamageType::Slashing
        ),
        20
    );
    assert!(e.actors[&cleric].feature_available(DAMPEN_ELEMENTS_TAG));
    assert!(e.actors[&cleric].can_consume_resource(Resource::Reaction));
    // Fire: halved from across the battlefield, charge and reaction
    // spent.
    assert_eq!(
        apply_reactive_damage_clamps(&mut e, goblin, wizard, 20, false, false, DamageType::Fire),
        10
    );
    assert!(!e.actors[&cleric].feature_available(DAMPEN_ELEMENTS_TAG));
    assert!(!e.actors[&cleric].can_consume_resource(Resource::Reaction));
}

/// Arcana Domain template drift pin: the Channel Divinity action, its
/// tag and charge, the Spell Resistance flag, and the whole baseline
/// Cleric kit inherited through the `..CLERIC_TEMPLATE.clone()` tail —
/// Turn Undead included, so the Arcana Cleric answers both the dead
/// and the extraplanar.
#[test]
fn arcana_cleric_ships_its_kit_and_inherits_the_cleric_chassis() {
    use crate::actions::class_features::{
        ARCANE_ABJURATION_TAG, DESTROY_UNDEAD_TAG, DIVINE_STRIKE_TAG, POTENT_SPELLCASTING_TAG,
        PRESERVE_LIFE_TAG, TURN_UNDEAD_TAG,
    };
    use crate::actors::creatures::clerics::{ARCANA_CLERIC_TEMPLATE, CLERIC_TEMPLATE};
    let mut e = ei_with_terrain(15, 15, &[]);
    let cleric = e
        .instantiate_creature(&ARCANA_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    assert!(e.actors[&cleric].has_passive_feature(ARCANE_ABJURATION_TAG));
    assert!(e.actors[&cleric].feature_available(ARCANE_ABJURATION_TAG));
    assert!(
        e.actors[&cleric].find_action("arcane abjuration").is_some(),
        "the Channel Divinity needs an action surface"
    );
    // Arcana's RAW level-8 feature is Potent Spellcasting, so the
    // chassis's radiant Divine Strike is swapped out rather than
    // inherited — one level-8 feature per domain, as for every
    // sibling.
    assert!(e.actors[&cleric].has_passive_feature(POTENT_SPELLCASTING_TAG));
    assert!(!e.actors[&cleric].has_passive_feature(DIVINE_STRIKE_TAG));
    assert!(e.actors[&cleric].find_action("divine strike").is_none());
    for tag in [TURN_UNDEAD_TAG, PRESERVE_LIFE_TAG, DESTROY_UNDEAD_TAG] {
        assert!(
            e.actors[&cleric].has_passive_feature(tag),
            "Arcana Cleric should inherit baseline Cleric tag {}",
            tag
        );
    }
    // Spell Resistance, on the shared Magic Resistance lane.
    assert!(e.actors[&cleric].has_magic_resistance());
    assert!(
        !CLERIC_TEMPLATE.has_magic_resistance,
        "the baseline cleric must not already carry it"
    );
}

/// Arcane Abjuration's type filter is the complement of Turn Undead's:
/// it catches a fiend, and leaves a humanoid alone. Sweeps seeds so
/// at least one save fails.
#[test]
fn arcane_abjuration_frightens_a_fiend_but_not_a_humanoid() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{ARCANE_ABJURATION, ARCANE_ABJURATION_TAG};
    use crate::actors::creatures::clerics::ARCANA_CLERIC_TEMPLATE;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::imps::IMP_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::dice::FastRandRoller;
    let mut saw_frighten = false;
    for seed in 0..40 {
        let mut e = ei_with_terrain(20, 20, &[]);
        e.roller = FastRandRoller::with_seed(seed);
        let cleric = e
            .instantiate_creature(&ARCANA_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let imp = e
            .instantiate_creature(&IMP_TEMPLATE, Coordinate::new(4, 4), 1, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 4), 1, 1)
            .unwrap();
        let effects = ARCANE_ABJURATION.side_effects(&mut e, cleric, None, None, None);
        for eff in effects {
            eff.apply(&mut e);
        }
        assert!(
            e.actors[&cleric].feature_charges_remaining(ARCANE_ABJURATION_TAG) < 2,
            "the burst must spend a Channel Divinity press"
        );
        assert!(
            !e.actors[&goblin].has_condition(Condition::Frightened)
                && !e.actors[&goblin].has_condition(Condition::Banished),
            "a humanoid is outside the celestial/elemental/fey/fiend filter"
        );
        // The imp is CR 1, which is exactly the escalation ceiling, so
        // the Arcana Cleric's level-5 clause fires and it is sent home
        // rather than merely scared. Either outcome proves the burst
        // reached the fiend; which one it is, is the next test's
        // question.
        if e.actors[&imp].has_condition(Condition::Frightened)
            || e.actors[&imp].has_condition(Condition::Banished)
        {
            saw_frighten = true;
            break;
        }
    }
    assert!(saw_frighten, "arcane abjuration never landed on the fiend");
}

/// The level-5 half of Arcane Abjuration: a weak enough outsider that
/// fails the save is banished to its home plane rather than frightened,
/// and a heavier one on the same board is only frightened.
///
/// The clause three docstrings said the engine could not have, and the
/// pairing is the point — the CR ceiling is what separates the two
/// outcomes, not the creature type, which both of these share.
#[test]
fn arcane_abjuration_banishes_a_weak_fiend_and_only_frightens_a_strong_one() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{
        ARCANE_ABJURATION, ARCANE_ABJURATION_BANISH_TAG,
    };
    use crate::actors::creatures::clerics::ARCANA_CLERIC_TEMPLATE;
    use crate::actors::creatures::hell_hounds::HELL_HOUND_TEMPLATE;
    use crate::actors::creatures::imps::IMP_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::dice::FastRandRoller;

    assert!(
        ARCANA_CLERIC_TEMPLATE
            .features
            .contains(ARCANE_ABJURATION_BANISH_TAG),
        "the domain has to carry the level-5 unlock for the rung to exist"
    );

    let mut saw_split = false;
    for seed in 0..60 {
        let mut e = ei_with_terrain(20, 20, &[]);
        e.roller = FastRandRoller::with_seed(seed);
        let cleric = e
            .instantiate_creature(&ARCANA_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // CR 1 — at the ceiling, so it goes.
        let imp = e
            .instantiate_creature(&IMP_TEMPLATE, Coordinate::new(4, 4), 1, 0)
            .unwrap();
        // CR 3 — past the ceiling, so it stays and is merely
        // frightened. A hell hound rather than one of the heavier
        // demons because most of those are immune to Frightened
        // outright, which would prove nothing about the ceiling.
        let heavy = e
            .instantiate_creature(&HELL_HOUND_TEMPLATE, Coordinate::new(5, 5), 1, 1)
            .unwrap();
        for eff in ARCANE_ABJURATION.side_effects(&mut e, cleric, None, None, None) {
            eff.apply(&mut e);
        }
        if !e.actors[&imp].has_condition(Condition::Banished)
            || !e.actors[&heavy].has_condition(Condition::Frightened)
        {
            continue;
        }
        assert!(
            !e.actors[&imp].has_condition(Condition::Frightened),
            "the two outcomes are alternatives, not a stack"
        );
        assert!(
            !e.actors[&heavy].has_condition(Condition::Banished),
            "a CR-3 fiend is past the ceiling"
        );
        e.reconcile_board_presence();
        assert!(e.actors[&imp].is_off_board());
        assert!(!e.actors[&heavy].is_off_board());
        saw_split = true;
        break;
    }
    assert!(
        saw_split,
        "no seed produced both a failed imp save and a failed hell hound save"
    );
}

#[test]
fn dreadful_aspect_frightens_humanoid_and_spends_charge() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::{DREADFUL_ASPECT, DREADFUL_ASPECT_TAG};
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::dice::FastRandRoller;

    let mut saw_frighten = false;
    // Sweep seeds so at least one lands a failed save — the CHA-14
    // paladin's DC vs a goblin's WIS-mod-none save should fail
    // most seeds, but the sweep gives us a deterministic-across-
    // toolchains signal.
    for seed in 0..24 {
        let mut e = ei_with_terrain(20, 20, &[]);
        e.roller = FastRandRoller::with_seed(seed);
        let paladin = e
            .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Place a HUMANOID (goblin) at 4,4 — inside the 30ft (12
        // tile) burst. Turn the Faithless would skip it (fey/fiend
        // filter); Turn Undead would skip it (undead filter);
        // Dreadful Aspect must catch it.
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 4), 1, 0)
            .unwrap();
        assert!(e.actors[&paladin].feature_available(DREADFUL_ASPECT_TAG));
        let effects = DREADFUL_ASPECT.side_effects(&mut e, paladin, None, None, None);
        for eff in effects {
            eff.apply(&mut e);
        }
        // Charge spent regardless of the goblin's save outcome.
        assert!(
            !e.actors[&paladin].feature_available(DREADFUL_ASPECT_TAG),
            "Dreadful Aspect charge burns on cast, not on fail"
        );
        if e.actors[&goblin].has_condition(Condition::Frightened) {
            saw_frighten = true;
            break;
        }
    }
    assert!(
        saw_frighten,
        "Dreadful Aspect should Frighten a humanoid on at least one seed \
         — the pass-through creature-type filter must not skip humanoids"
    );
}

/// Dreadful Aspect skips allies (team filter inside
/// `resolve_turn_burst`) — a friendly goblin adjacent to the
/// paladin must never pick up Frightened even on a failed save.
/// Pins the shared team-filter clause against a hypothetical
/// future regression where the pass-through creature-type filter
/// gets confused with an "everyone in range" filter.
#[test]
fn dreadful_aspect_skips_allied_target() {
    use crate::actions::action_template::Action;
    use crate::actions::class_features::DREADFUL_ASPECT;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::conditions::Condition;
    use crate::engine::dice::FastRandRoller;

    let mut e = ei_with_terrain(20, 20, &[]);
    e.roller = FastRandRoller::with_seed(1);
    let paladin = e
        .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Ally goblin on team 0 (same team as the paladin).
    let ally = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 4), 0, 0)
        .unwrap();
    let effects = DREADFUL_ASPECT.side_effects(&mut e, paladin, None, None, None);
    for eff in effects {
        eff.apply(&mut e);
    }
    assert!(
        !e.actors[&ally].has_condition(Condition::Frightened),
        "ally must never pick up Frightened from Dreadful Aspect"
    );
}

/// Dreadful Aspect refreshes on a short rest — registered in
