/// A failed save no reroll could rescue leaves Indomitable and
/// Fanatical Focus where they are.
///
/// The reroll cohort's version of
/// `a_hopeless_save_does_not_burn_the_add_die_charge`. A reroll
/// replaces the d20 and nothing else, so a DC above `20 + modifier`
/// is one no fresh face can reach — and a fighter who spent
/// Indomitable on it would meet the next Hold Person without it.
#[test]
fn a_hopeless_save_does_not_burn_a_reroll_charge() {
    use crate::actions::class_features::FANATICAL_FOCUS_TAG;
    use crate::actors::creatures::paladins::OATHBREAKER_PALADIN_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    let mut e = ei_with_terrain(15, 15, &[]);
    let id = e
        .instantiate_creature(&OATHBREAKER_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    e.actors.get_mut(&id).unwrap().grant_feature_for_test(
        crate::actions::class_features::INDOMITABLE_TAG,
    );
    for seed in 0u64..8 {
        e.roller = FastRandRoller::with_seed(seed);
        e.actors.get_mut(&id).unwrap().mark_indomitable_pending();
        let outcome = e.roll_save(id, AbilityScoreType::Wisdom, 100);
        assert!(!outcome.passed(), "DC 100 must fail");
    }
    assert!(
        e.actors[&id].indomitable_pending(),
        "Indomitable's latch should survive a save it could not have rescued"
    );
    assert!(
        e.actors[&id].feature_available(FANATICAL_FOCUS_TAG),
        "and so should Fanatical Focus"
    );
}

/// A failed save the boost could never rescue leaves the charge
/// alone.
///
/// The attack lane's twin is
/// `a_hopeless_miss_does_not_burn_the_rescue_charge`, and the
/// reasoning is the same: RAW lets the holder add the die to a roll
/// with no chance, but the holder is a person looking at the gap and
/// the engine is deciding for them. DC 100 is the fixture three of
/// these tests used to use precisely because nothing could reach it
/// — which is exactly the case that should now cost nothing.
#[test]
fn a_hopeless_save_does_not_burn_the_add_die_charge() {
    use crate::actions::class_features::{DARK_ONES_OWN_LUCK_TAG, FAVORED_BY_THE_GODS_TAG};
    use crate::actors::creatures::sorcerers::DIVINE_SOUL_SORCERER_TEMPLATE;
    use crate::actors::creatures::warlocks::FIEND_WARLOCK_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    for (template, tag, label) in [
        (
            &*FIEND_WARLOCK_TEMPLATE,
            DARK_ONES_OWN_LUCK_TAG,
            "dark one's own luck",
        ),
        (
            &*DIVINE_SOUL_SORCERER_TEMPLATE,
            FAVORED_BY_THE_GODS_TAG,
            "favored by the gods",
        ),
    ] {
        let mut e = ei_with_terrain(15, 15, &[]);
        let id = e
            .instantiate_creature(template, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        for seed in 0u64..8 {
            e.roller = FastRandRoller::with_seed(seed);
            let outcome = e.roll_save(id, AbilityScoreType::Wisdom, 100);
            assert!(!outcome.passed(), "DC 100 must fail");
        }
        assert!(
            e.actors[&id].feature_available(tag),
            "{} should still be held after eight unreachable saves",
            label
        );
    }
}

/// FBTG doesn't fire on a passing save — the tag stays untouched.
/// Sibling to `dark_ones_own_luck_does_not_fire_on_passing_save`
/// on the shared add-die cohort.
#[test]
fn favored_by_the_gods_does_not_fire_on_passing_save() {
    use crate::actions::class_features::FAVORED_BY_THE_GODS_TAG;
    use crate::actors::creatures::sorcerers::DIVINE_SOUL_SORCERER_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    let mut e = ei_with_terrain(15, 15, &[]);
    e.roller = FastRandRoller::with_seed(9);
    let id = e
        .instantiate_creature(&DIVINE_SOUL_SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let outcome = e.roll_save(id, AbilityScoreType::Constitution, 0);
    assert!(outcome.passed(), "DC 0 must pass");
    assert!(
        e.actors[&id].feature_available(FAVORED_BY_THE_GODS_TAG),
        "FBTG charge must NOT burn on a passing save"
    );
}

/// FBTG refreshes on a short rest — the tag is in
/// `SHORT_REST_FEATURES` so spending, resting, and re-checking pins
/// the refresh path. Sibling to `dark_ones_own_luck_refreshes_on_short_rest`.
#[test]
fn favored_by_the_gods_refreshes_on_short_rest() {
    use crate::actions::class_features::FAVORED_BY_THE_GODS_TAG;
    use crate::actors::creatures::sorcerers::DIVINE_SOUL_SORCERER_TEMPLATE;
    use crate::engine::dice::FastRandRoller;

    let mut e = ei_with_terrain(15, 15, &[]);
    e.roller = FastRandRoller::with_seed(11);
    let id = e
        .instantiate_creature(&DIVINE_SOUL_SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Burn the charge directly — picking a DC the boost can reach
    // and a seed that fails against it is
    // `favored_by_the_gods_spends_charge_on_failed_save`'s job.
    e.actors
        .get_mut(&id)
        .unwrap()
        .spend_feature(FAVORED_BY_THE_GODS_TAG);
    assert!(!e.actors[&id].feature_available(FAVORED_BY_THE_GODS_TAG));
    let mut roller = FastRandRoller::with_seed(0);
    e.actors.get_mut(&id).unwrap().short_rest(&mut roller);
    assert!(
        e.actors[&id].feature_available(FAVORED_BY_THE_GODS_TAG),
        "short rest must refresh FBTG"
    );
}

/// FBTG can flip a marginal failing save to a pass: uses the same
/// seed-sweep sentinel shape as the DOOL variant. The invariant:
/// if the outer save passed AND the charge is intact, the initial
/// d20 alone cleared the DC (regression sentinel — the failure
/// shape "save passes but charge burnt without a boost being
/// needed" would be the regression).
#[test]
fn favored_by_the_gods_boost_can_convert_fail_to_pass() {
    use crate::actions::class_features::FAVORED_BY_THE_GODS_TAG;
    use crate::actors::creatures::sorcerers::DIVINE_SOUL_SORCERER_TEMPLATE;
    use crate::engine::dice::FastRandRoller;
    use crate::engine::types::AbilityScoreType;

    for seed in 0u64..64 {
        let mut e = ei_with_terrain(15, 15, &[]);
        e.roller = FastRandRoller::with_seed(seed);
        let id = e
            .instantiate_creature(&DIVINE_SOUL_SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Inside the 2d4's reach from every failing face — see
        // `favored_by_the_gods_spends_charge_on_failed_save`.
        let dc = e.actors[&id].save_modifier(AbilityScoreType::Wisdom) + 9;
        let outcome = e.roll_save(id, AbilityScoreType::Wisdom, dc);
        let charge_left = e.actors[&id].feature_available(FAVORED_BY_THE_GODS_TAG);
        let charge_burnt = !charge_left;
        let passed = outcome.passed();
        assert!(
            passed || charge_burnt,
            "seed {}: inconsistent FBTG outcome (passed={} charge_burnt={})",
            seed,
            passed,
            charge_burnt,
        );
    }
}

/// FBTG is registered in `SHORT_REST_FEATURES` — the cohort-list
/// registration is what drives the short-rest refresh, so its
/// absence would silently regress the refresh path even if the
/// tag were still on the template. Sibling of the parallel
/// short-rest registration guard on FANATICAL_FOCUS_TAG.
#[test]
fn favored_by_the_gods_registered_in_short_rest_features() {
    use crate::actions::class_features::{FAVORED_BY_THE_GODS_TAG, SHORT_REST_FEATURES};
    assert!(
        SHORT_REST_FEATURES.contains(&FAVORED_BY_THE_GODS_TAG),
        "FBTG must ride the short-rest refresh cohort"
    );
}

/// Turn the Faithless ships on the Devotion Paladin template with
/// an unspent charge and refreshes on a short rest. Distinct from
/// Turn Undead which stays on long-rest for parity with the other
/// baseline cleric long-rest features.
#[test]
fn turn_the_faithless_ships_on_devotion_paladin_template() {
    use crate::actions::class_features::TURN_THE_FAITHLESS_TAG;
    use crate::actors::creatures::paladins::{DEVOTION_PALADIN_TEMPLATE, PALADIN_TEMPLATE};
    use crate::engine::dice::FastRandRoller;

    let mut e = ei_with_terrain(15, 15, &[]);
    let dev = e
        .instantiate_creature(&DEVOTION_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let baseline = e
        .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(5, 5), 0, 0)
        .unwrap();
    assert!(
        e.actors[&dev].feature_available(TURN_THE_FAITHLESS_TAG),
        "Devotion Paladin ships TURN_THE_FAITHLESS_TAG"
    );
    assert!(
        !e.actors[&baseline].feature_available(TURN_THE_FAITHLESS_TAG),
        "baseline Paladin doesn't ship TURN_THE_FAITHLESS_TAG (subclass CD)"
    );
    // Short-rest refresh: burn the charge manually and verify the
    // short rest picks it up.
    e.actors
        .get_mut(&dev)
        .unwrap()
        .spend_feature(TURN_THE_FAITHLESS_TAG);
    assert!(!e.actors[&dev].feature_available(TURN_THE_FAITHLESS_TAG));
    let mut roller = FastRandRoller::with_seed(0);
    e.actors.get_mut(&dev).unwrap().short_rest(&mut roller);
    assert!(
        e.actors[&dev].feature_available(TURN_THE_FAITHLESS_TAG),
        "short rest must refresh Turn the Faithless"
    );
}

/// Turn the Faithless install: fires only against fey / fiend
/// enemies within 30ft, not undead or humanoids. The action
/// installs Frightened on the on-fail target and leaves other
/// creature types untouched.
#[test]
fn turn_the_faithless_only_targets_fey_and_fiend() {
    use crate::actions::class_features::{TURN_THE_FAITHLESS, TURN_THE_FAITHLESS_TAG};
    use crate::actions::action_template::Action;
    use crate::actors::creatures::goblins::GOBLIN_TEMPLATE; // Humanoid
    use crate::actors::creatures::paladins::DEVOTION_PALADIN_TEMPLATE;
    use crate::actors::creatures::skeletons::SKELETON_TEMPLATE; // Undead
    use crate::actors::creatures::imps::IMP_TEMPLATE; // Fiend
    use crate::engine::dice::FastRandRoller;

    let mut e = ei_with_terrain(20, 20, &[]);
    // Seed picked so all in-radius enemies fail their WIS saves at
    // the paladin's baseline CHA-14-based DC. On any seed where the
    // fiend passes, the fiend won't gain Frightened either — but
    // the humanoid / undead must NEVER pick up the condition
    // regardless of save roll.
    e.roller = FastRandRoller::with_seed(1);
    let dev = e
        .instantiate_creature(&DEVOTION_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let goblin = e
        .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
        .unwrap();
    let skeleton = e
        .instantiate_creature(&SKELETON_TEMPLATE, Coordinate::new(4, 4), 1, 0)
        .unwrap();
    let imp = e
        .instantiate_creature(&IMP_TEMPLATE, Coordinate::new(2, 4), 1, 0)
        .unwrap();
    assert!(e.actors[&dev].feature_available(TURN_THE_FAITHLESS_TAG));
    // Fire the CD via the Action interface directly (side-effects
    // stage; execute() is picker-facing).
    let effects =
        TURN_THE_FAITHLESS.side_effects(&mut e, dev, None, None, None);
    // Apply each side effect so condition installs land.
    for eff in effects {
        eff.apply(&mut e);
    }
    // The humanoid goblin and the undead skeleton are outside the
    // creature-type filter — they must not pick up Frightened
    // regardless of save roll.
    assert!(
        !e.actors[&goblin].has_condition(crate::conditions::Condition::Frightened),
        "humanoid goblin outside the fey/fiend filter — never Frightened"
    );
    assert!(
        !e.actors[&skeleton].has_condition(crate::conditions::Condition::Frightened),
        "undead skeleton outside the fey/fiend filter — Turn Undead handles undead"
    );
    // The imp is a fiend inside the filter; the tag charge is
    // spent regardless of whether it saved. Its Frightened install
    // is seed-dependent (the imp has CHA save proficiency + magic
    // resistance in RAW) but the charge burn is deterministic.
    let _ = imp; // silence unused warning if the imp never picks up frightened
    assert!(
        !e.actors[&dev].feature_available(TURN_THE_FAITHLESS_TAG),
        "Turn the Faithless charge spent"
    );
}

/// 5e Ancients Paladin **Aura of Warding** (lv7): the paladin
/// projects a 10-ft aura (footprint-Chebyshev 4 tiles) that halves
/// spell-typical damage on allies inside. Verifies the aura fires
/// on Fire damage (a spell-typical type) for both the emitter and
/// an adjacent ally.
#[test]
fn aura_of_warding_halves_spell_damage_for_ally_and_emitter() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::paladins::ANCIENTS_PALADIN_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(15, 15, &[]);
    let pal = e
        .instantiate_creature(&ANCIENTS_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Use a Fighter as the ally — 24 HP baseline puts the delta
    // measurement well above the 10-damage threshold so we don't
    // accidentally read a truncated (HP-floor) delta.
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 3), 0, 0)
        .unwrap();
    assert!(e.is_in_aura_of_warding(pal));
    assert!(e.is_in_aura_of_warding(ally));
    // 20 fire → halved to 10 for the ally inside the aura.
    let ally_hp_before = e.actors[&ally].hitpoints();
    DealDamage {
        actor_id: ally,
        amount: 20,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    let ally_hp_after = e.actors[&ally].hitpoints();
    assert_eq!(
        ally_hp_before - ally_hp_after,
        10,
        "ally inside Aura of Warding halves 20 fire → 10"
    );
    // Emitter is covered too — 20 fire → 10.
    let pal_hp_before = e.actors[&pal].hitpoints();
    DealDamage {
        actor_id: pal,
        amount: 20,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    let pal_hp_after = e.actors[&pal].hitpoints();
    assert_eq!(
        pal_hp_before - pal_hp_after,
        10,
        "paladin emitter also benefits from Aura of Warding"
    );
}

/// Aura of Warding only halves spell-typical damage types. Physical
/// (bludgeoning / piercing / slashing) and poison damage pass
/// through at full amount so a nearby ally's greatsword swing
/// doesn't get accidentally shrunk.
#[test]
fn aura_of_warding_does_not_halve_physical_or_poison_damage() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::paladins::ANCIENTS_PALADIN_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(15, 15, &[]);
    let _pal = e
        .instantiate_creature(&ANCIENTS_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 3), 0, 0)
        .unwrap();
    for dt in [
        DamageType::Slashing,
        DamageType::Piercing,
        DamageType::Bludgeoning,
        DamageType::Poison,
    ] {
        // Top the ally up before each iteration so damage lands from
        // a known-good starting HP. `heal` clamps at max HP so a
        // large-number top-up is safe regardless of prior state.
        e.actors.get_mut(&ally).unwrap().heal(999);
        let before = e.actors[&ally].hitpoints();
        DealDamage {
            actor_id: ally,
            amount: 5,
            damage_type: dt,
        }
        .apply(&mut e);
        let after = e.actors[&ally].hitpoints();
        assert_eq!(
            before - after,
            5,
            "Aura of Warding must NOT halve {:?} damage",
            dt
        );
    }
}

/// Aura of Warding is ally-only and range-gated: enemies in range
/// still eat full spell damage; allies far outside the 10ft
/// footprint-Chebyshev radius don't get the halving either.
#[test]
fn aura_of_warding_does_not_cover_enemies_or_distant_allies() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::paladins::ANCIENTS_PALADIN_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
    use crate::engine::types::DamageType;
    let mut e = ei_with_terrain(30, 30, &[]);
    let _pal = e
        .instantiate_creature(&ANCIENTS_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    // Fighter chassis on both far actors — enough HP to absorb the
    // full 10-damage hit cleanly and read a stable delta.
    let enemy_close = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 3), 1, 0)
        .unwrap();
    let ally_far = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(25, 25), 0, 0)
        .unwrap();
    assert!(!e.is_in_aura_of_warding(enemy_close));
    assert!(!e.is_in_aura_of_warding(ally_far));
    // Adjacent enemy — full damage.
    let before = e.actors[&enemy_close].hitpoints();
    DealDamage {
        actor_id: enemy_close,
        amount: 10,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    let after = e.actors[&enemy_close].hitpoints();
    assert_eq!(
        before - after,
        10,
        "enemy in range still eats full spell damage — aura is ally-only"
    );
    // Distant ally — full damage.
    let before = e.actors[&ally_far].hitpoints();
    DealDamage {
        actor_id: ally_far,
        amount: 10,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    let after = e.actors[&ally_far].hitpoints();
    assert_eq!(
        before - after,
        10,
        "ally outside 10ft radius still eats full spell damage"
    );
}

/// Aura of Warding respects the standard "one halving per damage
/// instance" rule: if the ally already has resistance / immunity
/// to the damage type through their own sources, the aura no-ops
/// and the existing pipeline halves once — never twice.
#[test]
fn aura_of_warding_does_not_stack_with_own_resistance() {
    use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
    use crate::actors::creatures::paladins::ANCIENTS_PALADIN_TEMPLATE;
    use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
    use crate::engine::types::{DamageModifier, DamageType};
    let mut e = ei_with_terrain(15, 15, &[]);
    let _pal = e
        .instantiate_creature(&ANCIENTS_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
        .unwrap();
    let ally = e
        .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 3), 0, 0)
        .unwrap();
    // Give the ally template-side fire resistance so their own
    // pipeline halves fire damage once. The aura should NOT layer
    // an extra halving on top.
    e.actors
        .get_mut(&ally)
        .unwrap()
        .set_damage_modifier(DamageType::Fire, DamageModifier::Resistance);
    let before = e.actors[&ally].hitpoints();
    DealDamage {
        actor_id: ally,
        amount: 20,
        damage_type: DamageType::Fire,
    }
    .apply(&mut e);
    let after = e.actors[&ally].hitpoints();
    assert_eq!(
        before - after,
        10,
        "one halving only: template-side resistance already halved; aura no-ops"
    );
}

/// A baseline paladin (non-Ancients) doesn't emit the Aura of
